  Info
} from "lucide-react";
import { cn } from "@/lib/utils";

const BOOKING_STEPS = [
  { id: "dates", label: "Dates", icon: Calendar },
  { id: "members", label: "Members", icon: Users },
  { id: "rooms", label: "Rooms", icon: Bed },
