        <Route component={NotFound} />
    </Switch>
  );

  return (
    <AnimatePresence mode="wait">
      <Suspense fallback={<PageLoader />}>
        {shouldHaveTransition ? (
          <PageTransition key={location}>
            {routesContent}
          </PageTransition>
        ) : (
          routesContent
        )}
      </Suspense>
    </AnimatePresence>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <AuthProvider>
          <ErrorBoundary>
            <WishlistProvider>
              <NavigationHistoryProvider>
                <ScrollToTop />
                <div className="mobile-container">
                  <Toaster />
                  <Router />
                </div>
              </NavigationHistoryProvider>
            </WishlistProvider>
          </ErrorBoundary>
        </AuthProvider>
      </TooltipProvider>
    </QueryClientProvider>
  );
}

export default App;

