                  </div>
                </div>
              </div>
            ))}
          </TabsContent>

          {/* Due Tab */}
          <TabsContent value="due" className="mt-6 space-y-3">
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light mb-3">Upcoming Renewals</p>
            {savedAccounts.map((account) => (
              <div
