                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Trust Footer */}
      <div className="px-4 pt-6 pb-4">
        <div className="bg-white/5 rounded-xl p-4 border border-white/20">
          <div className="flex items-center gap-3">
