              <Shield className="h-5 w-5 text-white" />
            </div>
            <div>
              <p className="text-white/80 font-semibold">RBI Registered NBFC</p>
              <p className="text-white/80 text-sm">License: N-14.01999 • ISO 27001 Certified</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

}

