  const mockLearningPaths: LearningPath[] = [
    {
      id: "path-1",
      title: "Credit Building Mastery",
      description: "Complete guide to building and maintaining excellent credit scores",
      courses: 6,
      totalDuration: "8 hours",
      difficulty: "beginner",
      completionRate: 85,
      enrolled: 12400
