@tailwind base;
@tailwind components;
@tailwind utilities;

/* Global scroll fixes */
html {
  scroll-behavior: smooth;
}

body {
  overflow-x: hidden;
}

/* Fix scroll container behavior */
.scroll-container {
  scroll-behavior: smooth;
  scroll-padding-top: 1rem;
}

/* Ensure all scrollable areas start at top */
.scrollable-content {
  scroll-behavior: smooth;
}

/* Login animations */
@keyframes slideUp {
  from {
    transform: translateY(100%);
  }
  to {
    transform: translateY(0);
  }
}

.animate-slide-up {
  animation: slideUp 0.5s ease-out;
}

@keyframes fadeOut {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.animate-fade-out {
  animation: fadeOut 0.75s ease-out forwards;
}

.animate-fade-in {
  animation: fadeIn 0.75s ease-in forwards;
}

@keyframes logoFloat {
  0% {
    transform: translateY(0) rotate(0deg);
  }
  50% {
    transform: translateY(-8px) rotate(180deg);
  }
  100% {
    transform: translateY(0) rotate(360deg);
  }
}

.animate-logo-float {
  animation: logoFloat 8s ease-in-out infinite;
  filter: drop-shadow(0 0 30px rgba(255, 255, 255, 0.25)) 
          drop-shadow(0 0 60px rgba(255, 255, 255, 0.12))
          drop-shadow(0 0 90px rgba(255, 255, 255, 0.06));
}

/* Bottom Navigation Icon Animations */
@keyframes scanIcon {
  0%, 100% {
    transform: scale(1) rotate(0deg);
  }
  50% {
    transform: scale(1.1) rotate(5deg);
  }
}

.animate-scan-icon {
  animation: scanIcon 2s ease-in-out infinite;
}

@keyframes navIconActive {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.15);
  }
  100% {
    transform: scale(1);
  }
}

.animate-nav-icon-active {
  animation: navIconActive 0.5s ease-out;
}

@keyframes slideDown {
  0% {
    transform: translateX(-50%) scaleX(0);
    opacity: 0;
  }
  100% {
    transform: translateX(-50%) scaleX(1);
    opacity: 1;
  }
}

.animate-slide-down {
  animation: slideDown 0.3s ease-out;
}

@keyframes bubble {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.15);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes fadeInUp {
  0% {
    opacity: 0;
    transform: translateY(10px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Water wave animation for jar fill */
@keyframes wave {
  0%, 100% {
    transform: translateX(-50%) translateY(50%) rotate(0deg);
  }
  50% {
    transform: translateX(-50%) translateY(40%) rotate(180deg);
  }
}

/* Premium Loading Screen Animations - Smooth & Soft */
@keyframes orbitalSweep {
  0% {
    transform: rotate(0deg) scale(1);
    opacity: 0.2;
  }
  50% {
    transform: rotate(180deg) scale(1.02);
    opacity: 0.5;
  }
  100% {
    transform: rotate(360deg) scale(1);
    opacity: 0.2;
  }
}

@keyframes arcPulse {
  0%, 100% {
    transform: scale(1) rotateX(0deg);
    opacity: 0.2;
  }
  50% {
    transform: scale(1.05) rotateX(8deg);
    opacity: 0.4;
  }
}

@keyframes particleDrift {
  0% {
    transform: translate3d(0, 0, 0) scale(0) rotate(0deg);
    opacity: 0;
  }
  25% {
    opacity: 1;
    transform: translate3d(calc(var(--drift-x, 20px) * 0.5), calc(var(--drift-y, -20px) * 0.5), 0) scale(1.1) rotate(var(--rotation, 90deg));
  }
  50% {
    opacity: 1;
    transform: translate3d(calc(var(--drift-x, 20px) * 0.85), calc(var(--drift-y, -20px) * 0.85), 0) scale(1.2) rotate(calc(var(--rotation, 90deg) * 1.8));
  }
  75% {
    opacity: 0.7;
    transform: translate3d(calc(var(--drift-x, 20px) * 1.15), calc(var(--drift-y, -20px) * 1.15), 0) scale(0.9) rotate(calc(var(--rotation, 90deg) * 2.5));
  }
  100% {
    transform: translate3d(calc(var(--drift-x, 20px) * 1.4), calc(var(--drift-y, -20px) * 1.4), 0) scale(0.4) rotate(calc(var(--rotation, 90deg) * 3));
    opacity: 0;
  }
}

@keyframes iconFloat {
  0% {
    transform: rotate(0deg) translateY(0px);
  }
  25% {
    transform: rotate(90deg) translateY(-8px);
  }
  50% {
    transform: rotate(180deg) translateY(0px);
  }
  75% {
    transform: rotate(270deg) translateY(8px);
  }
  100% {
    transform: rotate(360deg) translateY(0px);
  }
}

@keyframes letterReveal {
  0% {
    opacity: 0;
    transform: translateY(10px);
    letter-spacing: 0.3em;
  }
  100% {
    opacity: 1;
    transform: translateY(0);
    letter-spacing: 0.2em;
  }
}

@keyframes radialGlow {
  0%, 100% {
    opacity: 0.2;
  }
  50% {
    opacity: 0.4;
  }
}

@keyframes logoEntrance {
  0% {
    transform: scale(0.7) rotate(-90deg);
    opacity: 0;
  }
  70% {
    transform: scale(1.05) rotate(5deg);
    opacity: 1;
  }
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 1;
  }
}

@keyframes softFadeIn {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

@keyframes softFadeOut {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

.animate-orbital-sweep {
  animation: orbitalSweep 1.4s ease-in-out;
}

.animate-arc-pulse {
  animation: arcPulse 1.8s ease-in-out infinite;
}

.animate-particle-drift {
  animation: particleDrift 3.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  will-change: transform, opacity;
  backface-visibility: hidden;
  perspective: 1000px;
}

.animate-letter-reveal {
  animation: letterReveal 0.7s ease-in-out forwards;
}

.animate-radial-glow {
  animation: radialGlow 2.5s ease-in-out infinite;
}

.animate-logo-entrance {
  animation: logoEntrance 0.7s cubic-bezier(0.25, 0.8, 0.25, 1) forwards;
}

.animate-soft-fade-in {
  animation: softFadeIn 0.5s ease-in forwards;
}

.animate-soft-fade-out {
  animation: softFadeOut 0.5s ease-out forwards;
}

.animate-icon-float {
  animation: iconFloat 3s ease-in-out infinite;
}

/* Noise texture overlay */
.noise-overlay::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.05'/%3E%3C/svg%3E");
  pointer-events: none;
  mix-blend-mode: overlay;
}

/* Radial gradient utility */
.bg-gradient-radial {
  background: radial-gradient(circle, var(--tw-gradient-stops));
}

/* Reduced motion fallback */
@media (prefers-reduced-motion: reduce) {
  .animate-orbital-sweep,
  .animate-arc-pulse,
  .animate-particle-drift,
  .animate-letter-reveal,
  .animate-radial-glow,
  .animate-logo-entrance,
  .animate-icon-float {
    animation: fadeIn 0.5s ease-in forwards;
  }
}

