/* Cred-style Neumorphic Dark Components */

@layer base {
  * {
    @apply border-border;
  }

  html {
    font-size: calc(16px * var(--ui-scale));
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-family: "Plus Jakarta Sans", sans-serif;
  }
}

@layer components {
  /* ===================================================================
     BROWSER COMPATIBILITY - Cross-browser Support & Graceful Degradation
     =================================================================== */

  /* Ensure sticky positioning works across browsers */
  .sticky-polyfill {
    position: -webkit-sticky; /* Safari */
    position: sticky;
  }

  /* @supports queries for graceful degradation */

  /* Backdrop filter support with fallback */
  @supports not ((-webkit-backdrop-filter: blur(10px)) or (backdrop-filter: blur(10px))) {
    .glassmorphic,
    .glassmorphic-red,
    .glassmorphic-green,
    .glassmorphic-blue,
    .glassmorphic-yellow,
    .glassmorphic-purple,
    .glassmorphic-teal,
    .glassmorphic-red-header {
      background: rgba(0, 0, 0, 0.9) !important;
    }
  }

  /* CSS Grid fallback for older browsers */
  @supports not (display: grid) {
    .grid {
      display: flex;
      flex-wrap: wrap;
    }
  }

  /* ===================================================================
     RESPONSIVE DESIGN - Enhanced Mobile/Tablet Support
     =================================================================== */

  /* Prevent images and media from overflowing */
  img, video, svg {
    max-width: 100%;
    height: auto;
  }

  /* Touch-friendly tap targets (minimum 44x44px for accessibility) */
  @media (hover: none) and (pointer: coarse) {
    button, a, input[type="button"], input[type="submit"] {
      min-height: 44px;
      min-width: 44px;
    }
  }

  /* Improve text readability on mobile devices */
  @media (max-width: 640px) {
    body {
      -webkit-text-size-adjust: 100%;
      text-size-adjust: 100%;
    }
  }

  /* Ensure horizontal scrolling is contained */
  .overflow-x-auto {
    -webkit-overflow-scrolling: touch;
  }

  /* ===================================================================
     NEUMORPHIC COMPONENTS
     =================================================================== */

  .neu-card {
    background: var(--card);
    border: 1px solid hsl(220 15% 25%);
    border-radius: 0px;
    box-shadow: 
      8px 8px 16px hsl(220 15% 3%),
      -8px -8px 16px hsl(220 15% 13%),
      inset 1px 1px 2px hsl(0 0% 100% / 0.03);
    transition: all 0.3s ease;
  }

  .neu-card:hover {
    box-shadow: 
      12px 12px 24px hsl(220 15% 2%),
      -12px -12px 24px hsl(220 15% 14%),
      inset 1px 1px 2px hsl(0 0% 100% / 0.05);
    transform: translateY(-2px);
  }

  .neu-card-inset {
    background: var(--card);
    border: 1px solid hsl(220 15% 18%);
    border-radius: 0px;
    box-shadow: 
      inset 4px 4px 8px hsl(220 15% 3%),
      inset -4px -4px 8px hsl(220 15% 13%);
  }

  .neu-button {
    background: var(--card);
    border: 1px solid hsl(220 15% 25%);
    border-radius: 0px;
    box-shadow: 
      4px 4px 8px hsl(220 15% 3%),
      -4px -4px 8px hsl(220 15% 13%);
    transition: all 0.2s ease;
  }

  .neu-button:hover {
    box-shadow: 
      6px 6px 12px hsl(220 15% 2%),
      -6px -6px 12px hsl(220 15% 14%);
    transform: translateY(-1px);
  }

  .neu-button:active {
    box-shadow: 
      inset 2px 2px 4px hsl(220 15% 3%),
      inset -2px -2px 4px hsl(220 15% 13%);
    transform: translateY(0);
  }

  .neu-input {
    background: var(--input);
    border: 1px solid hsl(220 15% 18%);
    border-radius: 0px;
    box-shadow: 
      inset 2px 2px 4px hsl(220 15% 3%),
      inset -2px -2px 4px hsl(220 15% 13%);
  }

  .neu-progress-track {
    background: var(--muted);
    border-radius: 0px;
    box-shadow: 
      inset 2px 2px 4px hsl(220 15% 3%),
      inset -2px -2px 4px hsl(220 15% 13%);
  }

  .neu-progress-fill {
    background: linear-gradient(90deg, hsl(0 0% 95%), hsl(0 0% 85%));
    border-radius: 0px;
    box-shadow: 
      2px 2px 4px hsl(220 15% 3%),
      -1px -1px 2px hsl(220 15% 13%);
  }

  /* Base glassmorphic effects */
  .glassmorphic {
    background: hsl(var(--white) / 0.25);
    @apply backdrop-blur-[10px];
    border: 1px solid hsl(var(--white) / 0.3);
  }

  /* Multi-colored glassmorphic variants using CSS variables */
  .glassmorphic-red {
    background: hsl(220 15% 20% / 0.3);
    @apply backdrop-blur-[10px];
    border: 1px solid hsl(220 15% 20%);
  }

  .glassmorphic-green {
    background: hsl(var(--green-500) / 0.1);
    @apply backdrop-blur-[10px];
    border: 1px solid hsl(var(--green-500) / 0.2);
  }

  .glassmorphic-blue {
    background: hsl(var(--blue-500) / 0.1);
    @apply backdrop-blur-[10px];
    border: 1px solid hsl(var(--blue-500) / 0.2);
  }

  .glassmorphic-yellow {
    background: hsl(var(--yellow-500) / 0.1);
    @apply backdrop-blur-[10px];
    border: 1px solid hsl(var(--yellow-500) / 0.2);
  }

  .glassmorphic-purple {
    background: hsl(var(--purple-500) / 0.1);
    @apply backdrop-blur-[10px];
    border: 1px solid hsl(var(--purple-500) / 0.2);
  }

  .glassmorphic-teal {
    background: hsl(var(--teal-400) / 0.1);
    @apply backdrop-blur-[10px];
    border: 1px solid hsl(var(--teal-400) / 0.2);
  }

  /* Enhanced card variants with gradients using CSS variables */
  .card-gradient-red {
    background: linear-gradient(135deg, hsl(220 15% 20% / 0.4) 0%, hsl(220 15% 10% / 0.8) 100%);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(220 15% 20%);
    color: hsl(0 0% 95%);
  }

  .card-gradient-green {
    background: linear-gradient(135deg, hsl(var(--green-500) / 0.15) 0%, hsl(var(--background-ch) / 0.05) 100%);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--green-500) / 0.3);
    color: hsl(var(--green-foreground));
  }

  .card-gradient-blue {
    background: linear-gradient(135deg, hsl(var(--blue-500) / 0.15) 0%, hsl(var(--background-ch) / 0.05) 100%);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--blue-500) / 0.3);
    color: hsl(var(--blue-foreground));
  }

  .card-gradient-yellow {
    background: linear-gradient(135deg, hsl(var(--yellow-500) / 0.15) 0%, hsl(var(--background-ch) / 0.05) 100%);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--yellow-500) / 0.3);
    color: hsl(var(--yellow-foreground));
  }

  .card-gradient-purple {
    background: linear-gradient(135deg, hsl(var(--purple-500) / 0.15) 0%, hsl(var(--background-ch) / 0.05) 100%);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--purple-500) / 0.3);
    color: hsl(var(--purple-foreground));
  }

  .card-gradient-teal {
    background: linear-gradient(135deg, hsl(var(--teal-400) / 0.15) 0%, hsl(var(--background-ch) / 0.05) 100%);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--teal-400) / 0.3);
    color: hsl(var(--teal-foreground));
  }

  /* Premium gradient cards with proper foreground colors */
  .card-premium {
    background: var(--premium-gradient);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--purple-500) / 0.3);
    color: hsl(var(--premium-foreground));
  }

  .card-success {
    background: var(--success-gradient);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--green-500) / 0.3);
    color: hsl(var(--success-foreground));
  }

  .card-warning {
    background: var(--warning-gradient);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--yellow-500) / 0.3);
    color: hsl(var(--warning-foreground));
  }

  .card-info {
    background: var(--info-gradient);
    @apply backdrop-blur-[15px];
    border: 1px solid hsl(var(--blue-500) / 0.3);
    color: hsl(var(--info-foreground));
  }

  /* Dark mode overrides for glassmorphic variants */
  .dark .glassmorphic-red {
    background: hsl(220 15% 20% / 0.4);
    border: 1px solid hsl(220 15% 20%);
  }

  .dark .glassmorphic-green {
    background: hsl(var(--green-500) / 0.15);
    border: 1px solid hsl(var(--green-500) / 0.3);
  }

  .dark .glassmorphic-blue {
    background: hsl(var(--blue-500) / 0.15);
    border: 1px solid hsl(var(--blue-500) / 0.3);
  }

  .dark .glassmorphic-yellow {
    background: hsl(var(--yellow-500) / 0.15);
    border: 1px solid hsl(var(--yellow-500) / 0.3);
  }

  .dark .glassmorphic-purple {
    background: hsl(var(--purple-500) / 0.15);
    border: 1px solid hsl(var(--purple-500) / 0.3);
  }

  .dark .glassmorphic-teal {
    background: hsl(var(--teal-400) / 0.15);
    border: 1px solid hsl(var(--teal-400) / 0.3);
  }

  .dark .card-gradient-red {
    background: linear-gradient(135deg, hsl(220 15% 20% / 0.5) 0%, hsl(220 15% 10% / 0.9) 100%);
    border: 1px solid hsl(220 15% 20%);
  }

  .dark .card-gradient-green {
    background: linear-gradient(135deg, hsl(var(--green-500) / 0.2) 0%, hsl(var(--background-ch) / 0.1) 100%);
    border: 1px solid hsl(var(--green-500) / 0.4);
  }

  .dark .card-gradient-blue {
    background: linear-gradient(135deg, hsl(var(--blue-500) / 0.2) 0%, hsl(var(--background-ch) / 0.1) 100%);
    border: 1px solid hsl(var(--blue-500) / 0.4);
  }

  .dark .card-gradient-yellow {
    background: linear-gradient(135deg, hsl(var(--yellow-500) / 0.2) 0%, hsl(var(--background-ch) / 0.1) 100%);
    border: 1px solid hsl(var(--yellow-500) / 0.4);
  }

  .dark .card-gradient-purple {
    background: linear-gradient(135deg, hsl(var(--purple-500) / 0.2) 0%, hsl(var(--background-ch) / 0.1) 100%);
    border: 1px solid hsl(var(--purple-500) / 0.4);
