  .dark .card-gradient-teal {
    background: linear-gradient(135deg, hsl(var(--teal-400) / 0.2) 0%, hsl(var(--background-ch) / 0.1) 100%);
    border: 1px solid hsl(var(--teal-400) / 0.4);
  }

  /* Dark mode variants for enhanced 3D styles */
  .dark .card-3d-enhanced {
    background: linear-gradient(135deg, hsl(var(--background-ch) / 0.98) 0%, hsl(var(--gray-800) / 0.95) 100%);
    border: 1px solid hsl(var(--gray-700) / 0.8);
    box-shadow: 
      0 2px 4px 0 hsl(var(--black) / 0.2),
      0 4px 8px 0 hsl(var(--black) / 0.15),
      0 8px 16px 0 hsl(var(--black) / 0.1),
      inset 0 1px 0 hsl(var(--white) / 0.1);
