import { useState, useMemo } from "react";
import { useLocation } from "wouter";
import { useNavigationHistory } from "@/hooks/use-navigation-history";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { 
  ArrowLeft,
  Phone,
  MessageCircle,
  Mail,
  Clock,
  User,
  Headphones,
  FileQuestion,
  MessageSquare,
  ExternalLink,
  Search,
  CheckCircle,
  AlertCircle,
  HelpCircle,
  BookOpen,
  Video,
  FileText,
  Shield
} from "lucide-react";
import { useUrlTab } from "@/hooks/use-url-tab";

interface SupportOption {
  id: string;
  title: string;
  description: string;
  icon: any;
  action: () => void;
  category: "contact" | "help" | "emergency";
  availability?: string;
  isAvailable?: boolean;
}

export default function Support() {
  const [, navigate] = useLocation();
  const { goBack } = useNavigationHistory();
  const [selectedTab, setSelectedTab] = useUrlTab("overview");
  const [searchQuery, setSearchQuery] = useState("");

  const handleWhatsAppSupport = () => {
    window.open("https://wa.me/918547258015?text=Hello%20Kcredit%20Support", "_blank");
  };

  const handleCall = () => {
    window.open("tel:+918547258015");
  };

  const handleEmail = () => {
    window.open("mailto:support@kcredit.com");
  };

  const handleEmergencyCall = () => {
    window.open("tel:+911800123456");
  };

  const supportOptions: SupportOption[] = [
    {
      id: "whatsapp",
      title: "WhatsApp Support",
      description: "Chat with us on WhatsApp for instant help",
      icon: MessageCircle,
      action: handleWhatsAppSupport,
      category: "contact",
      availability: "24/7",
      isAvailable: true
    },
    {
      id: "call",
      title: "Call Support",
      description: "+91-8547258015",
      icon: Phone,
      action: handleCall,
      category: "contact",
      availability: "Mon-Sat, 9AM-6PM",
      isAvailable: true
    },
    {
      id: "email",
      title: "Email Support",
      description: "support@kcredit.com",
      icon: Mail,
      action: handleEmail,
      category: "contact",
      availability: "Response within 24 hrs",
      isAvailable: true
    },
    {
      id: "faq",
      title: "FAQs",
      description: "Find answers to common questions",
      icon: FileQuestion,
      action: () => {},
      category: "help",
      isAvailable: true
    },
    {
      id: "live-chat",
      title: "Live Chat",
      description: "Chat with our support team",
      icon: MessageSquare,
      action: () => {},
      category: "help",
      availability: "Mon-Sat, 9AM-6PM",
      isAvailable: true
    },
    {
      id: "video-call",
      title: "Video Call Support",
      description: "Schedule a video call with expert",
      icon: Video,
      action: () => {},
      category: "help",
      availability: "By appointment",
      isAvailable: false
    },
    {
      id: "help-center",
      title: "Help Center",
      description: "Browse our knowledge base",
      icon: BookOpen,
      action: () => {},
      category: "help",
      isAvailable: true
    },
    {
      id: "loan-docs",
      title: "Loan Documents",
      description: "Access loan-related documents",
      icon: FileText,
      action: () => {},
      category: "help",
      isAvailable: true
    },
    {
      id: "fraud-alert",
      title: "Report Fraud",
      description: "Report suspicious activity",
      icon: Shield,
      action: () => {},
      category: "emergency",
      availability: "24/7",
      isAvailable: true
    },
    {
      id: "emergency",
      title: "Emergency Helpline",
      description: "1800-123-456 (24/7)",
      icon: Headphones,
      action: handleEmergencyCall,
      category: "emergency",
      availability: "24/7",
      isAvailable: true
    }
  ];

  const filteredOptions = useMemo(() => {
    let optionsToFilter: SupportOption[] = [];

    switch (selectedTab) {
      case "contact":
        optionsToFilter = supportOptions.filter(opt => opt.category === "contact");
        break;
      case "help":
        optionsToFilter = supportOptions.filter(opt => opt.category === "help");
        break;
      case "emergency":
        optionsToFilter = supportOptions.filter(opt => opt.category === "emergency");
        break;
      case "overview":
