    });
  };

  const getTierIcon = (tier: string) => {
    switch (tier) {
      case "Gold": return Crown;
      case "Platinum": return Trophy;
      case "Silver": return Award;
      default: return Star;
    }
  };

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Header */}
