import type { Request, Response, NextFunction } from "express";
import { verifyToken, extractTokenFromRequest } from "../jwt";

// Rate limiting store - in production should use Redis
const rateLimitStore = new Map<string, { count: number; resetTime: number }>();

// Rate limiting configuration
const RATE_LIMIT_CONFIG = {
  OTP_GENERATION: { maxAttempts: 3, windowMs: 15 * 60 * 1000 }, // 3 OTP generation attempts per 15 minutes
  OTP_VERIFICATION: { maxAttempts: 5, windowMs: 15 * 60 * 1000 }, // 5 attempts per 15 minutes
  LOAN_APPLICATION: { maxAttempts: 3, windowMs: 60 * 60 * 1000 }, // 3 attempts per hour
  GENERAL_API: { maxAttempts: 100, windowMs: 15 * 60 * 1000 }, // 100 requests per 15 minutes
  UPI_PAYMENT: { maxAttempts: 20, windowMs: 15 * 60 * 1000 }, // 20 UPI payments per 15 minutes
  UPI_COLLECT: { maxAttempts: 10, windowMs: 15 * 60 * 1000 }, // 10 collect requests per 15 minutes
  UPI_BILL_PAYMENT: { maxAttempts: 15, windowMs: 15 * 60 * 1000 }, // 15 bill payments per 15 minutes
  UPI_EMI_PAYMENT: { maxAttempts: 5, windowMs: 60 * 60 * 1000 }, // 5 EMI payments per hour
  BOOKING_CREATION: { maxAttempts: 10, windowMs: 15 * 60 * 1000 }, // 10 bookings per 15 minutes
  HOLD_CREATION: { maxAttempts: 20, windowMs: 15 * 60 * 1000 }, // 20 hold attempts per 15 minutes
  CARD_CREATION: { maxAttempts: 5, windowMs: 60 * 60 * 1000 }, // 5 card creations per hour
  REVIEW_CREATION: { maxAttempts: 10, windowMs: 15 * 60 * 1000 }, // 10 reviews per 15 minutes
};

// Get client identifier (IP + User-Agent)
function getClientId(req: Request): string {
  const ip = req.ip || req.connection.remoteAddress || 'unknown';
  const userAgent = req.headers['user-agent'] || 'unknown';
  return `${ip}:${Buffer.from(userAgent).toString('base64').slice(0, 20)}`;
}

// Rate limiting middleware
export function createRateLimiter(type: keyof typeof RATE_LIMIT_CONFIG) {
  return (req: Request, res: Response, next: NextFunction) => {
    const clientId = getClientId(req);
    const key = `${type}:${clientId}`;
    const config = RATE_LIMIT_CONFIG[type];
    const now = Date.now();

    let record = rateLimitStore.get(key);

    // Reset if window has expired
    if (!record || now > record.resetTime) {
      record = { count: 0, resetTime: now + config.windowMs };
    }

    record.count++;
    rateLimitStore.set(key, record);

    if (record.count > config.maxAttempts) {
      const retryAfter = Math.ceil((record.resetTime - now) / 1000);
      res.set('Retry-After', retryAfter.toString());
      return res.status(429).json({
        success: false,
        message: `Too many requests. Please try again in ${Math.ceil(retryAfter / 60)} minutes.`,
        retryAfter
      });
    }

    // Add rate limit headers
    res.set({
      'X-RateLimit-Limit': config.maxAttempts.toString(),
      'X-RateLimit-Remaining': Math.max(0, config.maxAttempts - record.count).toString(),
      'X-RateLimit-Reset': new Date(record.resetTime).toISOString()
    });

    next();
  };
}

// Security headers middleware
export function securityHeaders(req: Request, res: Response, next: NextFunction) {
  // Environment-aware Content Security Policy
  const isDevelopment = process.env.NODE_ENV === 'development';

  const cspDirectives = [
    "default-src 'self'",
    isDevelopment 
      ? "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://replit.com"
      : "script-src 'self' https://replit.com",
    isDevelopment
      ? "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com"
      : "style-src 'self' https://fonts.googleapis.com",
    "font-src 'self' https://fonts.gstatic.com",
    "img-src 'self' data: https:",
    "connect-src 'self' https://api.openai.com wss: ws:",
    "frame-ancestors 'none'"
  ];

  res.set('Content-Security-Policy', cspDirectives.join('; '));

  // Security headers
  res.set({
    'X-Content-Type-Options': 'nosniff',
    'X-Frame-Options': 'DENY',
    'X-XSS-Protection': '1; mode=block',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Permissions-Policy': 'camera=(), microphone=(), location=(), payment=()',
    'Strict-Transport-Security': 'max-age=31536000; includeSubDomains'
  });

  next();
}

// Enhanced error handler
export function enhancedErrorHandler(err: any, req: Request, res: Response, next: NextFunction) {
  // Log error details for debugging (without sensitive data)
  const errorLog = {
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    status: err.status || 500,
    message: err.message,
    userAgent: req.headers['user-agent'],
    ip: req.ip
  };

  // In production, send to logging service
  console.error('API Error:', errorLog);

  // Sanitize error response
  const status = err.status || err.statusCode || 500;
  let message = 'An unexpected error occurred. Please try again.';

  // Only expose specific error types to client
  if (status === 400) {
    message = err.message || 'Invalid request data';
  } else if (status === 401) {
    message = 'Authentication required';
  } else if (status === 403) {
    message = 'Access forbidden';
  } else if (status === 404) {
    message = 'Resource not found';
  } else if (status === 429) {
    message = err.message || 'Too many requests';
  }

  res.status(status).json({
    success: false,
    message,
    timestamp: new Date().toISOString(),
    requestId: req.headers['x-request-id'] || generateRequestId()
  });
}

// Request ID generator
function generateRequestId(): string {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

// Request ID middleware
export function requestIdMiddleware(req: Request, res: Response, next: NextFunction) {
  req.headers['x-request-id'] = req.headers['x-request-id'] || generateRequestId();
  res.set('X-Request-ID', req.headers['x-request-id'] as string);
  next();
}

// Input sanitization middleware
export function sanitizeInput(req: Request, res: Response, next: NextFunction) {
  // Basic input sanitization for strings
  const sanitizeValue = (value: any): any => {
    if (typeof value === 'string') {
      // Remove potential XSS patterns
      return value
        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/javascript:/gi, '')
        .replace(/on\w+=/gi, '')
        .trim();
    } else if (typeof value === 'object' && value !== null) {
      const sanitized: any = Array.isArray(value) ? [] : {};
      for (const key in value) {
        sanitized[key] = sanitizeValue(value[key]);
      }
      return sanitized;
    }
    return value;
  };

  if (req.body) {
    req.body = sanitizeValue(req.body);
  }

  next();
}

// Authentication middleware
export function requireAuth(req: Request, res: Response, next: NextFunction) {
  const token = extractTokenFromRequest(req);

  if (!token) {
    return res.status(401).json({
      success: false,
      message: 'Authentication required. Please log in.'
    });
  }

  const payload = verifyToken(token);

  if (!payload) {
    return res.status(401).json({
      success: false,
      message: 'Invalid or expired token. Please log in again.'
    });
  }

  // Add user info to request for use in route handlers
  req.user = { 
    id: payload.userId,
    phone: payload.phone 
  };
  next();
}

// Optional authentication middleware - populates req.user if token exists, but doesn't fail if missing
export function optionalAuth(req: Request, res: Response, next: NextFunction) {
  const token = extractTokenFromRequest(req);

  if (token) {
    const payload = verifyToken(token);

    if (payload) {
      // Add user info to request if valid token exists
      req.user = { 
        id: payload.userId,
        phone: payload.phone 
      };
    }
  }

  // Continue regardless of authentication status
  next();
}

// Extend Request type
declare global {
  namespace Express {
    interface Request {
      user?: { id: string; phone?: string };
    }
  }
}

