import { useState, useMemo, useEffect } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { ALL_STOCKS, STOCK_DOMAINS, getStocksByDomain } from "@/data/stocks-data";
import { MiniStockChart } from "@/components/ui/mini-stock-chart";
import { usePagination } from "@/hooks/use-pagination";
import { useNavigationHistory } from "@/hooks/use-navigation-history";
import { PaginationControls } from "@/components/ui/pagination-controls";
import { 
  ArrowLeft,
  Search,
  TrendingUp,
  TrendingDown,
  Star,
  BarChart3,
  Plus
} from "lucide-react";

// Generate stock price history for visualization (deterministic based on symbol)
const generatePriceHistory = (symbol: string, currentPrice: number, change: number) => {
  const points = 20;
  const data: number[] = [];

  // Calculate the previous price based on the change percentage
  const previousPrice = currentPrice / (1 + change / 100);
  const priceDiff = currentPrice - previousPrice;

  // Use symbol hash for consistent randomness
  const seed = symbol.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  const seededRandom = (index: number) => {
    const x = Math.sin(seed + index) * 10000;
    return x - Math.floor(x);
  };

  for (let i = 0; i < points; i++) {
    const progress = i / (points - 1);
    const basePrice = previousPrice + (priceDiff * progress);
    const randomVariation = (seededRandom(i) - 0.5) * currentPrice * 0.015;
    data.push(basePrice + randomVariation);
  }

  // Ensure last point is exactly the current price
  data[data.length - 1] = currentPrice;

  return data;
};

export default function StocksList() {
  const [, navigate] = useLocation();
  const { goBack } = useNavigationHistory();
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedDomain, setSelectedDomain] = useState("holdings");
  const [watchlist] = useState<string[]>(["RELIANCE", "TCS", "HDFCBANK", "INFY", "SBIN"]);
  const [liveStocks, setLiveStocks] = useState(ALL_STOCKS);

  // Update stock prices every 1 second to simulate live data
  useEffect(() => {
    const interval = setInterval(() => {
      setLiveStocks(prevStocks => prevStocks.map(stock => {
        const randomChange = (Math.random() - 0.5) * 0.5;
        const newChange = stock.change + randomChange;
        const newPrice = stock.price * (1 + randomChange / 100);

        return {
          ...stock,
          price: Math.round(newPrice * 100) / 100,
          change: Math.round(newChange * 100) / 100
        };
      }));
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const filteredStocks = useMemo(() => {
    let stocks = selectedDomain === "holdings" || selectedDomain === "watchlist"
      ? liveStocks.filter(stock => watchlist.includes(stock.symbol))
      : liveStocks.filter(stock => {
          const domain = STOCK_DOMAINS.find(d => d.id === selectedDomain);
          return domain ? stock.domain === selectedDomain : false;
        });

    if (searchQuery) {
      const lowerQuery = searchQuery.toLowerCase();
      stocks = stocks.filter(stock =>
        stock.name.toLowerCase().includes(lowerQuery) ||
        stock.symbol.toLowerCase().includes(lowerQuery)
      );
    }

    return stocks;
  }, [selectedDomain, searchQuery, watchlist, liveStocks]);

  const pagination = usePagination({
    data: filteredStocks,
    itemsPerPage: 20,
  });

  // Calculate holding stats
  const holdingStats = useMemo(() => {
    const holdings = ALL_STOCKS.filter(stock => watchlist.includes(stock.symbol));
    const totalValue = holdings.reduce((sum, stock) => sum + stock.price * 10, 0); // Assume 10 shares each
    const totalChange = holdings.reduce((sum, stock) => sum + (stock.price * 10 * stock.change / 100), 0);
    const changePercent = (totalChange / (totalValue - totalChange)) * 100;

    return {
      totalValue: totalValue.toFixed(2),
      totalChange: totalChange.toFixed(2),
      changePercent: changePercent.toFixed(2),
      holdings: holdings.length
    };
  }, [watchlist]);

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between p-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={goBack}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>

          <h1 className="text-lg font-bold tracking-wider uppercase">Stocks</h1>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/investment/stocks/add")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-add-stock"
          >
            <Plus className="h-5 w-5" />
          </Button>
        </div>

        {/* Holdings Stats */}
        <div className="px-6 pb-4">
          <div className="relative border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-6" data-testid="stocks-summary">
            <div className="space-y-6">
              {/* Total Portfolio Display */}
              <div className="space-y-2">
                <p className="text-xs text-white/50 uppercase tracking-widest font-light">Portfolio Value</p>
                <p className="text-4xl font-light text-white tracking-tight" data-testid="text-total-portfolio">
                  ₹{Number(holdingStats.totalValue).toLocaleString()}
                </p>
              </div>

              {/* Quick Stats Grid */}
              <div className="grid grid-cols-3 gap-3 pt-4 border-t border-white/10">
                <div className="space-y-1 text-center">
                  <p className="text-lg font-light text-white" data-testid="text-holdings-count">
                    {holdingStats.holdings}
                  </p>
                  <p className="text-[10px] text-white/50 uppercase tracking-widest">Holdings</p>
                </div>
                <div className="space-y-1 text-center">
                  <p className={cn(
                    "text-lg font-light",
                    Number(holdingStats.changePercent) >= 0 ? "text-green-400" : "text-red-400"
                  )} data-testid="text-todays-change">
                    {Number(holdingStats.changePercent) >= 0 ? "+" : ""}{holdingStats.changePercent}%
                  </p>
                  <p className="text-[10px] text-white/50 uppercase tracking-widest">Today's Change</p>
                </div>
                <div className="space-y-1 text-center">
                  <p className={cn(
                    "text-lg font-light",
                    Number(holdingStats.changePercent) >= 0 ? "text-green-400" : "text-red-400"
                  )} data-testid="text-todays-pnl">
                    {Number(holdingStats.changePercent) >= 0 ? "+" : ""}₹{holdingStats.totalChange}
                  </p>
                  <p className="text-[10px] text-white/50 uppercase tracking-widest">P&L</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Search Bar */}
        <div className="px-6 pb-4">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/40" />
            <Input
              placeholder="Search stocks by name or symbol..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="bg-transparent border-0 border-b-2 border-white/20 text-white pl-11 rounded-none h-12 focus:border-white placeholder:text-white/30"
              data-testid="input-search-stocks"
            />
          </div>
        </div>

        {/* Domain Filters - Horizontal Scrollable */}
        <div className="px-6 py-2 overflow-x-auto scrollbar-hide flex items-center">
          <div className="flex items-center gap-2 min-w-max">
            <Button
              variant={selectedDomain === "holdings" ? "default" : "outline"}
              size="sm"
              onClick={() => setSelectedDomain("holdings")}
              className={cn(
                "whitespace-nowrap rounded-none",
                selectedDomain === "holdings"
                  ? "bg-white text-black hover:bg-white/90"
                  : "bg-white/5 border-white/20 text-white hover:bg-white/10"
              )}
              data-testid="filter-domain-holdings"
            >
              Holdings ({watchlist.length})
            </Button>
            <Button
              variant={selectedDomain === "watchlist" ? "default" : "outline"}
              size="sm"
              onClick={() => setSelectedDomain("watchlist")}
              className={cn(
                "whitespace-nowrap rounded-none",
                selectedDomain === "watchlist"
                  ? "bg-white text-black hover:bg-white/90"
                  : "bg-white/5 border-white/20 text-white hover:bg-white/10"
              )}
              data-testid="filter-domain-watchlist"
            >
              <Star className="h-3 w-3 mr-1" />
              Watchlist ({watchlist.length})
            </Button>
            {STOCK_DOMAINS.map((domain) => (
              <Button
                key={domain.id}
                variant={selectedDomain === domain.id ? "default" : "outline"}
                size="sm"
                onClick={() => setSelectedDomain(domain.id)}
                className={cn(
                  "whitespace-nowrap rounded-none",
                  selectedDomain === domain.id
                    ? "bg-white text-black hover:bg-white/90"
                    : "bg-white/5 border-white/20 text-white hover:bg-white/10"
                )}
                data-testid={`filter-domain-${domain.id}`}
              >
                {domain.label} {domain.count > 0 && `(${domain.count})`}
              </Button>
            ))}
          </div>
        </div>
      </div>

      <div className="pt-[360px] px-4">
        {/* Stocks Grid */}
        <div className="space-y-1">
          {pagination.paginatedData.map((stock) => (
            <div
              key={stock.symbol}
              className="border border-white/10 p-4 bg-white/5 hover:bg-white/10 transition-colors cursor-pointer"
              onClick={() => navigate(`/stocks/${stock.symbol}`)}
              data-testid={`card-stock-${stock.symbol}`}
            >
              <div className="flex items-center justify-between gap-4">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-3 mb-2">
                    <h3 className="font-semibold text-white">{stock.symbol}</h3>
                    <Badge className="bg-white/10 text-white border-white/20 text-xs rounded-none font-light">
                      {STOCK_DOMAINS.find(d => d.id === stock.domain)?.label || stock.domain}
                    </Badge>
                  </div>
                  <p className="text-sm text-white/60 mb-2 truncate">{stock.name}</p>
                  <div className="flex items-center gap-4 text-xs text-white/50">
                    <span className="flex items-center gap-1">
                      <BarChart3 className="h-3 w-3" />
                      {stock.marketCap}
                    </span>
                    <span>Vol: {stock.volume}</span>
                  </div>
                </div>

                {/* Mini Chart */}
                <div className="flex-shrink-0">
                  <MiniStockChart 
                    data={generatePriceHistory(stock.symbol, stock.price, stock.change)} 
                    change={stock.change}
                    height={40}
                  />
                </div>

                <div className="text-right flex-shrink-0">
                  <p className="text-xl font-light text-white mb-2">₹{stock.price.toLocaleString()}</p>
                  <div className={cn(
                    "flex items-center gap-1 justify-end mb-2",
                    stock.change >= 0 ? "text-green-500" : "text-red-500"
                  )}>
                    {stock.change >= 0 ? <TrendingUp className="h-4 w-4" /> : <TrendingDown className="h-4 w-4" />}
                    <span className="text-sm font-light">
                      {stock.change >= 0 ? "+" : ""}{stock.change.toFixed(2)}%
                    </span>
                  </div>
                  <Button
                    size="sm"
                    variant="ghost"
                    className={cn(
                      "h-8 rounded-none",
                      watchlist.includes(stock.symbol) 
                        ? "text-white/80 hover:text-white/70 hover:bg-white/5" 
                        : "text-white/60 hover:text-white hover:bg-white/10"
                    )}
                    onClick={(e) => {
                      e.stopPropagation();
                      // TODO: Add to watchlist
                    }}
                    data-testid={`button-watchlist-${stock.symbol}`}
                  >
                    <Star className={cn("h-4 w-4", watchlist.includes(stock.symbol) && "fill-current")} />
                  </Button>
                </div>
              </div>
            </div>
          ))}

          {filteredStocks.length === 0 && (
            <div className="text-center py-12">
              <BarChart3 className="h-12 w-12 text-white/20 mx-auto mb-3" />
              <p className="text-white/60 mb-2">No stocks found</p>
              <p className="text-sm text-white/40">Try adjusting your search or filter</p>
            </div>
          )}
        </div>

        <PaginationControls
          currentPage={pagination.currentPage}
          totalPages={pagination.totalPages}
          onPageChange={pagination.goToPage}
          canGoNext={pagination.canGoNext}
          canGoPrevious={pagination.canGoPrevious}
          startIndex={pagination.startIndex}
          endIndex={pagination.endIndex}
          totalItems={pagination.totalItems}
          className="mb-6"
        />
      </div>
    </div>
  );
}

client/src/pages/booking/metro/results.t.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Train,
  ArrowLeft,
  Clock,
  MapPin,
  TrendingUp,
  Ticket,
  ArrowRight,
  Zap,
  Star
} from "lucide-react";
import { format, addDays } from "date-fns";
import { cn } from "@/lib/utils";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";

interface MetroRoute {
  id: string;
  name: string;
  from: string;
  to: string;
  line: string;
  duration: string;
  stops: number;
  fare: number;
  type: 'route' | 'pass';
  express?: boolean;
  rating?: number;
}

const mockRoutes: MetroRoute[] = [
  {
    id: "1",
    name: "Direct Route",
    from: "Rajiv Chowk",
    to: "Huda City Center",
    line: "Yellow Line",
    duration: "35 min",
    stops: 15,
    fare: 50,
    type: 'route',
    rating: 4.8
  },
  {
    id: "2",
    name: "Express Route",
    from: "Rajiv Chowk",
    to: "Huda City Center",
    line: "Yellow Line",
    duration: "28 min",
    stops: 8,
    fare: 65,
    type: 'route',
    express: true,
    rating: 4.9
  }
];

const featuredPasses = [
  { id: "pass-1", name: "Day Pass", validity: "24 hours", fare: 200, description: "Unlimited travel" },
  { id: "pass-2", name: "Week Pass", validity: "7 days", fare: 800, description: "Unlimited travel" },
  { id: "pass-3", name: "Month Pass", validity: "30 days", fare: 2500, description: "Unlimited travel" }
];

export default function MetroResults() {
  const [, navigate] = useLocation();
  const params = new URLSearchParams(window.location.search);

  const from = params.get("from") || "Rajiv Chowk";
  const to = params.get("to") || "Huda City Center";
  const initialDate = params.get("date") || format(new Date(), "yyyy-MM-dd");
  const passengers = parseInt(params.get("passengers") || "1");

  const [selectedDate, setSelectedDate] = useState(initialDate);
  const [routeFilter, setRouteFilter] = useState("all");

  const generateDateTabs = () => {
    const baseDate = new Date(initialDate);
    const dates = [];
    for (let i = 0; i <= 6; i++) {
      const date = addDays(baseDate, i);
      dates.push({
        date: format(date, "yyyy-MM-dd"),
        day: format(date, "EEE"),
        dayNum: format(date, "dd"),
        month: format(date, "MMM")
      });
    }
    return dates;
  };

  const dateTabs = generateDateTabs();

  const filteredRoutes = mockRoutes.filter(route => {
    if (routeFilter === "express") return route.express;
    if (routeFilter === "direct") return !route.express;
    return true;
  });

  const pagination = usePagination({
    data: filteredRoutes,
    itemsPerPage: 10,
  });

  const handleSelectRoute = (routeId: string) => {
    navigate(`/booking/metro/${selectedDate}/${routeId}`);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0
    }).format(amount);
  };

  return (
    <div className="min-h-screen bg-black text-white pb-24">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/booking/metro/search")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider uppercase">Available Routes</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">
              {from} → {to}
            </p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      <div className="pt-24 px-4 space-y-4 w-full max-w-screen-lg mx-auto">
        {/* Date Selection Tab Bar */}
        <div className="border border-white/20 bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-xl p-3">
          <div className="flex items-center gap-2 overflow-x-auto no-scrollbar">
            {dateTabs.map((dateTab) => (
              <button
                key={dateTab.date}
                onClick={() => setSelectedDate(dateTab.date)}
                className={cn(
                  "flex-shrink-0 px-4 py-3 border transition-all rounded-none min-w-[80px]",
                  selectedDate === dateTab.date
                    ? "bg-white text-black border-white"
                    : "bg-white/5 text-white/60 border-white/20 hover:border-white/40"
                )}
                data-testid={`button-date-${dateTab.date}`}
              >
                <div className="flex flex-col items-center gap-1">
                  <span className="text-[10px] uppercase tracking-wider font-light">{dateTab.day}</span>
                  <span className="text-xl font-light">{dateTab.dayNum}</span>
                  <span className="text-[10px] uppercase tracking-wider font-light">{dateTab.month}</span>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Route Filter Tabs */}
        <Tabs value={routeFilter} onValueChange={setRouteFilter} className="w-full">
          <TabsList className="bg-transparent border-b border-white/10 w-full h-auto p-0 rounded-none grid grid-cols-3 gap-0">
            <TabsTrigger 
              value="all" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent"
              data-testid="tab-all-routes"
            >
              All Routes
            </TabsTrigger>
            <TabsTrigger 
              value="express" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent"
              data-testid="tab-express-routes"
            >
              Express
            </TabsTrigger>
            <TabsTrigger 
              value="direct" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent"
              data-testid="tab-direct-routes"
            >
              Direct
            </TabsTrigger>
          </TabsList>
        </Tabs>

        {/* Featured Passes - Cardless Design */}
        <div className="border-b-2 border-white/20 pb-6">
          <div className="flex items-center gap-2 mb-4">
            <TrendingUp className="h-4 w-4 text-white" />
            <h3 className="text-sm font-light tracking-wider text-white uppercase">Featured Passes</h3>
          </div>
          <div className="grid grid-cols-3 gap-3">
            {featuredPasses.map((pass) => (
              <button
                key={pass.id}
                onClick={() => handleSelectRoute(pass.id)}
                className="p-4 border border-white/20 hover:border-white/40 transition-all bg-white/5 hover:bg-white/10"
                data-testid={`pass-${pass.id}`}
              >
                <div className="text-center space-y-2">
                  <Ticket className="h-6 w-6 text-white/60 mx-auto" />
                  <p className="text-xs font-light text-white">{pass.name}</p>
                  <p className="text-lg font-light text-white">{formatCurrency(pass.fare)}</p>
                  <p className="text-[10px] text-white/60 uppercase tracking-wider">{pass.validity}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Metro Routes List - Card Based */}
        {pagination.paginatedData.map((route) => (
          <div
            key={route.id}
            onClick={() => handleSelectRoute(route.id)}
            className="border border-white/20 bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-xl p-6 hover:border-white/40 transition-all cursor-pointer"
            data-testid={`route-card-${route.id}`}
          >
            <div className="space-y-4">
              {/* Route Header */}
              <div className="flex items-start justify-between">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="text-lg font-light text-white tracking-wider">{route.name}</h3>
                    {route.express && (
                      <Badge className="bg-white/20 text-white border-white/30 rounded-none font-light text-[10px] px-2 py-0.5">
                        <Zap className="h-3 w-3 mr-1" />
                        EXPRESS
                      </Badge>
                    )}
                  </div>
                  <p className="text-xs text-white/60 font-light">{route.line}</p>
                  {route.rating && (
                    <div className="flex items-center gap-1 mt-1">
                      <Star className="h-3 w-3 text-yellow-400 fill-yellow-400" />
                      <span className="text-xs text-white/60">{route.rating}</span>
                    </div>
                  )}
                </div>
                <div className="text-right">
                  <p className="text-2xl font-light text-white">{formatCurrency(route.fare * passengers)}</p>
                  <p className="text-xs text-white/60 font-light">{passengers} {passengers === 1 ? 'passenger' : 'passengers'}</p>
                </div>
              </div>

              {/* Route Details Grid */}
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div className="flex items-center gap-2 text-white/60">
                  <MapPin className="h-4 w-4" />
                  <span className="text-xs">{route.from}</span>
                </div>
                <div className="flex items-center gap-2 text-white/60">
                  <Clock className="h-4 w-4" />
                  <span className="text-xs">{route.duration}</span>
                </div>
                <div className="flex items-center gap-2 text-white/60">
                  <MapPin className="h-4 w-4" />
                  <span className="text-xs">{route.to}</span>
                </div>
                <div className="flex items-center gap-2 text-white/60">
                  <Train className="h-4 w-4" />
                  <span className="text-xs">{route.stops} stops</span>
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center justify-between pt-4 border-t border-white/10">
                <Badge variant="outline" className="bg-white/5 border-white/20 text-white/60 rounded-none text-xs font-light">
                  <Train className="h-3 w-3 mr-1" />
                  Metro Rail
                </Badge>
                <Button
                  onClick={(e) => {
                    e.stopPropagation();
                    handleSelectRoute(route.id);
                  }}
                  className="bg-white text-black hover:bg-white/90 rounded-none font-light tracking-wider text-sm uppercase"
                  data-testid={`button-book-${route.id}`}
                >
                  Book Now
                  <ArrowRight className="h-4 w-4 ml-2" />
                </Button>
              </div>
            </div>
          </div>
        ))}

        {filteredRoutes.length > 0 && (
          <PaginationControls
            currentPage={pagination.currentPage}
            totalPages={pagination.totalPages}
            onPageChange={pagination.goToPage}
            canGoNext={pagination.canGoNext}
            canGoPrevious={pagination.canGoPrevious}
            startIndex={pagination.startIndex}
            endIndex={pagination.endIndex}
            totalItems={pagination.totalItems}
            className="mt-6 mb-6"
          />
        )}
      </div>
    </div>
  );
}

