                {formatCurrency(amount || 0)}
              </p>
            </div>

            {/* Account Details Grid */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <div className="flex items-center gap-2 mb-2">
                  <User className="h-4 w-4 text-white/40" />
