                      value={studentCollegeId}
                      onChange={(e) => setStudentCollegeId(e.target.value)}
                      placeholder="Enter college ID"
                      className="bg-white/5 border-white/20 text-white rounded-none mt-2"
                      data-testid="input-student-college-id"
