  { id: "5", accountId: "3", accountName: "Rental Property", consumerNumber: "5555666677", city: "Delhi", amount: 550, date: "12 Sep 2024", time: "04:20 PM", status: "Success" },
  { id: "6", accountId: "2", accountName: "Parents Home", consumerNumber: "9876543210", city: "Pune", amount: 480, date: "15 Aug 2024", time: "01:15 PM", status: "Success" },
];

export default function BillPaymentWater() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useUrlTab("recent");

  const recentTransactions = allTransactions.slice(0, 3);

  const handleAccountClick = (account: SavedAccount) => {
    navigate(`/water-bill/account/${account.id}`);
  };

  const handleTransactionClick = (transaction: Transaction) => {
    navigate(`/water-bill/transaction/${transaction.id}`);
  };

  const handleAddNew = () => {
    navigate("/add-water-account");
  };

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/home")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">WATER BILL</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">All Cities</p>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={handleAddNew}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-add-new"
          >
            <Plus className="h-5 w-5" />
          </Button>
        </div>
      </div>

      <div className="pt-20 pb-6 px-4 space-y-6 w-full max-w-screen-lg mx-auto">
        {/* Water Bill Summary Card */}
        <div className="relative border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-6" data-testid="water-bill-summary">
          <div className="space-y-6">
            {/* Total Bills Display */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <p className="text-xs text-white/50 uppercase tracking-widest font-light">Total Water Bills</p>
                <div className="flex items-center gap-2">
                  <Droplets className="h-3 w-3 text-white/60" />
                  <span className="text-xs text-white/60">This Month</span>
                </div>
              </div>
              <p className="text-4xl font-light text-white tracking-tight" data-testid="text-total-water-bills">
                ₹{(recentTransactions.reduce((sum, t) => sum + t.amount, 0) / 1000).toFixed(1)}K
              </p>
            </div>

            {/* Quick Stats Grid */}
            <div className="grid grid-cols-3 gap-3 pt-4 border-t border-white/10">
              <div className="space-y-1 text-center" data-testid="card-paid-count">
                <p className="text-lg font-light text-white" data-testid="text-paid-count">
                  {recentTransactions.length}
                </p>
                <p className="text-[10px] text-white/50 uppercase tracking-widest">Paid</p>
              </div>
              <div className="space-y-1 text-center" data-testid="card-accounts-count">
                <p className="text-lg font-light text-white" data-testid="text-accounts-count">
                  {savedAccounts.length}
                </p>
                <p className="text-[10px] text-white/50 uppercase tracking-widest">Accounts</p>
              </div>
              <div className="space-y-1 text-center">
                <p className="text-lg font-light text-white">
                  {savedAccounts.length}
                </p>
                <p className="text-[10px] text-white/50 uppercase tracking-widest">Pending</p>
              </div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="bg-transparent border-b border-white/10 w-full h-auto p-0 rounded-none grid grid-cols-3 gap-0">
            <TabsTrigger 
              value="recent" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent" 
              data-testid="tab-recent"
            >
              Recent
            </TabsTrigger>
            <TabsTrigger 
              value="due" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent" 
              data-testid="tab-due"
            >
              Accounts
            </TabsTrigger>
            <TabsTrigger 
              value="transactions" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent" 
              data-testid="tab-transactions"
            >
              Transactions
            </TabsTrigger>
          </TabsList>

          {/* Recent Tab */}
          <TabsContent value="recent" className="mt-6 space-y-3">
            {savedAccounts.slice(0, 3).map((account) => (
              <div
                key={account.id}
                onClick={() => handleAccountClick(account)}
                className="cursor-pointer border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent hover:border-white/20 transition-all p-4"
                data-testid={`card-account-${account.id}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 border border-white/20 flex items-center justify-center">
                      <Droplets className="h-5 w-5 text-white/60" />
                    </div>
                    <div>
                      <p className="text-white font-light tracking-wide">{account.name}</p>
                      <p className="text-[10px] text-white/50 uppercase tracking-widest">{account.city} • {account.consumerNumber}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="text-right">
                      <p className="text-white font-light">{account.billAmount}</p>
                      <p className="text-[10px] text-white/40 uppercase tracking-widest">Due: {account.dueDate}</p>
                    </div>
                    <ChevronRight className="h-5 w-5 text-white/40" />
                  </div>
                </div>
              </div>
            ))}
          </TabsContent>

          {/* Due Tab */}
          <TabsContent value="due" className="mt-6 space-y-3">
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light mb-3">Upcoming Bills</p>
            {savedAccounts.map((account) => (
              <div
                key={account.id}
                onClick={() => handleAccountClick(account)}
                className="cursor-pointer border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-4"
                data-testid={`card-due-account-${account.id}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 border border-white/20 flex items-center justify-center">
                      <Droplets className="h-5 w-5 text-white/60" />
                    </div>
                    <div>
                      <p className="text-white font-light tracking-wide">{account.name}</p>
                      <p className="text-[10px] text-white/50 uppercase tracking-widest">{account.city} • {account.consumerNumber}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="text-right">
                      <p className="text-white font-light">{account.billAmount}</p>
                      <p className="text-[10px] text-white/40 uppercase tracking-widest">Due: {account.dueDate}</p>
                    </div>
                    <ChevronRight className="h-5 w-5 text-white/40" />
                  </div>
                </div>
              </div>
            ))}
          </TabsContent>

          {/* Transactions Tab */}
          <TabsContent value="transactions" className="mt-6 space-y-3">
            {allTransactions.map((transaction) => (
              <div
                key={transaction.id}
                onClick={() => handleTransactionClick(transaction)}
                className="cursor-pointer border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent hover:border-white/20 transition-all p-4"
                data-testid={`card-transaction-${transaction.id}`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-light tracking-wide">{transaction.accountName}</p>
                    <p className="text-[10px] text-white/50 uppercase tracking-widest">{transaction.city} • {transaction.consumerNumber}</p>
                    <div className="flex items-center gap-1 mt-1">
                      <Calendar className="h-3 w-3 text-white/40" />
                      <p className="text-[10px] text-white/40 uppercase tracking-widest">{transaction.date} • {transaction.time}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className="text-right">
                      <p className="text-white font-light">₹{transaction.amount}</p>
                      <Badge className="bg-white/10 text-white/60 border-white/20 rounded-none text-[10px] uppercase tracking-widest mt-1">
                        {transaction.status}
                      </Badge>
                    </div>
                    <ChevronRight className="h-5 w-5 text-white/40" />
                  </div>
                </div>
              </div>
            ))}
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

client/src/pages/metro-payment.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { useNavigationHistory } from "@/hooks/use-navigation-history";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import {
  ArrowLeft,
  CreditCard,
  Smartphone,
  Wallet,
  Building2,
  CheckCircle,
  Shield
} from "lucide-react";

export default function MetroPayment() {
  const { goBack } = useNavigationHistory();
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [paymentMethod, setPaymentMethod] = useState("upi");
  const [isProcessing, setIsProcessing] = useState(false);

  const [upiId, setUpiId] = useState("");
  const [cardNumber, setCardNumber] = useState("");
  const [cardName, setCardName] = useState("");
  const [cardExpiry, setCardExpiry] = useState("");
  const [cardCvv, setCardCvv] = useState("");
  const [cardType, setCardType] = useState<"credit" | "debit">("credit");

  const params = new URLSearchParams(window.location.search);
  const amount = parseFloat(params.get("amount") || "0");

  const formatCurrency = (amt: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0
    }).format(amt);
  };

  const handlePayment = () => {
    if (paymentMethod === "upi" && !upiId) {
      toast({
        title: "UPI ID Required",
        description: "Please enter your UPI ID",
        variant: "destructive"
      });
      return;
    }

    if (paymentMethod === "card" && (!cardNumber || !cardName || !cardExpiry || !cardCvv)) {
      toast({
        title: "Card Details Required",
        description: "Please fill in all card details",
        variant: "destructive"
      });
      return;
    }

    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      toast({
        title: "Payment Successful!",
        description: "Your ticket has been confirmed.",
      });
      navigate("/all-tickets");
    }, 2000);
  };

  const PAYMENT_METHODS = [
    { id: "upi", name: "UPI", icon: Smartphone },
    { id: "card", name: "Card", icon: CreditCard },
    { id: "netbanking", name: "Net Banking", icon: Building2 },
    { id: "wallet", name: "Wallet", icon: Wallet }
  ];

  return (
    <div className="min-h-screen bg-black text-white pb-32">
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => goBack()}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">SECURE PAYMENT</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Complete your booking</p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      <div className="pt-20 px-4 space-y-8 w-full max-w-screen-lg mx-auto">
        <div className="py-6 border-b border-white/10">
          <div className="flex items-start gap-3">
            <Shield className="h-5 w-5 text-white/60 mt-0.5" />
            <div className="flex-1">
              <h3 className="text-sm font-light text-white mb-1 tracking-wider">Secure Payment</h3>
              <p className="text-xs text-white/40 font-light leading-relaxed">
                Your payment is secured with 256-bit SSL encrypted transaction
              </p>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <Label className="text-white/60 text-xs uppercase tracking-widest font-light">
            Select Payment Method
          </Label>
          <div className="grid grid-cols-4 gap-2">
            {PAYMENT_METHODS.map((method) => {
              const Icon = method.icon;
              return (
                <button
                  key={method.id}
                  onClick={() => setPaymentMethod(method.id)}
                  className={cn(
                    "p-4 border-b-2 transition-all flex flex-col items-center gap-2",
                    paymentMethod === method.id
                      ? "border-white bg-white/5"
                      : "border-white/20 hover:border-white/40"
                  )}
                  data-testid={`button-payment-${method.id}`}
                >
                  <Icon className={cn(
                    "h-6 w-6 transition-opacity",
                    paymentMethod === method.id ? "opacity-100 text-white" : "opacity-40 text-white/60"
                  )} />
                  <span className={cn(
                    "text-xs font-light tracking-wider transition-opacity",
                    paymentMethod === method.id ? "opacity-100 text-white" : "opacity-40 text-white/60"
                  )}>
                    {method.name}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {paymentMethod === "upi" && (
          <div className="space-y-4 py-4 border-b border-white/10">
            <Label className="text-white/60 text-xs uppercase tracking-widest font-light block">
              Enter UPI ID
            </Label>
            <Input
              value={upiId}
              onChange={(e) => setUpiId(e.target.value)}
              placeholder="yourname@upi"
              className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-0"
              data-testid="input-upi-id"
            />
            <p className="text-xs text-white/40 font-light">e.g., 9876543210@paytm, yourname@okaxis</p>
          </div>
        )}

        {paymentMethod === "card" && (
          <div className="space-y-6 py-4 border-b border-white/10">
            <div className="flex gap-2">
              <button
                onClick={() => setCardType("credit")}
                className={cn(
                  "flex-1 p-3 border-b-2 transition-all text-center",
                  cardType === "credit"
                    ? "border-white bg-white/5 text-white"
                    : "border-white/20 text-white/60 hover:border-white/40"
                )}
                data-testid="button-credit-card"
              >
                <span className="text-sm font-light tracking-wider">CREDIT CARD</span>
              </button>
              <button
                onClick={() => setCardType("debit")}
                className={cn(
                  "flex-1 p-3 border-b-2 transition-all text-center",
                  cardType === "debit"
                    ? "border-white bg-white/5 text-white"
                    : "border-white/20 text-white/60 hover:border-white/40"
                )}
                data-testid="button-debit-card"
              >
                <span className="text-sm font-light tracking-wider">DEBIT CARD</span>
              </button>
            </div>

            <div className="space-y-2">
              <Label className="text-white/60 text-xs uppercase tracking-widest font-light">Card Number</Label>
              <Input
                value={cardNumber}
                onChange={(e) => setCardNumber(e.target.value.replace(/\D/g, '').substring(0, 16))}
                placeholder="1234 5678 9012 3456"
                maxLength={16}
                className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-0"
                data-testid="input-card-number"
              />
            </div>

            <div className="space-y-2">
              <Label className="text-white/60 text-xs uppercase tracking-widest font-light">Cardholder Name</Label>
              <Input
                value={cardName}
                onChange={(e) => setCardName(e.target.value)}
                placeholder="Name on card"
                className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-0"
                data-testid="input-card-name"
              />
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label className="text-white/60 text-xs uppercase tracking-widest font-light">Expiry Date</Label>
                <Input
                  value={cardExpiry}
                  onChange={(e) => setCardExpiry(e.target.value)}
                  placeholder="MM/YY"
                  maxLength={5}
                  className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-0"
                  data-testid="input-card-expiry"
                />
              </div>
              <div className="space-y-2">
                <Label className="text-white/60 text-xs uppercase tracking-widest font-light">CVV</Label>
                <Input
                  value={cardCvv}
                  onChange={(e) => setCardCvv(e.target.value.replace(/\D/g, '').substring(0, 3))}
                  placeholder="123"
                  type="password"
                  maxLength={3}
                  className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-0"
                  data-testid="input-card-cvv"
                />
              </div>
            </div>
          </div>
        )}

        <div className="py-6 border-b border-white/10">
          <div className="flex justify-between items-center">
            <span className="text-white/60 text-xs uppercase tracking-widest font-light">Total Amount</span>
            <span className="text-3xl font-light text-white" data-testid="text-total-amount">
              {formatCurrency(amount)}
            </span>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4 z-40">
        <Button
          onClick={handlePayment}
          disabled={isProcessing}
          className="w-full bg-white text-black hover:bg-white/90 rounded-none h-14 text-base font-light tracking-wider disabled:opacity-50 disabled:cursor-not-allowed"
          data-testid="button-pay-now"
        >
          {isProcessing ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-black border-t-transparent mr-2" />
              Processing Payment...
            </>
          ) : (
            <>
              <CheckCircle className="h-5 w-5 mr-2" />
              PAY {formatCurrency(amount)}
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

client/src/pages/my-metros.tsx.content:
import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Navigation, Search, Calendar, MapPin, Clock, Users, ArrowRight, ArrowLeft } from "lucide-react";
import type { TravelBooking } from "@shared/schema";
import { useToast } from "@/hooks/use-toast";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";

const formatDate = (date: string | Date) => {
  return new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

const formatTime = (date: string | Date) => {
  return new Date(date).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
};

export default function MyMetros() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [sortBy, setSortBy] = useState("date");

  const { data: bookingsData, isLoading, error } = useQuery<{ bookings: (TravelBooking & { passengers?: any[] })[] }>({
    queryKey: ['/api/travel/my-bookings'],
  });

  useEffect(() => {
    if (error) {
      toast({
        title: "Error loading metros",
        description: "Failed to fetch metro bookings. Please try again.",
        variant: "destructive",
      });
    }
  }, [error, toast]);

  const allBookings = bookingsData?.bookings || [];
  const metros = allBookings.filter(b => b.serviceType === 'metro');

  const filteredMetros = metros.filter(booking => {
    if (statusFilter !== "all" && booking.status !== statusFilter) return false;
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      return (
        booking.bookingReference?.toLowerCase().includes(query) ||
        booking.fromLocation.toLowerCase().includes(query) ||
        booking.toLocation.toLowerCase().includes(query) ||
        booking.operatorName?.toLowerCase().includes(query)
      );
    }
    return true;
  });

  const sortedMetros = [...filteredMetros].sort((a, b) => {
    if (sortBy === "date") return new Date(a.departureDate).getTime() - new Date(b.departureDate).getTime();
    if (sortBy === "price-low") return parseFloat(a.totalAmount) - parseFloat(b.totalAmount);
    if (sortBy === "price-high") return parseFloat(b.totalAmount) - parseFloat(a.totalAmount);
    return 0;
  });

  const pagination = usePagination({
    data: sortedMetros,
    itemsPerPage: 10,
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'bg-white/10 text-white/80 border-white/20';
      case 'pending': return 'bg-white/10 text-white/80 border-white/20';
      case 'cancelled': return 'bg-white/10 text-white/80 border-white/20';
      case 'completed': return 'bg-white/10 text-white/80 border-white/20';
      default: return 'bg-white/10 text-white/80 border-white/20';
    }
  };

  return (
    <div className="min-h-screen bg-black text-white">
      <div className="container mx-auto px-4 py-8 max-w-7xl">
        <div className="mb-8">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/my-trips")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>

          <div className="flex items-center gap-4">
            <div className="p-3 bg-white/10 border border-white/20 rounded-none">
              <Navigation className="h-8 w-8 text-white" strokeWidth={1} />
            </div>
            <div>
              <h1 className="text-3xl font-light text-white tracking-wider uppercase">My Metros</h1>
              <p className="text-white/60 text-xs uppercase tracking-widest font-light">{metros.length} metro{metros.length !== 1 ? 's' : ''} found</p>
            </div>
          </div>
        </div>

        <div className="bg-white/5 border border-white/10 rounded-none mb-6 p-6">
          <div className="flex flex-col lg:flex-row gap-4">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/50" strokeWidth={1} />
              <Input
                placeholder="Search by ticket ID, station, or operator..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 bg-white/5 border-white/20 text-white placeholder:text-white/50 rounded-none"
                data-testid="input-search"
              />
            </div>
            <div className="flex gap-3">
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-[180px] bg-white/5 border-white/20 text-white rounded-none" data-testid="select-status">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="confirmed">Confirmed</SelectItem>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                </SelectContent>
              </Select>
              <Select value={sortBy} onValueChange={setSortBy}>
                <SelectTrigger className="w-[180px] bg-white/5 border-white/20 text-white rounded-none" data-testid="select-sort">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="date">Sort by Date</SelectItem>
                  <SelectItem value="price-low">Price: Low to High</SelectItem>
                  <SelectItem value="price-high">Price: High to Low</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>

        {isLoading ? (
          <div className="grid gap-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white/5 border border-white/10 rounded-none p-6">
                <div className="animate-pulse space-y-3">
                  <div className="h-6 bg-white/10 rounded-none w-1/3"></div>
                  <div className="h-8 bg-white/10 rounded-none"></div>
                </div>
              </div>
            ))}
          </div>
        ) : pagination.paginatedData.length > 0 ? (
          <div className="grid gap-4">
            {pagination.paginatedData.map((metro) => (
              <div
                key={metro.id}
                className="bg-gradient-to-br from-white/10 via-white/5 to-transparent border border-white/20 backdrop-blur-xl rounded-none hover:border-white/40 transition-all cursor-pointer p-6"
                onClick={() => navigate(`/my-trips/metros/${metro.id}`)}
                data-testid={`card-metro-${metro.id}`}
              >
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                  <div className="flex-1 space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="p-2 bg-white/10 border border-white/20 rounded-none">
                          <Navigation className="h-5 w-5 text-white/80" strokeWidth={1} />
                        </div>
                        <div>
                          <h3 className="font-light text-lg text-white">{metro.operatorName || 'Metro'}</h3>
                          <p className="text-sm text-white/50 uppercase tracking-wider">ID: {metro.bookingReference}</p>
                        </div>
                      </div>
                      <Badge className={`${getStatusColor(metro.status)} border rounded-none uppercase tracking-wider text-xs`}>
                        {metro.status}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-8">
                      <div>
                        <p className="text-2xl font-light text-white">{formatTime(metro.departureDate)}</p>
                        <p className="text-white/60 flex items-center gap-1 mt-1 text-sm">
                          <MapPin className="h-3 w-3" strokeWidth={1} />
                          {metro.fromLocation}
                        </p>
                      </div>
                      <div className="flex-1 flex items-center justify-center">
                        <div className="flex items-center gap-2 text-white/40">
                          <div className="h-px bg-white/20 flex-1"></div>
                          <Clock className="h-4 w-4" strokeWidth={1} />
                          <div className="h-px bg-white/20 flex-1"></div>
                        </div>
                      </div>
                      <div>
                        <p className="text-2xl font-light text-white">{metro.arrivalTime || formatTime(metro.departureDate)}</p>
                        <p className="text-white/60 flex items-center gap-1 mt-1 text-sm">
                          <MapPin className="h-3 w-3" strokeWidth={1} />
                          {metro.toLocation}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-6 text-sm text-white/60">
                      <div className="flex items-center gap-2">
                        <Calendar className="h-4 w-4" strokeWidth={1} />
                        {formatDate(metro.departureDate)}
                      </div>
                      <div className="flex items-center gap-2">
                        <Users className="h-4 w-4" strokeWidth={1} />
                        {metro.totalPassengers} Passenger{metro.totalPassengers !== 1 ? 's' : ''}
                      </div>
                      {metro.seatClass && (
                        <div className="px-2 py-1 bg-white/10 rounded-none text-xs uppercase tracking-wider">
                          {metro.seatClass}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="flex lg:flex-col items-center lg:items-end justify-between lg:justify-center gap-4">
                    <div className="text-right">
                      <p className="text-sm text-white/50 mb-1 uppercase tracking-wider">Total Amount</p>
                      <p className="text-2xl font-light text-white">₹{parseFloat(metro.totalAmount).toLocaleString()}</p>
                    </div>
                    <Button
                      variant="outline"
                      className="border-white/20 text-white rounded-none"
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate(`/my-trips/booking/${metro.id}`);
                      }}
                      data-testid={`button-view-${metro.id}`}
                    >
                      View Details
                      <ArrowRight className="h-4 w-4 ml-2" strokeWidth={1} />
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : null}

        {sortedMetros.length > 0 && (
          <PaginationControls
            currentPage={pagination.currentPage}
            totalPages={pagination.totalPages}
            onPageChange={pagination.goToPage}
            canGoNext={pagination.canGoNext}
            canGoPrevious={pagination.canGoPrevious}
            startIndex={pagination.startIndex}
            endIndex={pagination.endIndex}
            totalItems={pagination.totalItems}
            className="mt-6"
          />
        )}

        {sortedMetros.length === 0 && (
          <div className="bg-white/5 border border-white/10 rounded-none p-12 text-center">
            <Navigation className="h-16 w-16 text-white/20 mx-auto mb-4" strokeWidth={1} />
            <h3 className="text-lg font-light text-white mb-2">No metros found</h3>
            <p className="text-white/60">
              {searchQuery || statusFilter !== "all"
                ? "Try adjusting your search or filters"
                : "You haven't booked any metro tickets yet"}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

client/src/pages/upi-history.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { 
  History, 
  Send, 
  Receipt, 
  CreditCard, 
  CheckCircle, 
  XCircle, 
  Clock, 
  Loader2,
  Search,
  BarChart3,
  Calendar,
  TrendingUp,
  TrendingDown,
  PieChart,
  Download,
  ArrowLeft,
  Lock,
  LogIn
} from "lucide-react";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/hooks/use-auth";
import { type UpiTransaction } from "@shared/schema";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";

export default function UpiHistory() {
  const [, navigate] = useLocation();
  const { isAuthenticated, isLoading: authLoading } = useAuth();
  const [filter, setFilter] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedMonth, setSelectedMonth] = useState("all");
  const [viewMode, setViewMode] = useState<"list" | "analytics">("list");


  // Fetch UPI transactions only if authenticated
  const { data: transactions = [], isLoading, error } = useQuery<UpiTransaction[]>({
    queryKey: ['/api/upi/transactions'],
    enabled: isAuthenticated, // Only fetch when authenticated
    retry: (failureCount, error: any) => {
      // Don't retry on 401 authentication errors
      if (error?.response?.status === 401) return false;
      return failureCount < 3;
    }
  });

  // Show loading state while checking authentication
  if (authLoading) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-center">
          <Loader2 className="h-8 w-8 animate-spin mx-auto mb-4 text-white" />
          <p className="text-white/60">Loading...</p>
        </div>
      </div>
    );
  }

  // Show login prompt if not authenticated
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-center px-6 max-w-md mx-auto">
          <div className="w-20 h-20 border-2 border-white/30 flex items-center justify-center mx-auto mb-6">
            <Lock className="h-10 w-10 text-white" />
          </div>
          <h2 className="text-2xl font-bold text-white tracking-wider mb-4">LOGIN REQUIRED</h2>
          <p className="text-white/60 mb-6">
            Please log in to view your UPI transaction history
          </p>
          <Button
            onClick={() => navigate("/login")}
            className="bg-white text-black hover:bg-white/90 font-semibold w-full h-12"
            data-testid="button-login"
          >
            <LogIn className="h-4 w-4 mr-2" />
            LOGIN NOW
          </Button>
        </div>
      </div>
    );
  }

  const filteredTransactions = transactions.filter((t: UpiTransaction) => {
    // Filter by type
    const typeMatch = filter === "all" || 
      t.transactionType.replace('_payment', '').replace('_', '') === filter || 
      t.transactionType === filter;

    // Filter by search term
    const searchMatch = searchTerm === "" || 
      (t.recipientName && t.recipientName.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (t.description && t.description.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (t.recipientUpiId && t.recipientUpiId.toLowerCase().includes(searchTerm.toLowerCase()));

    return typeMatch && searchMatch;
  });

  // Add pagination
  const {
    paginatedData: paginatedTransactions,
    currentPage,
    totalPages,
    goToPage,
    canGoNext,
    canGoPrevious,
    startIndex,
    endIndex,
    totalItems,
  } = usePagination({
    data: filteredTransactions,
    itemsPerPage: 20,
  });

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "success": return <CheckCircle className="h-4 w-4 text-white/80" />;
      case "failed": return <XCircle className="h-4 w-4 text-white/80" />;
      case "pending": return <Clock className="h-4 w-4 text-white/80" />;
      default: return null;
    }
  };

  const getTypeIcon = (type: string) => {
    const transactionType = type.replace('_payment', '').replace('_', '');
    switch (transactionType) {
      case "payment": return <Send className="h-4 w-4 text-white/60" />;
      case "collect": return <Receipt className="h-4 w-4 text-white/60" />;
      case "bill": return <CreditCard className="h-4 w-4 text-white/60" />;
      default: return <Send className="h-4 w-4 text-white/60" />;
    }
  };

  // Calculate analytics
  const totalTransactions = filteredTransactions.length;
  const totalAmount = filteredTransactions.reduce((sum, t) => sum + parseFloat(t.amount || '0'), 0);
  const successfulTransactions = filteredTransactions.filter(t => t.status === 'success').length;
  const successRate = totalTransactions > 0 ? ((successfulTransactions / totalTransactions) * 100).toFixed(1) : 0;

  const filterOptions = [
    { value: "all", label: "ALL", icon: History },
    { value: "payment", label: "PAYMENTS", icon: Send },
    { value: "collect", label: "REQUESTS", icon: Receipt },
    { value: "bill", label: "BILLS", icon: CreditCard }
  ];

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/home")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base uppercase tracking-widest font-light">UPI HISTORY</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest">Transaction history</p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      {/* Main Content */}
      <div className="pt-20 px-4 space-y-6 w-full max-w-screen-lg mx-auto">
        {/* Analytics Overview */}
        <div className="bg-white/5 border border-white/10 p-6 mb-6 backdrop-blur-xl">
          <div className="grid grid-cols-2 gap-4 mb-4">
            <div className="text-center p-4 border border-white/10 bg-white/5">
              <p className="text-2xl font-bold text-white">{totalTransactions}</p>
              <p className="text-white/60 text-sm">Total Transactions</p>
            </div>
            <div className="text-center p-4 border border-white/10 bg-white/5">
              <p className="text-2xl font-bold text-white">₹{totalAmount.toLocaleString()}</p>
              <p className="text-white/60 text-sm">Total Amount</p>
            </div>
          </div>
          <div className="text-center p-4 border border-white/10 bg-white/5">
            <p className="text-2xl font-bold text-white/80">{successRate}%</p>
            <p className="text-white/60 text-sm">Success Rate</p>
          </div>
        </div>

        {/* Search and Filters */}
        <div className="mb-6">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/60" />
            <Input
              placeholder="Search transactions..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10 bg-black border border-white/10 text-white placeholder:text-white/40 focus:border-white/60 focus:ring-0 h-12 rounded-none"
            />
          </div>

          <Tabs value={viewMode} onValueChange={(value) => setViewMode(value as "list" | "analytics")} className="w-full mb-4">
            <TabsList className="grid w-full grid-cols-2 bg-black border border-white/10 rounded-none p-1">
              <TabsTrigger 
                value="list" 
                className="data-[state=active]:bg-white data-[state=active]:text-black text-white/80 font-medium text-xs rounded-none transition-all duration-300 ease-out data-[state=active]:scale-105 data-[state=active]:animate-[bubble_0.4s_ease-out] hover:text-white"
              >
                TRANSACTIONS
              </TabsTrigger>
              <TabsTrigger 
                value="analytics"
                className="data-[state=active]:bg-white data-[state=active]:text-black text-white/80 font-medium text-xs rounded-none transition-all duration-300 ease-out data-[state=active]:scale-105 data-[state=active]:animate-[bubble_0.4s_ease-out] hover:text-white"
              >
                ANALYTICS
              </TabsTrigger>
            </TabsList>
          </Tabs>

          {/* Filter Pills */}
          <div className="flex gap-2 overflow-x-auto">
            {filterOptions.map((option) => (
              <Button
                key={option.value}
                variant={filter === option.value ? "default" : "outline"}
                size="sm"
                onClick={() => setFilter(option.value)}
                className={`flex items-center gap-2 whitespace-nowrap rounded-none ${
                  filter === option.value 
                    ? "bg-white text-black hover:bg-white/90" 
                    : "border border-white/10 text-white/80 hover:text-white hover:bg-white/10"
                }`}
              >
                <option.icon className="h-3 w-3" />
                {option.label}
              </Button>
            ))}
          </div>
        </div>

        {viewMode === "list" ? (
          <div className="space-y-4">
            {isLoading ? (
              <div className="space-y-4">
                {[1, 2, 3, 4, 5].map((i) => (
                  <div key={i} className="border border-white/20 p-4 animate-pulse">
                    <div className="h-4 bg-white/20 rounded w-3/4 mb-2"></div>
                    <div className="h-3 bg-white/10 rounded w-1/2"></div>
                  </div>
                ))}
              </div>
            ) : filteredTransactions.length === 0 ? (
              <div className="text-center py-12 border border-white/10 bg-white/5">
                <History className="h-16 w-16 text-white/40 mx-auto mb-4" />
                <h3 className="text-lg font-semibold text-white mb-2">NO TRANSACTIONS FOUND</h3>
                <p className="text-white/60 mb-4">
                  {searchTerm ? "Try adjusting your search terms" : "Start making UPI transactions to see them here"}
                </p>
                <Button
                  onClick={() => {
                    setSearchTerm("");
                    setFilter("all");
                  }}
                  className="bg-white text-black hover:bg-white/90 font-semibold rounded-none"
                >
                  CLEAR FILTERS
                </Button>
              </div>
            ) : (
              <>
                <div className="space-y-4">
                  {paginatedTransactions.map((transaction) => (
                    <div 
                      key={transaction.id} 
                      className="border border-white/10 bg-white/5 p-4 hover:border-white/30 transition-colors cursor-pointer"
                      onClick={() => navigate(`/payment-detail/${transaction.id}`)}
                      data-testid={`transaction-item-${transaction.id}`}
                    >
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 border border-white/30 flex items-center justify-center">
                            {getTypeIcon(transaction.transactionType)}
                          </div>
                          <div>
                            <h3 className="font-semibold text-white">
                              {transaction.recipientName || transaction.recipientUpiId || 'UPI Transaction'}
                            </h3>
                            <p className="text-white/60 text-sm">
                              {transaction.description || transaction.transactionType.replace('_', ' ').toUpperCase()}
                            </p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="font-bold text-white">₹{parseFloat(transaction.amount || '0').toLocaleString()}</p>
                          <div className="flex items-center gap-1 justify-end mt-1">
                            {getStatusIcon(transaction.status)}
                            <span className="text-white/60 text-sm capitalize">{transaction.status}</span>
                          </div>
                        </div>
                      </div>

                      <div className="flex justify-between items-center text-sm">
                        <span className="text-white/60">
                          {transaction.createdAt ? new Date(transaction.createdAt).toLocaleDateString() : 'Unknown date'}
                        </span>
                        <span className="text-white/60">
                          ID: {transaction.externalTransactionId?.slice(-6) || 'N/A'}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>

                <PaginationControls
                  currentPage={currentPage}
                  totalPages={totalPages}
                  onPageChange={goToPage}
                  canGoNext={canGoNext}
                  canGoPrevious={canGoPrevious}
                  startIndex={startIndex}
                  endIndex={endIndex}
                  totalItems={totalItems}
                />
              </>
            )}
          </div>
        ) : (
          <div className="space-y-4">
            {/* Transaction Type Breakdown */}
            <div className="border border-white/10 bg-white/5 p-6 backdrop-blur-xl">
              <h3 className="font-semibold text-white mb-4">TRANSACTION BREAKDOWN</h3>
              <div className="space-y-3">
                {filterOptions.slice(1).map((type) => {
                  const typeTransactions = transactions.filter(t => 
                    t.transactionType.includes(type.value === 'bill' ? 'bill' : type.value)
                  );
                  const typeAmount = typeTransactions.reduce((sum, t) => sum + parseFloat(t.amount || '0'), 0);

                  return (
                    <div key={type.value} className="flex items-center justify-between p-3 border border-white/10 bg-black/20">
                      <div className="flex items-center gap-3">
                        <type.icon className="h-4 w-4 text-white/60" />
                        <span className="text-white">{type.label}</span>
                      </div>
                      <div className="text-right">
                        <p className="text-white font-semibold">₹{typeAmount.toLocaleString()}</p>
                        <p className="text-white/60 text-xs">{typeTransactions.length} transactions</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Monthly Trends */}
            <div className="border border-white/10 bg-white/5 p-6 backdrop-blur-xl">
              <h3 className="font-semibold text-white mb-4">MONTHLY PERFORMANCE</h3>
              <div className="text-center py-8">
                <BarChart3 className="h-16 w-16 text-white/40 mx-auto mb-4" />
                <p className="text-white/60">Detailed analytics coming soon</p>
              </div>
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex gap-3 mt-6">
          <Button 
            onClick={() => navigate("/upi-payment")}
            className="flex-1 bg-white text-black hover:bg-white/90 font-semibold h-12 rounded-none"
          >
            <Send className="h-4 w-4 mr-2" />
            NEW PAYMENT
          </Button>
          <Button 
            variant="outline" 
            className="flex-1 border border-white/10 text-white hover:bg-white/10 font-semibold h-12 rounded-none"
          >
            <Download className="h-4 w-4 mr-2" />
            EXPORT
          </Button>
        </div>
      </div>
    </div>
  );
}

