import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import {
  ArrowLeft,
  User,
  Mail,
  Phone,
  MessageSquare,
  Hotel,
  Calendar,
  Users,
  CreditCard,
  Shield,
  Check
} from "lucide-react";
import { cn } from "@/lib/utils";

const guestFormSchema = z.object({
  firstName: z.string().min(2, "First name must be at least 2 characters"),
  lastName: z.string().min(2, "Last name must be at least 2 characters"),
  email: z.string().email("Invalid email address"),
  phone: z.string().regex(/^[0-9]{10}$/, "Phone number must be 10 digits"),
  specialRequests: z.string().optional()
});

type GuestFormData = z.infer<typeof guestFormSchema>;

export default function HotelGuestDetails() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const searchParams = new URLSearchParams(window.location.search);
  const hotelId = searchParams.get('hotelId') || '';
  const roomId = searchParams.get('roomId') || '';
  const roomType = searchParams.get('roomType') || '';
  const price = parseFloat(searchParams.get('price') || '0');
  const checkIn = searchParams.get('checkIn') || '';
  const checkOut = searchParams.get('checkOut') || '';
  const rooms = searchParams.get('rooms') || '1';
  const guests = searchParams.get('guests') || '2';

  const calculateNights = () => {
    if (!checkIn || !checkOut) return 1;
    const start = new Date(checkIn);
    const end = new Date(checkOut);
    return Math.max(1, Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)));
  };

  const nights = calculateNights();
  const subtotal = price * nights;
  const tax = subtotal * 0.12;
  const total = subtotal + tax;

  const form = useForm<GuestFormData>({
    resolver: zodResolver(guestFormSchema),
    defaultValues: {
      firstName: "Priya",
      lastName: "Sharma",
      email: "priya.sharma@example.com",
      phone: "9876543210",
      specialRequests: "Early check-in if possible"
    }
  });

  const onSubmit = async (data: GuestFormData) => {
    try {
      setIsSubmitting(true);

      const bookingData = {
        hotelId,
        roomId,
        checkInDate: checkIn,
        checkOutDate: checkOut,
        numberOfRooms: parseInt(rooms),
        numberOfGuests: parseInt(guests),
        totalPrice: total.toString(),
        guestName: `${data.firstName} ${data.lastName}`,
        guestEmail: data.email,
        guestPhone: data.phone,
        specialRequests: data.specialRequests || '',
        status: 'confirmed',
        paymentStatus: 'pending'
      };

      const response = await apiRequest('POST', '/api/hotel-bookings', bookingData);
      const result = await response.json() as { success: boolean; booking: any };

      if (result.success && result.booking) {
        await queryClient.invalidateQueries({ queryKey: ['/api/hotel-bookings'] });

        // Navigate to payment page
        const paymentParams = new URLSearchParams({
          amount: total.toFixed(2),
          type: 'hotel',
          bookingId: result.booking.id,
          returnUrl: `/booking/hotel/success?bookingId=${result.booking.id}`
        });
        navigate(`/upi-payment?${paymentParams.toString()}`);
      }
    } catch (error) {
      toast({
        title: "Booking Failed",
        description: "Failed to create booking. Please try again.",
        variant: "destructive"
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('en-IN', { 
      day: 'numeric', 
      month: 'short', 
      year: 'numeric' 
    });
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0
    }).format(price);
  };

  return (
    <div className="min-h-screen bg-black text-white pb-32">
