const DIAMOND_ITEMS: DiamondItem[] = [
  { id: "1", name: "Lab Grown Diamond", type: "Lab Grown", pricePerCarat: 25000, change: 2.1, clarity: "VS1", cut: "Excellent", provider: "BlueStone" },
