  { id: "20", name: "Diamond Investment Plan", type: "Fund", pricePerCarat: 36000, change: -0.1, clarity: "Investment", cut: "N/A", provider: "HDFC Diamond Fund" },
];

const generatePriceHistory = (id: string, currentPrice: number, change: number) => {
  const points = 20;
  const data: number[] = [];
  const previousPrice = currentPrice / (1 + change / 100);
  const priceDiff = currentPrice - previousPrice;
  const seed = id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  const seededRandom = (index: number) => {
    const x = Math.sin(seed + index) * 10000;
    return x - Math.floor(x);
  };

  for (let i = 0; i < points; i++) {
    const progress = i / (points - 1);
    const basePrice = previousPrice + (priceDiff * progress);
    const randomVariation = (seededRandom(i) - 0.5) * currentPrice * 0.015;
    data.push(basePrice + randomVariation);
  }
  data[data.length - 1] = currentPrice;
  return data;
};

export default function DiamondList() {
  const { goBack } = useNavigationHistory();
  const [, navigate] = useLocation();
  const [searchQuery, setSearchQuery] = useState("");
  const [holdings] = useState<string[]>(["1", "3", "7"]);
  const [liveDiamond, setLiveDiamond] = useState(DIAMOND_ITEMS);

  useEffect(() => {
    const interval = setInterval(() => {
      setLiveDiamond(prevDiamond => prevDiamond.map(diamond => {
        const randomChange = (Math.random() - 0.5) * 0.4;
        const newChange = diamond.change + randomChange;
        const newPrice = diamond.pricePerCarat * (1 + randomChange / 100);
        return {
          ...diamond,
          pricePerCarat: Math.round(newPrice * 100) / 100,
          change: Math.round(newChange * 100) / 100
        };
      }));
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  const filteredDiamond = useMemo(() => {
    let items = liveDiamond;
    if (searchQuery) {
      const lowerQuery = searchQuery.toLowerCase();
      items = items.filter(diamond =>
        diamond.name.toLowerCase().includes(lowerQuery) ||
        diamond.provider.toLowerCase().includes(lowerQuery) ||
        diamond.type.toLowerCase().includes(lowerQuery)
      );
    }
    return items;
  }, [searchQuery, liveDiamond]);

  const holdingStats = useMemo(() => {
    const myHoldings = DIAMOND_ITEMS.filter(diamond => holdings.includes(diamond.id));
    const totalValue = myHoldings.reduce((sum, diamond) => sum + diamond.pricePerCarat * 0.5, 0);
    const totalChange = myHoldings.reduce((sum, diamond) => sum + (diamond.pricePerCarat * 0.5 * diamond.change / 100), 0);
    const changePercent = (totalChange / (totalValue - totalChange)) * 100;

    return {
      totalValue: totalValue.toFixed(2),
      totalChange: totalChange.toFixed(2),
      changePercent: changePercent.toFixed(2),
      holdings: myHoldings.length
    };
  }, [holdings]);

  const pagination = usePagination({
    data: filteredDiamond,
    itemsPerPage: 20,
  });

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => goBack()}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>

          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">DIAMOND</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Invest in Lab & Natural Diamonds</p>
          </div>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/investment/diamond/add")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-add-diamond"
          >
            <Plus className="h-5 w-5" />
          </Button>
        </div>

        {/* Portfolio Card */}
        <div className="px-4 pb-4">
          <div className="relative border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-6" data-testid="diamond-summary">
            <div className="space-y-6">
              {/* Total Portfolio Display */}
              <div className="space-y-2">
                <p className="text-xs text-white/50 uppercase tracking-widest font-light">Portfolio Value</p>
                <p className="text-4xl font-light text-white tracking-tight" data-testid="text-total-portfolio">
                  ₹{Number(holdingStats.totalValue).toLocaleString()}
                </p>
              </div>

              {/* Quick Stats Grid */}
              <div className="grid grid-cols-3 gap-3 pt-4 border-t border-white/10">
                <div className="space-y-1 text-center">
                  <p className="text-lg font-light text-white" data-testid="text-holdings-count">
                    {holdingStats.holdings}
                  </p>
                  <p className="text-[10px] text-white/50 uppercase tracking-widest">Holdings</p>
                </div>
                <div className="space-y-1 text-center">
                  <p className={cn(
                    "text-lg font-light",
                    Number(holdingStats.changePercent) >= 0 ? "text-green-400" : "text-red-400"
                  )} data-testid="text-todays-change">
                    {Number(holdingStats.changePercent) >= 0 ? "+" : ""}{holdingStats.changePercent}%
                  </p>
                  <p className="text-[10px] text-white/50 uppercase tracking-widest">Today's Change</p>
                </div>
                <div className="space-y-1 text-center">
                  <p className={cn(
                    "text-lg font-light",
                    Number(holdingStats.changePercent) >= 0 ? "text-green-400" : "text-red-400"
                  )} data-testid="text-todays-pnl">
                    {Number(holdingStats.changePercent) >= 0 ? "+" : ""}₹{holdingStats.totalChange}
                  </p>
                  <p className="text-[10px] text-white/50 uppercase tracking-widest">P&L</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Search Box */}
        <div className="px-4 pb-4">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/40" />
            <Input
              placeholder="Search diamonds by name, type, or provider..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="bg-transparent border-0 border-b-2 border-white/20 text-white pl-11 rounded-none h-12 focus:border-white placeholder:text-white/30"
              data-testid="input-search-diamond"
            />
          </div>
        </div>
      </div>

      {/* Spacer for fixed header */}
      <div className="h-[280px]" />

      {/* Diamond Items List */}
      <div className="px-4 space-y-3">
        {pagination.paginatedData.map((diamond) => {
          const priceHistory = generatePriceHistory(diamond.id, diamond.pricePerCarat, diamond.change);
          const isPositive = diamond.change >= 0;

          return (
            <div
              key={diamond.id} 
              className="border border-white/20 p-5 bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-xl hover:from-white/15 hover:to-white/10 transition-all cursor-pointer"
              onClick={() => navigate(`/investment/diamond/${diamond.id}`)}
              data-testid={`card-diamond-${diamond.id}`}
            >
              <div className="flex items-center justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="font-light text-white text-sm">{diamond.name}</h3>
                    <Badge variant="outline" className="text-xs bg-white/10 text-white border-white/20 font-light rounded-none">
                      {diamond.type}
                    </Badge>
                  </div>
                  <p className="text-xs text-white/50 font-light mb-2">{diamond.provider} • {diamond.clarity} • {diamond.cut}</p>
                  <div className="flex items-baseline gap-2 mb-1">
                    <p className="text-lg font-light text-white">₹{diamond.pricePerCarat.toLocaleString()}</p>
                    <p className="text-xs text-white/50 font-light">/carat</p>
                  </div>
                  <Badge className={cn(
                    "rounded-none font-light text-xs",
                    isPositive ? "bg-green-500/20 text-green-400 border-green-500/30" : "bg-red-500/20 text-red-400 border-red-500/30"
                  )}>
                    {isPositive ? <TrendingUp className="h-3 w-3 mr-1" /> : <TrendingDown className="h-3 w-3 mr-1" />}
                    {isPositive ? "+" : ""}{diamond.change.toFixed(2)}%
                  </Badge>
                </div>

                <div className="w-24 h-16">
                  <MiniStockChart 
                    data={priceHistory} 
                    change={diamond.change}
                  />
                </div>
              </div>
            </div>
          );
        })}

        <PaginationControls
          currentPage={pagination.currentPage}
          totalPages={pagination.totalPages}
          onPageChange={pagination.goToPage}
          canGoNext={pagination.canGoNext}
          canGoPrevious={pagination.canGoPrevious}
          startIndex={pagination.startIndex}
          endIndex={pagination.endIndex}
          totalItems={pagination.totalItems}
          className="mt-6"
        />
      </div>
    </div>
  );
}

client/src/pages/my-flights.tsx.content:
import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plane, Search, Calendar, MapPin, Clock, Users, ArrowRight, ArrowLeft } from "lucide-react";
import type { TravelBooking } from "@shared/schema";
import { useToast } from "@/hooks/use-toast";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";

const formatDate = (date: string | Date) => {
  return new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

const formatTime = (date: string | Date) => {
  return new Date(date).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
};

export default function MyFlights() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [sortBy, setSortBy] = useState("date");

  const { data: bookingsData, isLoading, error } = useQuery<{ bookings: (TravelBooking & { passengers?: any[] })[] }>({
    queryKey: ['/api/travel/my-bookings'],
  });

  useEffect(() => {
    if (error) {
      toast({
        title: "Error loading flights",
        description: "Failed to fetch flight bookings. Please try again.",
        variant: "destructive",
      });
    }
  }, [error, toast]);

  const allBookings = bookingsData?.bookings || [];
  const flights = allBookings.filter(b => b.serviceType === 'flight');

  const filteredFlights = flights.filter(booking => {
    if (statusFilter !== "all" && booking.status !== statusFilter) return false;
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      return (
        booking.bookingReference?.toLowerCase().includes(query) ||
        booking.fromLocation.toLowerCase().includes(query) ||
        booking.toLocation.toLowerCase().includes(query) ||
        booking.operatorName?.toLowerCase().includes(query)
      );
    }
    return true;
  });

  const sortedFlights = [...filteredFlights].sort((a, b) => {
    if (sortBy === "date") return new Date(a.departureDate).getTime() - new Date(b.departureDate).getTime();
    if (sortBy === "price-low") return parseFloat(a.totalAmount) - parseFloat(b.totalAmount);
    if (sortBy === "price-high") return parseFloat(b.totalAmount) - parseFloat(a.totalAmount);
    return 0;
  });

  const pagination = usePagination({
    data: sortedFlights,
    itemsPerPage: 10,
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed': return 'bg-white/10 text-white/80 border-white/20';
      case 'pending': return 'bg-white/10 text-white/80 border-white/20';
      case 'cancelled': return 'bg-white/10 text-white/80 border-white/20';
      case 'completed': return 'bg-white/10 text-white/80 border-white/20';
      default: return 'bg-white/10 text-white/80 border-white/20';
    }
  };

  return (
    <div className="min-h-screen bg-black text-white">
      <div className="container mx-auto px-4 py-8 max-w-7xl">
        <div className="mb-8">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/my-trips")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>

          <div className="flex items-center gap-4">
            <div className="p-3 bg-white/10 border border-white/20 rounded-none">
              <Plane className="h-8 w-8 text-white" strokeWidth={1} />
            </div>
            <div>
              <h1 className="text-3xl font-light text-white tracking-wider uppercase">My Flights</h1>
              <p className="text-white/60 text-xs uppercase tracking-widest font-light">{flights.length} flight{flights.length !== 1 ? 's' : ''} found</p>
            </div>
          </div>
        </div>

        <div className="bg-white/5 border border-white/10 rounded-none mb-6 p-6">
          <div className="flex flex-col lg:flex-row gap-4">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/50" strokeWidth={1} />
              <Input
                placeholder="Search by PNR, location, or airline..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 bg-white/5 border-white/20 text-white placeholder:text-white/50 rounded-none"
                data-testid="input-search"
              />
            </div>
            <div className="flex gap-3">
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-[180px] bg-white/5 border-white/20 text-white rounded-none" data-testid="select-status">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="confirmed">Confirmed</SelectItem>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                </SelectContent>
              </Select>
              <Select value={sortBy} onValueChange={setSortBy}>
                <SelectTrigger className="w-[180px] bg-white/5 border-white/20 text-white rounded-none" data-testid="select-sort">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="date">Sort by Date</SelectItem>
                  <SelectItem value="price-low">Price: Low to High</SelectItem>
                  <SelectItem value="price-high">Price: High to Low</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>

        {isLoading ? (
          <div className="grid gap-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white/5 border border-white/10 rounded-none p-6">
                <div className="animate-pulse space-y-3">
                  <div className="h-6 bg-white/10 rounded-none w-1/3"></div>
                  <div className="h-8 bg-white/10 rounded-none"></div>
                </div>
              </div>
            ))}
          </div>
        ) : pagination.paginatedData.length > 0 ? (
          <div className="grid gap-4">
            {pagination.paginatedData.map((flight) => (
              <div
                key={flight.id}
                className="bg-gradient-to-br from-white/10 via-white/5 to-transparent border border-white/20 backdrop-blur-xl rounded-none hover:border-white/40 transition-all cursor-pointer p-6"
                onClick={() => navigate(`/my-trips/flights/${flight.id}`)}
                data-testid={`card-flight-${flight.id}`}
              >
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                  <div className="flex-1 space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="p-2 bg-white/10 border border-white/20 rounded-none">
                          <Plane className="h-5 w-5 text-white/80" strokeWidth={1} />
                        </div>
                        <div>
                          <h3 className="font-light text-lg text-white">{flight.operatorName || 'Flight'}</h3>
                          <p className="text-sm text-white/50 uppercase tracking-wider">PNR: {flight.bookingReference}</p>
                        </div>
                      </div>
                      <Badge className={`${getStatusColor(flight.status)} border rounded-none uppercase tracking-wider text-xs`}>
                        {flight.status}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-8">
                      <div>
                        <p className="text-2xl font-light text-white">{formatTime(flight.departureDate)}</p>
                        <p className="text-white/60 flex items-center gap-1 mt-1 text-sm">
                          <MapPin className="h-3 w-3" strokeWidth={1} />
                          {flight.fromLocation}
                        </p>
                      </div>
                      <div className="flex-1 flex items-center justify-center">
                        <div className="flex items-center gap-2 text-white/40">
                          <div className="h-px bg-white/20 flex-1"></div>
                          <Clock className="h-4 w-4" strokeWidth={1} />
                          <div className="h-px bg-white/20 flex-1"></div>
                        </div>
                      </div>
                      <div>
                        <p className="text-2xl font-light text-white">{flight.arrivalTime || formatTime(flight.departureDate)}</p>
                        <p className="text-white/60 flex items-center gap-1 mt-1 text-sm">
