import { useState, useMemo, useEffect } from "react";
import { useLocation } from "wouter";
import { useNavigationHistory } from "@/hooks/use-navigation-history";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { MiniStockChart } from "@/components/ui/mini-stock-chart";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";
import { 
  ArrowLeft,
  Search,
  TrendingUp,
  TrendingDown,
  Building2,
  Plus
} from "lucide-react";

interface FDItem {
  id: string;
  name: string;
  bank: string;
  type: string;
  interestRate: number;
  change: number;
  tenure: string;
  minAmount: number;
  rating: string;
}

const FD_ITEMS: FDItem[] = [
  { id: "1", name: "HDFC Bank FD", bank: "HDFC Bank", type: "Regular", interestRate: 7.5, change: 0.2, tenure: "1 Year", minAmount: 10000, rating: "AAA" },
  { id: "2", name: "SBI Senior Citizen FD", bank: "State Bank of India", type: "Senior Citizen", interestRate: 8.25, change: -0.1, tenure: "5 Years", minAmount: 5000, rating: "AAA" },
  { id: "3", name: "ICICI Bank Tax Saver FD", bank: "ICICI Bank", type: "Tax Saver", interestRate: 7.75, change: 0.3, tenure: "5 Years", minAmount: 100, rating: "AAA" },
  { id: "4", name: "Axis Bank Short Term FD", bank: "Axis Bank", type: "Regular", interestRate: 7.0, change: -0.15, tenure: "6 Months", minAmount: 5000, rating: "AA+" },
  { id: "5", name: "Kotak Mahindra FD", bank: "Kotak Mahindra", type: "Regular", interestRate: 7.25, change: 0.25, tenure: "2 Years", minAmount: 10000, rating: "AAA" },
  { id: "6", name: "YES Bank Corporate FD", bank: "YES Bank", type: "Corporate", interestRate: 8.5, change: -0.2, tenure: "3 Years", minAmount: 100000, rating: "AA" },
  { id: "7", name: "Punjab National Bank FD", bank: "PNB", type: "Regular", interestRate: 7.65, change: 0.15, tenure: "1 Year", minAmount: 1000, rating: "AAA" },
  { id: "8", name: "IndusInd Bank FD", bank: "IndusInd Bank", type: "Regular", interestRate: 7.85, change: -0.05, tenure: "18 Months", minAmount: 10000, rating: "AA+" },
];

const generateRateHistory = (id: string, currentRate: number, change: number) => {
  const points = 20;
  const data: number[] = [];
  const previousRate = currentRate - change;
  const rateDiff = currentRate - previousRate;
  const seed = id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  const seededRandom = (index: number) => {
    const x = Math.sin(seed + index) * 10000;
    return x - Math.floor(x);
  };

  for (let i = 0; i < points; i++) {
    const progress = i / (points - 1);
    const baseRate = previousRate + (rateDiff * progress);
    const randomVariation = (seededRandom(i) - 0.5) * currentRate * 0.01;
    data.push(baseRate + randomVariation);
  }
  data[data.length - 1] = currentRate;
  return data;
};

export default function FDList() {
  const { goBack } = useNavigationHistory();
  const [, navigate] = useLocation();
  const [searchQuery, setSearchQuery] = useState("");
  const [holdings] = useState<string[]>(["1", "3", "5"]);
  const [liveFD, setLiveFD] = useState(FD_ITEMS);

  useEffect(() => {
    const interval = setInterval(() => {
      setLiveFD(prevFD => prevFD.map(fd => {
        const randomChange = (Math.random() - 0.5) * 0.05;
        const newChange = fd.change + randomChange;
        const newRate = fd.interestRate + randomChange;
        return {
          ...fd,
          interestRate: Math.round(newRate * 100) / 100,
          change: Math.round(newChange * 100) / 100
        };
      }));
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  const filteredFD = useMemo(() => {
    let items = liveFD;
    if (searchQuery) {
      const lowerQuery = searchQuery.toLowerCase();
      items = items.filter(fd =>
        fd.name.toLowerCase().includes(lowerQuery) ||
        fd.bank.toLowerCase().includes(lowerQuery) ||
        fd.type.toLowerCase().includes(lowerQuery)
      );
    }
    return items;
  }, [searchQuery, liveFD]);

  const pagination = usePagination({
    data: filteredFD,
    itemsPerPage: 15,
  });

  const holdingStats = useMemo(() => {
    const myHoldings = FD_ITEMS.filter(fd => holdings.includes(fd.id));
    const totalValue = myHoldings.reduce((sum, fd) => sum + fd.minAmount * 5, 0);
    const totalReturns = myHoldings.reduce((sum, fd) => sum + (fd.minAmount * 5 * fd.interestRate / 100), 0);
    const changePercent = (totalReturns / totalValue) * 100;

    return {
      totalValue: totalValue.toFixed(2),
      totalChange: totalReturns.toFixed(2),
      changePercent: changePercent.toFixed(2),
      holdings: myHoldings.length
    };
  }, [holdings]);

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-md border-b border-white/10">
        <div className="flex items-center justify-between p-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => goBack()}
            className="text-white/80 hover:text-white hover:bg-white/10 p-2"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>

          <h1 className="text-lg font-bold text-white uppercase tracking-wider flex items-center gap-2">
            <Building2 className="h-5 w-5 bg-white/10" />
            Fixed Deposits
          </h1>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/investment/fd/add")}
            className="text-white/80 hover:text-white hover:bg-white/10 p-2"
            data-testid="button-add-fd"
          >
            <Plus className="h-5 w-5" />
          </Button>
        </div>

        {/* Portfolio Card */}
        <div className="px-6 pb-4">
          <Card className="bg-white/5 border border-white/10 rounded-none">
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-xs text-white/50 uppercase tracking-wider">Portfolio Value</p>
                  <p className="text-xl font-bold text-white mt-1">₹{Number(holdingStats.totalValue).toLocaleString()}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-white/50 uppercase tracking-wider">Annual Returns</p>
                  <div className="flex items-center gap-1 justify-end mt-1">
                    {Number(holdingStats.changePercent) >= 0 ? <TrendingUp className="h-4 w-4 bg-white/10" /> : <TrendingDown className="h-4 w-4 bg-white/10" />}
                    <p className={cn(
                      "text-xl font-bold",
                      Number(holdingStats.changePercent) >= 0 ? "bg-white/10" : "bg-white/10"
                    )}>
                      {Number(holdingStats.changePercent) >= 0 ? "+" : ""}{holdingStats.changePercent}%
                    </p>
                  </div>
                </div>
                <div className="text-center">
                  <p className="text-xs text-white/50 uppercase tracking-wider">Holdings</p>
                  <p className="text-xl font-bold text-white mt-1">{holdingStats.holdings}</p>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Search Box */}
        <div className="px-6 pb-4">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/40" />
            <Input
              placeholder="Search FDs by bank, type, or tenure..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="bg-transparent border-0 border-b-2 border-white/20 text-white pl-11 rounded-none h-12 focus:border-white placeholder:text-white/30"
              data-testid="input-search-fd"
            />
          </div>
        </div>
      </div>

      {/* Spacer for fixed header */}
      <div className="h-[280px]" />

      {/* FD Items List */}
      <div className="px-4 space-y-3">
        {pagination.paginatedData.map((fd) => {
          const rateHistory = generateRateHistory(fd.id, fd.interestRate, fd.change);
          const isPositive = fd.change >= 0;

          return (
            <Card 
              key={fd.id} 
              className="bg-white/5 border border-white/10 hover:bg-white/10 transition-colors cursor-pointer"
              onClick={() => navigate(`/investment/fd/${fd.id}`)}
              data-testid={`card-fd-${fd.id}`}
            >
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <h3 className="font-semibold text-white">{fd.bank}</h3>
                      <Badge variant="outline" className="text-xs bg-white/10 bg-white/10 bg-white/10">
                        {fd.type}
                      </Badge>
                    </div>
                    <p className="text-xs text-white/50 mb-2">{fd.tenure} • Rating: {fd.rating}</p>
                    <div className="flex items-baseline gap-3">
                      <div>
                        <p className="text-xs text-white/50">Interest Rate</p>
                        <p className="text-lg font-bold bg-white/10">{fd.interestRate}%</p>
                      </div>
                      <div>
                        <p className="text-xs text-white/50">Min Amount</p>
                        <p className="text-sm font-semibold text-white">₹{fd.minAmount.toLocaleString()}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-1 mt-1">
                      {isPositive ? <TrendingUp className="h-3 w-3 bg-white/10" /> : <TrendingDown className="h-3 w-3 bg-white/10" />}
                      <p className={cn(
                        "text-sm font-semibold",
                        isPositive ? "bg-white/10" : "bg-white/10"
                      )}>
                        {isPositive ? "+" : ""}{fd.change.toFixed(2)}%
                      </p>
                    </div>
                  </div>

                  <div className="w-24 h-16">
                    <MiniStockChart 
                      data={rateHistory} 
                      color={isPositive ? "#4ade80" : "#f87171"}
                    />
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}

        {filteredFD.length > 0 && (
          <PaginationControls
            currentPage={pagination.currentPage}
            totalPages={pagination.totalPages}
            onPageChange={pagination.goToPage}
            canGoNext={pagination.canGoNext}
            canGoPrevious={pagination.canGoPrevious}
            startIndex={pagination.startIndex}
            endIndex={pagination.endIndex}
            totalItems={pagination.totalItems}
            className="mt-6 mb-6"
          />
        )}
      </div>
    </div>
  );
}

client/src/pages/booking/bus/search.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  Bus,
  ArrowLeft,
  Calendar as CalendarIcon,
  Users,
  MapPin,
  ArrowRightLeft,
  Ticket
} from "lucide-react";
import { format } from "date-fns";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";
import { TicketHeader } from "@/components/ui/ticket-header";

const popularCities = [
  { code: "DEL", name: "Delhi" },
  { code: "MUM", name: "Mumbai" },
  { code: "BLR", name: "Bangalore" },
  { code: "CHN", name: "Chennai" },
  { code: "KOL", name: "Kolkata" },
  { code: "HYD", name: "Hyderabad" },
  { code: "PUN", name: "Pune" },
  { code: "AHM", name: "Ahmedabad" },
  { code: "JAI", name: "Jaipur" },
  { code: "LKO", name: "Lucknow" },
  { code: "SUR", name: "Surat" },
  { code: "NAG", name: "Nagpur" },
];

export default function BusSearch() {
  const [, navigate] = useLocation();
  const { toast } = useToast();

  const [tripType, setTripType] = useState<"oneway" | "roundtrip">("oneway");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [fromSearch, setFromSearch] = useState("");
  const [toSearch, setToSearch] = useState("");
  const [showFromPopover, setShowFromPopover] = useState(false);
  const [showToPopover, setShowToPopover] = useState(false);
  const [departureDate, setDepartureDate] = useState<Date>();
  const [returnDate, setReturnDate] = useState<Date>();
  const [showPassengers, setShowPassengers] = useState(false);
  const [passengers, setPassengers] = useState(1);

  const filteredFromCities = popularCities.filter(city =>
    city.name.toLowerCase().includes(fromSearch.toLowerCase()) ||
    city.code.toLowerCase().includes(fromSearch.toLowerCase())
  );

  const filteredToCities = popularCities.filter(city =>
    city.name.toLowerCase().includes(toSearch.toLowerCase()) ||
    city.code.toLowerCase().includes(toSearch.toLowerCase())
  );

  const swapLocations = () => {
    const temp = from;
    setFrom(to);
    setTo(temp);
  };

  const handleSearch = () => {
    if (!from || !to) {
      toast({
        title: "MISSING INFORMATION",
        description: "Please select both departure and destination cities",
        variant: "destructive"
      });
      return;
    }

    if (!departureDate) {
      toast({
        title: "MISSING INFORMATION",
        description: "Please select a departure date",
        variant: "destructive"
      });
      return;
    }

    if (tripType === "roundtrip" && !returnDate) {
      toast({
        title: "MISSING INFORMATION",
        description: "Please select a return date",
        variant: "destructive"
      });
      return;
    }

    const params = new URLSearchParams({
      from,
      to,
      departureDate: format(departureDate, "yyyy-MM-dd"),
      ...(returnDate && { returnDate: format(returnDate, "yyyy-MM-dd") }),
      passengers: passengers.toString(),
      tripType
    });

    navigate(`/booking/bus/results?${params.toString()}`);
  };

  const selectedFrom = popularCities.find(c => c.code === from);
  const selectedTo = popularCities.find(c => c.code === to);

  return (
    <div className="min-h-screen bg-black text-white">
      <TicketHeader 
        title="BOOK BUS" 
        subtitle="Search & book your journey"
        backPath="/home"
        ticketsPath="/all-tickets?type=bus&status=all"
        ticketIcon={<Bus className="h-5 w-5" />}
      />

      <div className="pt-24 px-4 pb-32 w-full max-w-screen-lg mx-auto space-y-8">
        {/* Trip Type */}
        <div className="space-y-3">
          <Label className="text-xs text-white/60 uppercase tracking-widest font-light block">Trip Type</Label>
          <div className="flex gap-2">
            {[
              { value: "oneway", label: "ONE WAY" },
              { value: "roundtrip", label: "ROUND TRIP" }
            ].map((type) => (
              <button
                key={type.value}
                onClick={() => setTripType(type.value as any)}
                className={cn(
                  "flex-1 py-3 border transition-all text-xs tracking-wider font-light rounded-none",
                  tripType === type.value
                    ? "bg-white text-black border-white"
                    : "bg-white/5 text-white/60 border-white/20 hover:border-white/40"
                )}
                data-testid={`button-trip-${type.value}`}
              >
                {type.label}
              </button>
            ))}
          </div>
        </div>

        {/* From & To */}
        <div className="space-y-4">
          {/* From */}
          <div className="space-y-2">
            <Label className="text-xs text-white/60 uppercase tracking-widest font-light flex items-center gap-2">
              <MapPin className="h-3 w-3" />
              FROM
            </Label>
            <Popover open={showFromPopover} onOpenChange={setShowFromPopover}>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    "w-full justify-start text-left bg-transparent border-b-2 border-white/20 rounded-none h-auto min-h-[64px] py-3 hover:bg-transparent hover:border-white px-3",
                    !from && "text-white/50"
                  )}
                  data-testid="button-from"
                >
                  {selectedFrom ? (
                    <div className="flex flex-col items-start w-full">
                      <div className="flex items-center gap-2">
                        <span className="text-2xl font-light">{selectedFrom.code}</span>
                        <span className="text-xs text-white/60">{selectedFrom.name}</span>
                      </div>
                    </div>
                  ) : (
                    <span className="font-light">Select departure city</span>
                  )}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-[400px] bg-black border-white/20 p-0" align="start">
                <Input
                  placeholder="Search cities..."
                  value={fromSearch}
                  onChange={(e) => setFromSearch(e.target.value)}
                  className="border-0 border-b border-white/20 rounded-none bg-transparent text-white"
                  data-testid="input-from-search"
                />
                <div className="max-h-64 overflow-y-auto">
                  {filteredFromCities.map((city) => (
                    <button
                      key={city.code}
                      onClick={() => {
                        setFrom(city.code);
                        setFromSearch("");
                        setShowFromPopover(false);
                      }}
                      className="w-full text-left px-4 py-3 hover:bg-white/10 transition-colors border-b border-white/10"
                      data-testid={`option-from-${city.code}`}
                    >
                      <div className="flex items-center justify-between">
                        <div>
                          <div className="font-light text-white">{city.name}</div>
                        </div>
                        <div className="text-lg font-light text-white/80">{city.code}</div>
                      </div>
                    </button>
                  ))}
                </div>
              </PopoverContent>
            </Popover>
          </div>

          {/* Swap Button */}
          <div className="flex justify-center -my-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={swapLocations}
              className="bg-white/10 text-white hover:bg-white/20 rounded-full h-10 w-10 p-0"
              data-testid="button-swap"
            >
              <ArrowRightLeft className="h-5 w-5" />
            </Button>
          </div>

          {/* To */}
          <div className="space-y-2">
            <Label className="text-xs text-white/60 uppercase tracking-widest font-light flex items-center gap-2">
              <MapPin className="h-3 w-3" />
              TO
            </Label>
            <Popover open={showToPopover} onOpenChange={setShowToPopover}>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    "w-full justify-start text-left bg-transparent border-b-2 border-white/20 rounded-none h-auto min-h-[64px] py-3 hover:bg-transparent hover:border-white px-3",
                    !to && "text-white/50"
                  )}
                  data-testid="button-to"
                >
                  {selectedTo ? (
                    <div className="flex flex-col items-start w-full">
                      <div className="flex items-center gap-2">
                        <span className="text-2xl font-light">{selectedTo.code}</span>
                        <span className="text-xs text-white/60">{selectedTo.name}</span>
                      </div>
                    </div>
                  ) : (
                    <span className="font-light">Select destination city</span>
                  )}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-[400px] bg-black border-white/20 p-0" align="start">
                <Input
                  placeholder="Search cities..."
                  value={toSearch}
                  onChange={(e) => setToSearch(e.target.value)}
                  className="border-0 border-b border-white/20 rounded-none bg-transparent text-white"
                  data-testid="input-to-search"
                />
                <div className="max-h-64 overflow-y-auto">
                  {filteredToCities.map((city) => (
                    <button
                      key={city.code}
                      onClick={() => {
                        setTo(city.code);
                        setToSearch("");
                        setShowToPopover(false);
                      }}
                      className="w-full text-left px-4 py-3 hover:bg-white/10 transition-colors border-b border-white/10"
                      data-testid={`option-to-${city.code}`}
                    >
                      <div className="flex items-center justify-between">
                        <div>
                          <div className="font-light text-white">{city.name}</div>
                        </div>
                        <div className="text-lg font-light text-white/80">{city.code}</div>
                      </div>
                    </button>
                  ))}
                </div>
              </PopoverContent>
            </Popover>
          </div>
        </div>

        {/* Dates */}
        <div className="space-y-4">
          <div className={cn("grid gap-6", tripType === "roundtrip" ? "grid-cols-2" : "grid-cols-1")}>
            {/* Departure Date */}
            <div className="space-y-2">
              <Label className="text-xs text-white/60 uppercase tracking-widest font-light flex items-center gap-2">
                <CalendarIcon className="h-3 w-3" />
                DEPARTURE
              </Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left bg-transparent border-b-2 border-white/20 rounded-none h-14 hover:bg-transparent hover:border-white px-3 font-light",
                      !departureDate && "text-white/50"
                    )}
                    data-testid="button-departure-date"
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {departureDate ? format(departureDate, "EEE, dd MMM yyyy") : "Select date"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0 bg-black border-white/20" align="start">
                  <Calendar
                    mode="single"
                    selected={departureDate}
                    onSelect={setDepartureDate}
                    disabled={(date) => date < new Date()}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>

            {/* Return Date */}
            {tripType === "roundtrip" && (
              <div className="space-y-2">
                <Label className="text-xs text-white/60 uppercase tracking-widest font-light flex items-center gap-2">
                  <CalendarIcon className="h-3 w-3" />
                  RETURN
                </Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full justify-start text-left bg-transparent border-b-2 border-white/20 rounded-none h-14 hover:bg-transparent hover:border-white px-3 font-light",
                        !returnDate && "text-white/50"
                      )}
                      data-testid="button-return-date"
                    >
                      <CalendarIcon className="mr-2 h-4 w-4" />
                      {returnDate ? format(returnDate, "EEE, dd MMM yyyy") : "Select date"}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0 bg-black border-white/20" align="start">
                    <Calendar
                      mode="single"
                      selected={returnDate}
                      onSelect={setReturnDate}
                      disabled={(date) => {
                        const minDate = departureDate || new Date();
                        return date < minDate;
                      }}
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>
              </div>
            )}
          </div>
        </div>

        {/* Passengers */}
        <div className="space-y-2">
            <Label className="text-xs text-white/60 uppercase tracking-widest font-light flex items-center gap-2">
              <Users className="h-3 w-3" />
              PASSENGERS
            </Label>
            <Popover open={showPassengers} onOpenChange={setShowPassengers}>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className="w-full justify-start text-left bg-transparent border-b-2 border-white/20 rounded-none h-14 hover:bg-transparent hover:border-white px-3 font-light"
                  data-testid="button-passengers"
                >
                  <Users className="mr-2 h-4 w-4" />
                  {passengers} Passenger{passengers !== 1 ? 's' : ''}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-80 bg-black border-white/20 p-4" align="start">
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="text-sm text-white font-light">Passengers</div>
                    </div>
                    <div className="flex items-center gap-3">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setPassengers(p => Math.max(1, p - 1))}
                        disabled={passengers <= 1}
                        className="h-8 w-8 p-0 rounded-none bg-white/5 border-white/20"
                        data-testid="button-passengers-decrease"
                      >
                        -
                      </Button>
                      <span className="w-8 text-center font-light" data-testid="text-passengers-count">{passengers}</span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setPassengers(p => Math.min(9, p + 1))}
                        disabled={passengers >= 9}
                        className="h-8 w-8 p-0 rounded-none bg-white/5 border-white/20"
                        data-testid="button-passengers-increase"
                      >
                        +
                      </Button>
                    </div>
                  </div>

                  <Button
                    onClick={() => setShowPassengers(false)}
                    className="w-full bg-white text-black hover:bg-white/90 rounded-none"
                    data-testid="button-passengers-done"
                  >
                    DONE
                  </Button>
                </div>
              </PopoverContent>
            </Popover>
          </div>

        {/* Popular Routes */}
        <div className="space-y-4">
          <Label className="text-xs text-white/60 uppercase tracking-widest font-light block">Popular Routes</Label>
          <div className="grid grid-cols-2 gap-2">
            {[
              { from: "DEL", to: "MUM", label: "Delhi → Mumbai" },
              { from: "BLR", to: "CHN", label: "Bangalore → Chennai" },
              { from: "MUM", to: "PUN", label: "Mumbai → Pune" },
              { from: "DEL", to: "JAI", label: "Delhi → Jaipur" },
            ].map((route, idx) => (
              <button
                key={idx}
                onClick={() => {
                  setFrom(route.from);
                  setTo(route.to);
                }}
                className="px-4 py-3 border border-white/20 hover:border-white/40 transition-all text-left bg-white/5 hover:bg-white/10 rounded-none"
                data-testid={`button-route-${route.from}-${route.to}`}
              >
                <div className="text-xs text-white/60 font-light uppercase tracking-wider">Popular</div>
                <div className="text-sm text-white font-light mt-1">{route.label}</div>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Fixed Search Button */}
      <div className="fixed bottom-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4">
        <Button
          onClick={handleSearch}
          className="w-full bg-white text-black hover:bg-white/90 rounded-none h-14 text-base tracking-wider font-light"
          data-testid="button-search-buses"
        >
          <Bus className="mr-2 h-5 w-5" />
          SEARCH BUSES
        </Button>
      </div>
    </div>
  );
}

client/src/pages/add-account.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { ArrowLeft, Building2, CheckCircle } from "lucide-react";

const addAccountSchema = z.object({
  bankName: z.string().min(1, "Bank name is required"),
  accountNumber: z.string().min(8, "Account number must be at least 8 digits").max(18, "Account number must not exceed 18 digits"),
  confirmAccountNumber: z.string().min(8, "Please confirm your account number"),
  accountType: z.enum(["savings", "current", "salary"], {
    required_error: "Please select an account type",
  }),
  ifscCode: z.string().regex(/^[A-Z]{4}0[A-Z0-9]{6}$/, "Invalid IFSC code format"),
  branch: z.string().min(1, "Branch name is required"),
  accountHolderName: z.string().min(1, "Account holder name is required"),
}).refine((data) => data.accountNumber === data.confirmAccountNumber, {
  message: "Account numbers don't match",
  path: ["confirmAccountNumber"],
});

type AddAccountForm = z.infer<typeof addAccountSchema>;

const popularBanks = [
  "State Bank of India (SBI)",
  "HDFC Bank",
  "ICICI Bank",
  "Axis Bank",
  "Kotak Mahindra Bank",
  "Punjab National Bank (PNB)",
  "Bank of Baroda",
  "Canara Bank",
  "Union Bank of India",
  "IndusInd Bank",
  "Yes Bank",
  "IDFC First Bank",
  "RBL Bank",
  "Federal Bank",
  "South Indian Bank",
  "Other"
];

export default function AddAccount() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const form = useForm<AddAccountForm>({
    resolver: zodResolver(addAccountSchema),
    defaultValues: {
      bankName: "",
      accountNumber: "",
      confirmAccountNumber: "",
      accountType: undefined,
      ifscCode: "",
      branch: "",
      accountHolderName: "",
    },
  });

  const onSubmit = async (data: AddAccountForm) => {
    setIsSubmitting(true);

    // Simulate API call
    await new Promise((resolve) => setTimeout(resolve, 1500));

    setIsSubmitting(false);
    setShowSuccess(true);

    // Show success message and redirect after delay
    setTimeout(() => {
      toast({
        title: "Account Added Successfully",
        description: `${data.bankName} account linked to your profile`,
      });
      navigate("/my-bank-accounts");
    }, 2000);
  };

  if (showSuccess) {
    return (
      <div className="min-h-screen bg-black text-white pb-20">
        <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-md border-b border-white/10">
          <div className="flex items-center justify-between py-6 px-4">
            <div className="w-10"></div>
            <h1 className="text-lg font-semibold tracking-wider">ACCOUNT ADDED</h1>
            <div className="w-10"></div>
          </div>
        </div>

        <div className="pt-32 px-4">
          <div className="max-w-md mx-auto">
            <Card className="bg-gradient-to-br from-white/10 to-white/5 border border-white/20 rounded-none">
              <CardContent className="p-12 text-center">
                <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-4">
                  <CheckCircle className="h-10 w-10 text-white/80" />
                </div>
                <h2 className="text-2xl font-bold mb-2 text-white">Success!</h2>
                <p className="text-white/60 mb-6">
                  Your bank account has been added successfully
                </p>
                <p className="text-sm text-white/40">
                  Redirecting to your accounts...
                </p>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white pb-20 overflow-x-hidden">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-md border-b border-white/10">
        <div className="flex items-center justify-between py-6 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/my-bank-accounts")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <h1 className="text-lg font-semibold tracking-wider">ADD BANK ACCOUNT</h1>
          <div className="w-10"></div>
        </div>
      </div>

      {/* Content */}
      <div className="pt-24 px-4">
        <div className="max-w-2xl mx-auto">
          {/* Info Card */}
          <Card className="bg-white/5 border border-white/20 rounded-none mb-6">
            <CardContent className="p-6">
              <div className="flex items-start gap-4">
                <div className="bg-white/10 rounded-full p-3">
                  <Building2 className="h-6 w-6 text-white/80" />
                </div>
                <div className="flex-1">
                  <h3 className="text-base font-semibold text-white mb-2">
                    Link Your Bank Account
                  </h3>
                  <p className="text-sm text-white/60">
                    Connect your bank account to enable seamless payments, transfers, and financial tracking.
                    Your information is encrypted and secure.
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Form Card */}
          <Card className="bg-white/5 border border-white/10 rounded-none">
            <CardHeader>
              <CardTitle className="text-xl text-white">Account Details</CardTitle>
            </CardHeader>
            <CardContent>
              <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                  {/* Account Holder Name */}
                  <FormField
                    control={form.control}
                    name="accountHolderName"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white/80">Account Holder Name</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="Enter full name as per bank records"
                            className="bg-white/10 border-white/20 text-white placeholder:text-white/40 focus:border-white/40"
                            data-testid="input-account-holder"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage className="text-white/80" />
                      </FormItem>
                    )}
                  />

                  {/* Bank Name */}
                  <FormField
                    control={form.control}
                    name="bankName"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white/80">Bank Name</FormLabel>
                        <Select onValueChange={field.onChange} value={field.value}>
                          <FormControl>
                            <SelectTrigger className="bg-white/10 border-white/20 text-white" data-testid="select-bank">
                              <SelectValue placeholder="Select your bank" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent className="bg-black border-white/20">
                            {popularBanks.map((bank) => (
                              <SelectItem key={bank} value={bank} className="text-white focus:bg-white/10">
                                {bank}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage className="text-white/80" />
                      </FormItem>
                    )}
                  />

                  {/* Account Type */}
                  <FormField
                    control={form.control}
                    name="accountType"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white/80">Account Type</FormLabel>
                        <Select onValueChange={field.onChange} value={field.value}>
                          <FormControl>
                            <SelectTrigger className="bg-white/10 border-white/20 text-white" data-testid="select-account-type">
                              <SelectValue placeholder="Select account type" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent className="bg-black border-white/20">
                            <SelectItem value="savings" className="text-white focus:bg-white/10">Savings Account</SelectItem>
                            <SelectItem value="current" className="text-white focus:bg-white/10">Current Account</SelectItem>
                            <SelectItem value="salary" className="text-white focus:bg-white/10">Salary Account</SelectItem>
                          </SelectContent>
                        </Select>
                        <FormMessage className="text-white/80" />
                      </FormItem>
                    )}
                  />

                  {/* Account Number */}
                  <FormField
                    control={form.control}
                    name="accountNumber"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white/80">Account Number</FormLabel>
                        <FormControl>
                          <Input
                            type="text"
                            placeholder="Enter account number"
                            className="bg-white/10 border-white/20 text-white placeholder:text-white/40 focus:border-white/40"
                            data-testid="input-account-number"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage className="text-white/80" />
                      </FormItem>
                    )}
                  />

                  {/* Confirm Account Number */}
                  <FormField
                    control={form.control}
                    name="confirmAccountNumber"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white/80">Confirm Account Number</FormLabel>
                        <FormControl>
                          <Input
                            type="text"
                            placeholder="Re-enter account number"
                            className="bg-white/10 border-white/20 text-white placeholder:text-white/40 focus:border-white/40"
                            data-testid="input-confirm-account"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage className="text-white/80" />
                      </FormItem>
                    )}
                  />

                  {/* IFSC Code */}
                  <FormField
                    control={form.control}
                    name="ifscCode"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white/80">IFSC Code</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="e.g., HDFC0001234"
                            className="bg-white/10 border-white/20 text-white placeholder:text-white/40 focus:border-white/40 uppercase"
                            data-testid="input-ifsc"
                            {...field}
                            onChange={(e) => field.onChange(e.target.value.toUpperCase())}
                          />
                        </FormControl>
                        <FormMessage className="text-white/80" />
                      </FormItem>
                    )}
                  />

                  {/* Branch */}
                  <FormField
                    control={form.control}
                    name="branch"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white/80">Branch Name</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="Enter branch name"
                            className="bg-white/10 border-white/20 text-white placeholder:text-white/40 focus:border-white/40"
                            data-testid="input-branch"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage className="text-white/80" />
                      </FormItem>
                    )}
                  />

                  {/* Submit Button */}
                  <div className="pt-4">
                    <Button
                      type="submit"
                      disabled={isSubmitting}
                      className="w-full bg-white text-black hover:bg-white/90 h-12 text-base font-semibold"
                      data-testid="button-submit"
                    >
                      {isSubmitting ? "Adding Account..." : "Add Account"}
                    </Button>
                  </div>
                </form>
              </Form>
            </CardContent>
          </Card>

          {/* Security Notice */}
          <div className="mt-6 text-center">
            <p className="text-xs text-white/40">
              🔒 Your bank details are encrypted and stored securely. We never share your information with third parties.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

client/src/pages/sip-new.tsx.content:
import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/use-auth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { DatePicker } from "@/components/ui/date-picker";
import { Separator } from "@/components/ui/separator";
import { Badge } from "@/components/ui/badge";
import { 
  ArrowLeft, 
  TrendingUp, 
  Calendar, 
  Target, 
  Clock,
  DollarSign,
  Zap,
  Shield,
  Info,
  CheckCircle2
} from "lucide-react";

export default function SipNew() {
  const [, navigate] = useLocation();
  const { isAuthenticated, isLoading: authLoading, user } = useAuth();
  const { toast } = useToast();

  const [selectedFund, setSelectedFund] = useState<string>("");
  const [sipAmount, setSipAmount] = useState("500");
  const [frequency, setFrequency] = useState("monthly");
  const [sipDay, setSipDay] = useState("1");
  const [startDate, setStartDate] = useState("");
  const [endCondition, setEndCondition] = useState("until_cancelled");
  const [totalInstallments, setTotalInstallments] = useState("12");
  const [targetAmount, setTargetAmount] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("auto_debit");
  const [autoEscalation, setAutoEscalation] = useState(false);
  const [escalationPercent, setEscalationPercent] = useState("10");

  // Fetch mutual funds
  const { data: fundsData, isLoading: fundsLoading } = useQuery({
    queryKey: ["/api/mutual-funds"],
    enabled: isAuthenticated,
  });

  // Create SIP mutation
  const createSipMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest("POST", "/api/sip/create", data);
    },
    onSuccess: () => {
      toast({
        title: "SIP Created Successfully",
        description: "Your systematic investment plan has been set up",
      });
      navigate("/investment");
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Create SIP",
        description: error.message || "Please try again",
        variant: "destructive",
      });
    },
  });

  useEffect(() => {
    if (!authLoading && !isAuthenticated) {
      navigate("/");
    }
  }, [isAuthenticated, authLoading, navigate]);

  useEffect(() => {
    // Set default start date to next month
    const nextMonth = new Date();
    nextMonth.setMonth(nextMonth.getMonth() + 1);
    nextMonth.setDate(1);
    setStartDate(nextMonth.toISOString().split('T')[0]);
  }, []);

  if (!isAuthenticated && !authLoading) {
    return null;
  }

  const funds = fundsData?.funds || [];
  const selectedFundData = funds.find((f: any) => f.id === selectedFund);

  const calculateProjectedValue = () => {
    if (!sipAmount || !totalInstallments) return 0;
    const amount = parseFloat(sipAmount);
    const months = endCondition === "fixed_installments" ? parseInt(totalInstallments) : 60;
    const expectedReturn = selectedFundData?.returns1Year || 12;
    const monthlyReturn = expectedReturn / 100 / 12;

    let futureValue = 0;
    for (let i = 0; i < months; i++) {
      futureValue = (futureValue + amount) * (1 + monthlyReturn);
    }
    return futureValue;
  };

  const handleSubmit = () => {
    if (!selectedFund) {
      toast({
        title: "Select a Fund",
        description: "Please select a mutual fund for your SIP",
        variant: "destructive",
      });
      return;
    }

    if (!sipAmount || parseFloat(sipAmount) < 500) {
      toast({
        title: "Invalid Amount",
        description: "Minimum SIP amount is ₹500",
        variant: "destructive",
      });
      return;
    }

    const sipData = {
      userId: user?.id,
      fundId: selectedFund,
      sipAmount: parseFloat(sipAmount),
      frequency,
      sipDay: parseInt(sipDay),
      startDate: new Date(startDate),
      endCondition,
      totalInstallments: endCondition === "fixed_installments" ? parseInt(totalInstallments) : null,
      targetAmount: endCondition === "target_amount" ? parseFloat(targetAmount) : null,
      paymentMethod,
      autoEscalation: autoEscalation ? 1 : 0,
      escalationPercent: autoEscalation ? parseFloat(escalationPercent) : null,
      escalationFrequency: autoEscalation ? "yearly" : null,
    };

    createSipMutation.mutate(sipData);
  };

  const projectedValue = calculateProjectedValue();
  const totalInvestment = parseFloat(sipAmount) * (endCondition === "fixed_installments" ? parseInt(totalInstallments) : 60);
  const expectedReturns = projectedValue - totalInvestment;

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Header */}
      <div className="fixed top-0 left-0 right-0 z-10 bg-black/95 backdrop-blur-sm border-b border-white/10">
        <div className="flex items-center gap-4 p-6">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate("/investment")}
            className="text-white hover:bg-white/10"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-xl font-bold">Start New SIP</h1>
            <p className="text-sm text-white/60">Systematic Investment Plan</p>
          </div>
        </div>
      </div>

      <div className="p-4 space-y-6 pt-20">
        {/* Select Fund */}
        <Card className="bg-white/5 border-white/10">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Target className="h-5 w-5 text-white/80" />
              Select Mutual Fund
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label className="text-white/80">Choose Fund</Label>
              <Select value={selectedFund} onValueChange={setSelectedFund}>
                <SelectTrigger className="bg-white/5 border-white/20 text-white" data-testid="select-fund">
                  <SelectValue placeholder="Select a mutual fund" />
                </SelectTrigger>
                <SelectContent>
                  {fundsLoading ? (
                    <SelectItem value="loading">Loading funds...</SelectItem>
                  ) : funds.length > 0 ? (
                    funds.map((fund: any) => (
                      <SelectItem key={fund.id} value={fund.id}>
                        {fund.fundName} - {fund.fundHouse}
                      </SelectItem>
                    ))
                  ) : (
                    <SelectItem value="no-funds">No funds available</SelectItem>
                  )}
                </SelectContent>
              </Select>
            </div>

            {selectedFundData && (
              <div className="p-3 rounded-lg bg-white/5 space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-white/60">NAV</span>
                  <span className="text-white font-semibold">₹{parseFloat(selectedFundData.nav).toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-white/60">1Y Returns</span>
                  <span className="text-white/80 font-semibold">+{parseFloat(selectedFundData.returns1Year || 0).toFixed(2)}%</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-white/60">Min SIP</span>
                  <span className="text-white font-semibold">₹{parseFloat(selectedFundData.minSipAmount || 500).toFixed(0)}</span>
                </div>
                <Badge className={`${
                  selectedFundData.riskLevel === 'low' ? 'bg-white/10 text-white/80' :
                  selectedFundData.riskLevel === 'medium' ? 'bg-white/10 text-white/80' :
                  'bg-white/10 text-white/80'
                } border-0`}>
                  {selectedFundData.riskLevel} Risk
                </Badge>
              </div>
            )}
          </CardContent>
        </Card>

        {/* SIP Amount */}
        <Card className="bg-white/5 border-white/10">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <DollarSign className="h-5 w-5 text-white/80" />
              SIP Amount
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label className="text-white/80">Monthly Investment Amount</Label>
              <Input
                type="number"
                value={sipAmount}
                onChange={(e) => setSipAmount(e.target.value)}
                placeholder="500"
                className="bg-white/5 border-white/20 text-white"
                data-testid="input-sip-amount"
              />
              <p className="text-xs text-white/50 mt-1">Minimum: ₹500</p>
            </div>

            <div className="grid grid-cols-3 gap-2">
              {["500", "1000", "2500", "5000"].map((amount) => (
                <Button
                  key={amount}
                  variant="outline"
                  size="sm"
                  onClick={() => setSipAmount(amount)}
                  className={`${
                    sipAmount === amount
                      ? "bg-white/10 text-white border-white/20"
                      : "bg-white/5 border-white/20 text-white hover:bg-white/10"
                  }`}
                  data-testid={`button-preset-${amount}`}
                >
                  ₹{amount}
                </Button>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Frequency & Schedule */}
        <Card className="bg-white/5 border-white/10">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Clock className="h-5 w-5 text-white/80" />
              Frequency & Schedule
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label className="text-white/80">Frequency</Label>
              <Select value={frequency} onValueChange={setFrequency}>
                <SelectTrigger className="bg-white/5 border-white/20 text-white" data-testid="select-frequency">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="monthly">Monthly</SelectItem>
                  <SelectItem value="quarterly">Quarterly</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label className="text-white/80">SIP Day</Label>
                <Input
                  type="number"
                  min="1"
                  max="28"
                  value={sipDay}
                  onChange={(e) => setSipDay(e.target.value)}
                  className="bg-white/5 border-white/20 text-white"
                  data-testid="input-sip-day"
                />
              </div>

              <div>
                <Label className="text-white/80">Start Date</Label>
                <DatePicker
                  value={startDate}
                  onChange={setStartDate}
                  placeholder="Select start date"
                  className="bg-white/5 border-white/20 text-white"
                  data-testid="input-start-date"
                />
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Duration */}
        <Card className="bg-white/5 border-white/10">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Calendar className="h-5 w-5 text-white/80" />
              Duration
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <RadioGroup value={endCondition} onValueChange={setEndCondition}>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="until_cancelled" id="until_cancelled" data-testid="radio-until-cancelled" />
                <Label htmlFor="until_cancelled" className="text-white cursor-pointer">Until I cancel</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="fixed_installments" id="fixed_installments" data-testid="radio-fixed-installments" />
                <Label htmlFor="fixed_installments" className="text-white cursor-pointer">Fixed number of installments</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="target_amount" id="target_amount" data-testid="radio-target-amount" />
                <Label htmlFor="target_amount" className="text-white cursor-pointer">Target amount</Label>
              </div>
            </RadioGroup>

            {endCondition === "fixed_installments" && (
              <div>
                <Label className="text-white/80">Number of Installments</Label>
                <Input
                  type="number"
                  value={totalInstallments}
                  onChange={(e) => setTotalInstallments(e.target.value)}
                  placeholder="12"
                  className="bg-white/5 border-white/20 text-white"
                  data-testid="input-installments"
                />
              </div>
            )}

            {endCondition === "target_amount" && (
              <div>
                <Label className="text-white/80">Target Amount (₹)</Label>
                <Input
                  type="number"
                  value={targetAmount}
                  onChange={(e) => setTargetAmount(e.target.value)}
                  placeholder="100000"
                  className="bg-white/5 border-white/20 text-white"
                  data-testid="input-target-amount"
                />
              </div>
            )}
          </CardContent>
        </Card>

        {/* Auto Escalation */}
        <Card className="bg-white/5 border-white/10">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <TrendingUp className="h-5 w-5 text-white/80" />
              Auto Escalation (Optional)
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <Label className="text-white/80">Enable Auto Escalation</Label>
              <input
                type="checkbox"
                checked={autoEscalation}
                onChange={(e) => setAutoEscalation(e.target.checked)}
                className="w-4 h-4"
                data-testid="checkbox-auto-escalation"
              />
            </div>

            {autoEscalation && (
              <div>
                <Label className="text-white/80">Annual Increase (%)</Label>
                <Input
                  type="number"
                  value={escalationPercent}
                  onChange={(e) => setEscalationPercent(e.target.value)}
                  placeholder="10"
                  className="bg-white/5 border-white/20 text-white"
                  data-testid="input-escalation-percent"
                />
                <p className="text-xs text-white/50 mt-1">Your SIP amount will increase by this percentage every year</p>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Projection */}
        {selectedFund && sipAmount && (
          <Card className="bg-gradient-to-r from-white/10 to-white/5 border-white/20">
            <CardHeader>
              <CardTitle className="text-white flex items-center gap-2">
                <Zap className="h-5 w-5 text-white/80" />
                Projected Returns
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex justify-between">
                <span className="text-white/70">Total Investment</span>
                <span className="text-white font-semibold">₹{totalInvestment.toLocaleString()}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-white/70">Expected Value</span>
                <span className="text-white font-semibold">₹{projectedValue.toLocaleString(undefined, {maximumFractionDigits: 0})}</span>
              </div>
              <Separator className="bg-white/20" />
              <div className="flex justify-between">
                <span className="text-white/70">Estimated Returns</span>
                <span className="text-white/80 font-bold">+₹{expectedReturns.toLocaleString(undefined, {maximumFractionDigits: 0})}</span>
              </div>
              <p className="text-xs text-white/50 text-center mt-2">
                Based on historical returns. Actual returns may vary.
              </p>
            </CardContent>
          </Card>
        )}

        {/* Payment Method */}
        <Card className="bg-white/5 border-white/10">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Shield className="h-5 w-5 text-white/80" />
              Payment Method
            </CardTitle>
          </CardHeader>
          <CardContent>
            <RadioGroup value={paymentMethod} onValueChange={setPaymentMethod}>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="auto_debit" id="auto_debit" data-testid="radio-auto-debit" />
                <Label htmlFor="auto_debit" className="text-white cursor-pointer">Auto Debit (e-Mandate)</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="manual" id="manual" data-testid="radio-manual" />
                <Label htmlFor="manual" className="text-white cursor-pointer">Manual Payment</Label>
              </div>
            </RadioGroup>
          </CardContent>
        </Card>

        {/* Submit Button */}
        <div className="fixed bottom-0 left-0 right-0 p-4 bg-black/95 backdrop-blur-sm border-t border-white/10">
          <Button
            onClick={handleSubmit}
            disabled={createSipMutation.isPending || !selectedFund}
            className="w-full bg-white/10 hover:bg-white/15 text-white h-12"
            data-testid="button-create-sip"
          >
            {createSipMutation.isPending ? (
              "Creating SIP..."
            ) : (
              <>
                <CheckCircle2 className="h-5 w-5 mr-2" />
                Create SIP
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

client/src/components/ui/chart.tsx.content:
"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"

import { cn } from "@/lib/utils"

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const

export type ChartConfig = {
  [k in string]: {
    label?: React.ReactNode
    icon?: React.ComponentType
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
}

type ChartContextProps = {
  config: ChartConfig
}

const ChartContext = React.createContext<ChartContextProps | null>(null)

function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

const ChartContainer = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    config: ChartConfig
    children: React.ComponentProps<
      typeof RechartsPrimitive.ResponsiveContainer
    >["children"]
  }
>(({ id, className, children, config, ...props }, ref) => {
  const uniqueId = React.useId()
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-chart={chartId}
        ref={ref}
        className={cn(
          "flex aspect-video justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-none [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-none [&_.recharts-surface]:outline-none",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
})
ChartContainer.displayName = "Chart"

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme || config.color
  )

  if (!colorConfig.length) {
    return null
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ||
      itemConfig.color
    return color ? `  --color-${key}: ${color};` : null
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  )
}

const ChartTooltip = RechartsPrimitive.Tooltip

const ChartTooltipContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
    React.ComponentProps<"div"> & {
      hideLabel?: boolean
      hideIndicator?: boolean
      indicator?: "line" | "dot" | "dashed"
      nameKey?: string
      labelKey?: string
    }
>(
  (
    {
      active,
      payload,
      className,
      indicator = "dot",
      hideLabel = false,
      hideIndicator = false,
      label,
      labelFormatter,
      labelClassName,
      formatter,
      color,
      nameKey,
      labelKey,
    },
    ref
  ) => {
    const { config } = useChart()

    const tooltipLabel = React.useMemo(() => {
      if (hideLabel || !payload?.length) {
        return null
      }

      const [item] = payload
      const key = `${labelKey || item?.dataKey || item?.name || "value"}`
      const itemConfig = getPayloadConfigFromPayload(config, item, key)
      const value =
        !labelKey && typeof label === "string"
          ? config[label as keyof typeof config]?.label || label
          : itemConfig?.label

      if (labelFormatter) {
        return (
          <div className={cn("font-medium", labelClassName)}>
            {labelFormatter(value, payload)}
          </div>
        )
      }

      if (!value) {
        return null
      }

      return <div className={cn("font-medium", labelClassName)}>{value}</div>
    }, [
      label,
      labelFormatter,
      payload,
      hideLabel,
      labelClassName,
      config,
      labelKey,
    ])

    if (!active || !payload?.length) {
      return null
    }

    const nestLabel = payload.length === 1 && indicator !== "dot"

    return (
      <div
        ref={ref}
        className={cn(
          "grid min-w-[8rem] items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
          className
        )}
      >
        {!nestLabel ? tooltipLabel : null}
        <div className="grid gap-1.5">
          {payload.map((item, index) => {
            const key = `${nameKey || item.name || item.dataKey || "value"}`
            const itemConfig = getPayloadConfigFromPayload(config, item, key)
            const indicatorColor = color || item.payload.fill || item.color

            return (
              <div
                key={item.dataKey}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-[--color-border] bg-[--color-bg]",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label || item.name}
                        </span>
                      </div>
                      {item.value && (
                        <span className="font-mono font-medium tabular-nums text-foreground">
                          {item.value.toLocaleString()}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
        </div>
      </div>
    )
  }
)
ChartTooltipContent.displayName = "ChartTooltip"

const ChartLegend = RechartsPrimitive.Legend

const ChartLegendContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> &
    Pick<RechartsPrimitive.LegendProps, "payload" | "verticalAlign"> & {
      hideIcon?: boolean
      nameKey?: string
    }
>(
  (
    { className, hideIcon = false, payload, verticalAlign = "bottom", nameKey },
    ref
  ) => {
    const { config } = useChart()

    if (!payload?.length) {
      return null
    }

    return (
      <div
        ref={ref}
        className={cn(
          "flex items-center justify-center gap-4",
          verticalAlign === "top" ? "pb-3" : "pt-3",
          className
        )}
      >
        {payload.map((item) => {
          const key = `${nameKey || item.dataKey || "value"}`
          const itemConfig = getPayloadConfigFromPayload(config, item, key)

          return (
            <div
              key={item.value}
              className={cn(
                "flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground"
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div
                  className="h-2 w-2 shrink-0 rounded-[2px]"
                  style={{
                    backgroundColor: item.color,
                  }}
                />
              )}
              {itemConfig?.label}
            </div>
          )
        })}
      </div>
    )
  }
)
ChartLegendContent.displayName = "ChartLegend"

// Helper to extract item config from a payload.
function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  return configLabelKey in config
    ? config[configLabelKey]
    : config[key as keyof typeof config]
}

export {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
}

