                    )}
                    {referral.milestones.firstTransaction && (
                      <Badge className="bg-white/10 text-white/60 border-white/10 rounded-none text-xs px-2 py-0.5">
                        First Transaction
                      </Badge>
                    )}
                    {referral.milestones.monthlyActive && (
