import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { ArrowLeft, Store, CreditCard, Check, Lock, Shield, TrendingUp } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import type { CreditUpiAccount } from "@shared/schema";
import QRCode from "react-qr-code";

export default function CreditUpiPay() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [merchantName, setMerchantName] = useState("");
  const [merchantUpi, setMerchantUpi] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("shopping");
  const [description, setDescription] = useState("");
  const [processing, setProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const { data: accountData } = useQuery<{ account: CreditUpiAccount | null }>({
    queryKey: ["/api/credit-upi/account"],
  });

  const account = accountData?.account;
  const availableLimit = parseFloat(account?.availableLimit || "0");

  const handlePay = async () => {
    if (!merchantName.trim()) {
      toast({
        title: "Error",
        description: "Please enter merchant name",
        variant: "destructive",
      });
      return;
    }

    const payAmount = parseFloat(amount);
    if (!payAmount || payAmount <= 0) {
      toast({
        title: "Error",
        description: "Please enter a valid amount",
        variant: "destructive",
      });
      return;
    }

    if (payAmount > availableLimit) {
      toast({
        title: "Insufficient Credit",
        description: `You only have ₹${availableLimit.toLocaleString('en-IN')} available`,
        variant: "destructive",
      });
      return;
    }

    setProcessing(true);
    try {
      const response = await apiRequest("POST", "/api/credit-upi/transaction", {
        merchantName: merchantName.trim(),
        merchantUpi: merchantUpi.trim() || undefined,
        amount: payAmount,
        category,
        description: description.trim() || undefined,
      });
      const result = await response.json();

      if (!result.success) {
        toast({
          title: "Payment Failed",
          description: result.message || "Failed to process payment",
          variant: "destructive",
        });
        return;
      }

      setShowSuccess(true);
      queryClient.invalidateQueries({ queryKey: ["/api/credit-upi/account"] });
      queryClient.invalidateQueries({ queryKey: ["/api/credit-upi/transactions"] });

      setTimeout(() => {
        navigate("/credit-upi");
      }, 2000);
    } catch (error: any) {
      toast({
        title: "Payment Failed",
        description: error.message || "Failed to process payment",
        variant: "destructive",
      });
    } finally {
      setProcessing(false);
    }
  };

  if (showSuccess) {
    return (
      <div className="min-h-screen bg-black p-6 flex items-center justify-center">
        <div className="text-center space-y-6">
          <div className="w-20 h-20 border-2 border-white flex items-center justify-center mx-auto">
            <Check className="h-10 w-10 text-white" />
          </div>
          <h2 className="text-3xl font-light text-white tracking-wider uppercase">PAYMENT SUCCESSFUL</h2>
          <p className="text-white/70 font-light tracking-wider">Your payment has been processed successfully</p>
          <div className="text-3xl font-light text-white tracking-tight">₹{parseFloat(amount).toLocaleString('en-IN')}</div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white pb-32">
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/credit-upi")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">MAKE PAYMENT</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Pay Using Credit UPI</p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      <div className="pt-20 px-4 space-y-8 w-full max-w-screen-lg mx-auto">
        {/* Payment Amount Card with QR Code - UPI Payment Style */}
        <div className="border border-white/20 p-6 bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-xl">
          <div className="flex items-start justify-between gap-6">
            <div className="flex-1">
              <Label className="text-xs text-white/60 mb-4 uppercase tracking-widest font-light block">Payment Amount</Label>
              <div className="relative max-w-md">
                <span className="absolute left-0 top-1/2 -translate-y-1/2 text-4xl font-light text-white/60">₹</span>
                <Input
                  id="amount"
                  type="text"
                  inputMode="decimal"
                  value={amount}
                  onChange={(e) => {
                    const value = e.target.value.replace(/[^0-9.]/g, '');
                    const parts = value.split('.');
                    if (parts.length <= 2 && (!parts[1] || parts[1].length <= 2)) {
                      setAmount(value);
                    }
                  }}
                  placeholder="0"
                  className="text-5xl font-light text-white tracking-tight bg-transparent border-0 border-b-2 border-white/20 rounded-none pl-12 focus:border-white h-20 placeholder:text-white/20"
                  data-testid="input-amount"
                />
              </div>
              <div className="flex items-center gap-2 mt-4">
                <TrendingUp className="h-4 w-4 text-white/60" />
                <span className="text-xs text-white/60 font-light tracking-wider">
                  Available Credit: ₹{availableLimit.toLocaleString('en-IN')}
                </span>
              </div>
            </div>

            {/* QR Code on Right */}
            <div className="flex flex-col items-center gap-2">
              <div className="bg-white p-3 rounded-lg">
                <QRCode
                  value={`upi://pay?pa=${merchantUpi || 'merchant@upi'}&pn=${merchantName || 'Merchant'}&am=${amount || '0'}&cu=INR`}
                  size={120}
                  level="M"
                />
              </div>
              <p className="text-xs text-white/60 font-light tracking-wider text-center">Scan to Pay</p>
            </div>
          </div>
        </div>

        {/* Merchant Details */}
        <div className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="merchantName" className="text-white/60 text-xs uppercase tracking-widest font-light flex items-center gap-2">
              <Store className="h-3 w-3" />
              Merchant Name
            </Label>
            <Input
              id="merchantName"
              value={merchantName}
              onChange={(e) => setMerchantName(e.target.value)}
              placeholder="Enter merchant name"
              className="bg-transparent border-b-2 border-white/20 rounded-none text-white placeholder:text-white/40 focus:border-white font-light h-12"
              data-testid="input-merchant-name"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="merchantUpi" className="text-white/60 text-xs uppercase tracking-widest font-light">Merchant UPI ID (Optional)</Label>
            <Input
              id="merchantUpi"
              value={merchantUpi}
              onChange={(e) => setMerchantUpi(e.target.value)}
              placeholder="merchant@upi"
              className="bg-transparent border-b-2 border-white/20 rounded-none text-white placeholder:text-white/40 focus:border-white font-light h-12"
              data-testid="input-merchant-upi"
            />
          </div>
        </div>

        {/* Category & Description */}
        <div className="grid md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <Label htmlFor="category" className="text-white/60 text-xs uppercase tracking-widest font-light">Category</Label>
            <Select value={category} onValueChange={setCategory}>
              <SelectTrigger className="bg-transparent border-b-2 border-white/20 rounded-none text-white font-light focus:border-white h-12" data-testid="select-category">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="bg-black border-white/20 text-white">
                <SelectItem value="shopping">Shopping</SelectItem>
                <SelectItem value="food">Food & Dining</SelectItem>
                <SelectItem value="groceries">Groceries</SelectItem>
                <SelectItem value="fuel">Fuel</SelectItem>
                <SelectItem value="bills">Bills & Utilities</SelectItem>
                <SelectItem value="entertainment">Entertainment</SelectItem>
                <SelectItem value="other">Other</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description" className="text-white/60 text-xs uppercase tracking-widest font-light">Description (Optional)</Label>
            <Input
              id="description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Add a note"
              className="bg-transparent border-b-2 border-white/20 rounded-none text-white placeholder:text-white/40 focus:border-white font-light h-12"
              data-testid="input-description"
            />
          </div>
        </div>

        {/* Security Notice */}
        <div className="border border-white/20 p-5 bg-white/5 backdrop-blur-sm">
          <div className="flex items-start gap-3">
            <div className="bg-white/10 border border-white/20 rounded-none p-2">
              <Shield className="h-5 w-5 text-white" />
            </div>
            <div className="flex-1">
              <h3 className="text-sm font-light text-white mb-1 tracking-wider">Important Note</h3>
              <p className="text-xs text-white/60 font-light leading-relaxed">
                Credit UPI can only be used for Person-to-Merchant (P2M) transactions. P2P transfers, cash withdrawals, and investments are strictly prohibited.
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4 z-40">
        <Button
          onClick={handlePay}
          disabled={processing || !merchantName || !amount || parseFloat(amount) <= 0}
          className="w-full bg-white text-black hover:bg-white/90 rounded-none h-14 text-base font-light tracking-wider disabled:opacity-50 disabled:cursor-not-allowed"
          data-testid="button-pay-now"
        >
          {processing ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-black border-t-transparent mr-2" />
              PROCESSING...
            </>
          ) : (
            <>
              <CreditCard className="mr-2 h-5 w-5" />
              {amount && parseFloat(amount) > 0 ? `PAY ₹${parseFloat(amount).toLocaleString('en-IN')}` : 'ENTER AMOUNT'}
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

client/src/components/ui/reusable-page-e.content:
import { ReactNode, HTMLAttributes } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";

// Utility function for consistent currency formatting
export function formatINR(value: string | number): string {
  const num = typeof value === "string" ? parseFloat(value) : value;
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(num);
}
import { 
  ArrowRight, 
  TrendingUp, 
  TrendingDown, 
  Calendar,
  IndianRupee,
  Plus,
  Eye,
  Edit,
  ChevronRight,
  Shield,
  CreditCard,
  Wallet,
  PieChart,
  BarChart3,
  Activity,
  Target,
  Award,
  Gift,
  Users,
  Settings
} from "lucide-react";

// Page Layout Components
interface PageContainerProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  maxWidth?: "sm" | "md" | "lg" | "xl" | "2xl" | "full";
}

export function PageContainer({ children, maxWidth = "2xl", className, ...props }: PageContainerProps) {
  const maxWidthClass = {
    sm: "max-w-sm",
    md: "max-w-md", 
    lg: "max-w-lg",
    xl: "max-w-xl",
    "2xl": "max-w-2xl",
    full: "max-w-full"
  }[maxWidth];

  return (
    <div 
      className={cn("min-h-screen bg-white dark:bg-gray-900", className)}
      {...props}
    >
      <div className={cn("mx-auto px-4 py-6", maxWidthClass)}>
        {children}
      </div>
    </div>
  );
}

interface PageHeaderProps {
  title: string;
  subtitle?: string;
  action?: ReactNode;
  children?: ReactNode;
}

export function PageHeader({ title, subtitle, action, children }: PageHeaderProps) {
  return (
    <div className="mb-8">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-gray-100 mb-2" data-testid="page-title">
            {title}
          </h1>
          {subtitle && (
            <p className="text-gray-600 dark:text-gray-300 text-lg" data-testid="page-subtitle">
              {subtitle}
            </p>
          )}
        </div>
        {action && (
          <div className="flex-shrink-0">
            {action}
          </div>
        )}
      </div>
      {children}
    </div>
  );
}

// Financial Data Components
interface FinancialSummaryCardProps {
  title: string;
  amount: string | number;
  trend?: {
    direction: "up" | "down";
    percentage: number;
    period: string;
  };
  icon: ReactNode;
  color?: "blue" | "green" | "purple" | "orange" | "red";
  onClick?: () => void;
}

export function FinancialSummaryCard({ 
  title, 
  amount, 
  trend, 
  icon, 
  color = "blue",
  onClick 
}: FinancialSummaryCardProps) {
  const colorConfig = {
    blue: {
      iconBg: "bg-blue-500 dark:bg-blue-600",
      iconText: "text-white",
      cardHover: "hover:bg-blue-50 dark:hover:bg-blue-900/20"
    },
    green: {
      iconBg: "bg-green-500 dark:bg-green-600", 
      iconText: "text-white",
      cardHover: "hover:bg-green-50 dark:hover:bg-green-900/20"
    },
    purple: {
      iconBg: "bg-purple-500 dark:bg-purple-600",
      iconText: "text-white", 
      cardHover: "hover:bg-purple-50 dark:hover:bg-purple-900/20"
    },
    orange: {
      iconBg: "bg-orange-500 dark:bg-orange-600",
      iconText: "text-white",
      cardHover: "hover:bg-orange-50 dark:hover:bg-orange-900/20"
    },
    red: {
      iconBg: "bg-red-500 dark:bg-red-600",
      iconText: "text-white",
      cardHover: "hover:bg-red-50 dark:hover:bg-red-900/20"
    }
  }[color];

  return (
    <Card 
      className={cn(
        "relative overflow-hidden transition-all duration-200 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700",
        onClick && "cursor-pointer hover:shadow-lg hover:-translate-y-1",
        onClick && colorConfig.cardHover
      )}
      onClick={onClick}
      data-testid={`financial-summary-${title.toLowerCase().replace(/\s+/g, '-')}`}
    >
      <CardContent className="p-6">
        <div className="flex items-center justify-between">
          <div className="flex-1">
            <p className="text-sm font-medium text-gray-600 dark:text-gray-300 mb-1">{title}</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">
              {typeof amount === "string" && amount.includes("₹") ? amount : formatINR(amount)}
            </p>
            {trend && (
              <div className="flex items-center gap-1 mt-2">
                {trend.direction === "up" ? (
                  <TrendingUp className="h-4 w-4 text-green-600 dark:text-green-400" />
                ) : (
                  <TrendingDown className="h-4 w-4 text-red-600 dark:text-red-400" />
                )}
                <span className={cn(
                  "text-sm font-medium",
                  trend.direction === "up" ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"
                )}>
                  {trend.percentage}% {trend.period}
                </span>
              </div>
            )}
          </div>
          <div 
            className={cn(
              "w-12 h-12 rounded-lg flex items-center justify-center",
              colorConfig.iconBg
            )}
          >
            <div className={colorConfig.iconText}>
              {icon}
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

// Status and Progress Components
interface StatusBadgeProps {
  status: string;
  variant?: "default" | "success" | "warning" | "danger" | "info";
  size?: "sm" | "md" | "lg";
}

export function StatusBadge({ status, variant = "default", size = "md" }: StatusBadgeProps) {
  const variants = {
    default: "bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-200 border-gray-200 dark:border-gray-600",
    success: "bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-200 border-green-200 dark:border-green-600",
    warning: "bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 border-yellow-200 dark:border-yellow-600", 
    danger: "bg-red-100 dark:bg-red-900/30 text-red-800 dark:text-red-200 border-red-200 dark:border-red-600",
    info: "bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-200 border-blue-200 dark:border-blue-600"
  };

  const sizes = {
    sm: "px-2 py-1 text-xs",
    md: "px-3 py-1 text-sm",
    lg: "px-4 py-2 text-base"
  };

  return (
    <Badge 
      className={cn(
        "font-medium border rounded-lg",
        variants[variant],
        sizes[size]
      )}
      data-testid={`status-badge-${status.toLowerCase()}`}
    >
      {status}
    </Badge>
  );
}

interface ProgressCardProps {
  title: string;
  current: number;
  total: number;
  description?: string;
  color?: "blue" | "green" | "purple" | "orange";
}

export function ProgressCard({ title, current, total, description, color = "blue" }: ProgressCardProps) {
  const percentage = total > 0 ? (current / total) * 100 : 0;

  const colorConfig = {
    blue: "text-blue-600 dark:text-blue-400",
    green: "text-green-600 dark:text-green-400", 
    purple: "text-purple-600 dark:text-purple-400",
    orange: "text-orange-600 dark:text-orange-400"
  }[color];

  return (
    <Card className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700">
      <CardContent className="p-6">
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="font-semibold text-gray-900 dark:text-gray-100">{title}</h3>
            <span className={cn("text-sm font-medium", colorConfig)}>
              {percentage.toFixed(1)}%
            </span>
          </div>
          <Progress value={percentage} className="h-2" />
          <div className="flex items-center justify-between text-sm text-gray-600 dark:text-gray-300">
            <span>{formatINR(current)}</span>
            <span>{formatINR(total)}</span>
          </div>
          {description && (
            <p className="text-sm text-gray-500 dark:text-gray-400">{description}</p>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

// Action Components
interface QuickActionCardProps {
  title: string;
  description: string;
  icon: ReactNode;
  onClick: () => void;
  color?: "blue" | "green" | "purple" | "orange" | "red";
  disabled?: boolean;
}

export function QuickActionCard({ 
  title, 
  description, 
  icon, 
  onClick, 
  color = "blue",
  disabled = false 
}: QuickActionCardProps) {
  const colorConfig = {
    blue: "hover:bg-blue-50 dark:hover:bg-blue-900/20 border-blue-200 dark:border-blue-600 text-blue-700 dark:text-blue-300",
    green: "hover:bg-green-50 dark:hover:bg-green-900/20 border-green-200 dark:border-green-600 text-green-700 dark:text-green-300",
    purple: "hover:bg-purple-50 dark:hover:bg-purple-900/20 border-purple-200 dark:border-purple-600 text-purple-700 dark:text-purple-300",
    orange: "hover:bg-orange-50 dark:hover:bg-orange-900/20 border-orange-200 dark:border-orange-600 text-orange-700 dark:text-orange-300",
    red: "hover:bg-red-50 dark:hover:bg-red-900/20 border-red-200 dark:border-red-600 text-red-700 dark:text-red-300"
  }[color];

  return (
    <Card 
      className={cn(
        "cursor-pointer transition-all duration-200 border-2 bg-white dark:bg-gray-800",
        "hover:shadow-md hover:-translate-y-1",
        !disabled && colorConfig,
        disabled && "opacity-50 cursor-not-allowed"
      )}
      onClick={!disabled ? onClick : undefined}
      data-testid={`quick-action-${title.toLowerCase().replace(/\s+/g, '-')}`}
    >
      <CardContent className="p-6 text-center">
        <div className="w-12 h-12 mx-auto mb-4 bg-gray-100 dark:bg-gray-700 rounded-lg flex items-center justify-center">
          {icon}
        </div>
        <h3 className="font-semibold text-gray-900 dark:text-gray-100 mb-2">{title}</h3>
        <p className="text-sm text-gray-600 dark:text-gray-300">{description}</p>
        <ChevronRight className="h-4 w-4 mx-auto mt-3 text-gray-400 dark:text-gray-500" />
      </CardContent>
    </Card>
  );
}

// Data Display Components
interface DataListItemProps {
  label: string;
  value: string | ReactNode;
  subValue?: string;
  action?: ReactNode;
  onClick?: () => void;
}

export function DataListItem({ label, value, subValue, action, onClick }: DataListItemProps) {
  return (
    <div 
      className={cn(
        "flex items-center justify-between py-4 px-6 border-b border-gray-100 dark:border-gray-700",
        onClick && "cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-800/50"
      )}
      onClick={onClick}
      data-testid={`data-list-item-${label.toLowerCase().replace(/\s+/g, '-')}`}
    >
      <div className="flex-1">
        <p className="font-medium text-gray-900 dark:text-gray-100">{label}</p>
        {subValue && (
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">{subValue}</p>
        )}
      </div>
      <div className="flex items-center gap-3">
        <div className="text-right">
          {typeof value === "string" ? (
            <p className="font-semibold text-gray-900 dark:text-gray-100">{value}</p>
          ) : value}
        </div>
        {action && action}
        {onClick && <ChevronRight className="h-4 w-4 text-gray-400 dark:text-gray-500" />}
      </div>
    </div>
  );
}

interface EmptyStateProps {
  icon: ReactNode;
  title: string;
  description: string;
  action?: {
    label: string;
    onClick: () => void;
  };
}

export function EmptyState({ icon, title, description, action }: EmptyStateProps) {
  return (
    <div className="text-center py-12" data-testid="empty-state">
      <div className="w-16 h-16 mx-auto mb-4 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center">
        {icon}
      </div>
      <h3 className="font-semibold text-gray-900 dark:text-gray-100 mb-2">{title}</h3>
      <p className="text-gray-600 dark:text-gray-300 mb-6 max-w-sm mx-auto">{description}</p>
      {action && (
        <Button onClick={action.onClick} className="gap-2" data-testid="button-empty-action">
          <Plus className="h-4 w-4" />
          {action.label}
        </Button>
      )}
    </div>
  );
}

// Section Components
interface SectionProps {
  title: string;
  description?: string;
  action?: ReactNode;
  children: ReactNode;
}

export function Section({ title, description, action, children }: SectionProps) {
  return (
    <div className="mb-8">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-xl font-bold text-gray-900 dark:text-gray-100">{title}</h2>
          {description && (
            <p className="text-gray-600 dark:text-gray-300 mt-1">{description}</p>
          )}
        </div>
        {action && action}
      </div>
      {children}
    </div>
  );
}

