                            onChange={(e) => setNewCardCvv(e.target.value.replace(/\D/g, '').slice(0, 3))}
                            placeholder="123"
                            maxLength={3}
                            className="bg-white/5 border-white/20 text-white rounded-none mt-1"
                            data-testid="input-card-cvv"
                          />
                        </div>
                      </div>
                    </div>
