import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  Plane,
  ArrowLeft,
  SlidersHorizontal,
  Clock,
  Calendar,
  Users,
  MapPin,
  TrendingUp,
  ChevronRight,
  Zap,
  Award,
  GraduationCap,
