import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-none text-sm font-medium ring-offset-background transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90 font-semibold shadow-crisp hover:shadow-sharp",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90 shadow-crisp hover:shadow-sharp",
        outline: "border border-primary bg-transparent hover:bg-primary/5 text-primary hover:text-primary/90 font-semibold shadow-crisp hover:shadow-sharp",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80 shadow-crisp hover:shadow-sharp",
        ghost: "hover:bg-accent hover:text-accent-foreground transition-all duration-200",
        link: "text-primary underline-offset-4 hover:underline hover:text-primary/80 transition-all duration-200",
        accent: "bg-accent text-accent-foreground hover:bg-accent/80 shadow-crisp hover:shadow-sharp",
        actionGreen: "bg-green-500/90 text-white hover:bg-green-500 backdrop-blur-xl border border-green-400/30 font-semibold tracking-wide transition-colors",
        actionRed: "bg-red-500/90 text-white hover:bg-red-500 backdrop-blur-xl border border-red-400/30 font-semibold tracking-wide transition-colors",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 px-3 text-xs",
        lg: "h-11 px-8 text-base",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button"
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }

