      phoneVerified: false,
      secondaryPhone: "",
      dateOfBirth: "1990-05-15",
      gender: "male",
      profilePicture: ""
    },
    address: {
      line1: "123 Tech Park Road",
      line2: "Near City Mall",
      city: "Bangalore",
      state: "Karnataka",
      pincode: "560001",
      country: "India"
    },
    professional: {
      occupation: "Software Engineer",
      company: "Tech Corp Ltd",
      annualIncome: "1200000",
      workExperience: "5"
    },
    preferences: {
      language: "english",
      currency: "INR",
      timezone: "Asia/Kolkata",
      notifications: {
        email: true,
        sms: true,
        push: true,
        promotional: false
      },
      privacy: {
        profileVisibility: "private",
        activitySharing: false,
        dataSharing: false
      }
    },
    security: {
      twoFactorAuth: true,
      biometricAuth: false,
      sessionTimeout: "30",
      lastPasswordChange: "2024-11-15"
    }
  });

  const handleInputChange = (section: keyof ProfileData, field: string, value: any) => {
    setProfileData(prev => {
      const updates: any = {
        ...prev,
        [section]: {
          ...prev[section],
          [field]: value
        }
      };

      // Reset verification status when email or phone changes
      if (section === "personalInfo") {
        if (field === "email" && value !== prev.personalInfo.email) {
          updates.personalInfo.emailVerified = false;
        }
        if (field === "phone" && value !== prev.personalInfo.phone) {
          updates.personalInfo.phoneVerified = false;
        }
      }

      return updates;
    });
  };

  const handleNestedInputChange = (section: keyof ProfileData, nestedSection: string, field: string, value: any) => {
    setProfileData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [nestedSection]: {
          ...(prev[section] as any)[nestedSection],
          [field]: value
        }
      }
    }));
  };

  const handleSave = async () => {
    setIsSaving(true);

    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1500));

    toast({
      title: "Profile Updated",
      description: "Your profile has been successfully updated"
    });

    setIsSaving(false);
    setIsEditing(false);
  };

  const handleVerifyPhone = () => {
    // In real app, this would send OTP and verify
    toast({
      title: "OTP Sent",
      description: "Verification code sent to your phone number"
    });
    // Simulate successful verification
    setTimeout(() => {
      setProfileData(prev => ({
        ...prev,
        personalInfo: {
          ...prev.personalInfo,
          phoneVerified: true
        }
      }));
      toast({
        title: "Phone Verified",
        description: "Your phone number has been verified successfully"
      });
    }, 2000);
  };

  const handleVerifyEmail = () => {
    // In real app, this would send OTP and verify
    toast({
      title: "OTP Sent",
      description: "Verification code sent to your email"
    });
    // Simulate successful verification
    setTimeout(() => {
      setProfileData(prev => ({
        ...prev,
        personalInfo: {
          ...prev.personalInfo,
          emailVerified: true
        }
      }));
      toast({
        title: "Email Verified",
        description: "Your email has been verified successfully"
      });
    }, 2000);
  };

  const handleKYCUpload = () => {
    // In real app, this would open file picker and upload
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*,.pdf';
    input.multiple = true;
    input.onchange = (e) => {
      const files = (e.target as HTMLInputElement).files;
      if (files && files.length > 0) {
        toast({
          title: "Documents Selected",
          description: `${files.length} document(s) ready for upload`
        });
        // Here you would upload the files
      }
    };
    input.click();
  };

  const handleProfilePictureUpload = () => {
    // In real app, this would open file picker, show cropper, and upload
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        // Here you would:
        // 1. Read the file as data URL
        // 2. Show a cropper dialog
        // 3. Upload the cropped image
        const reader = new FileReader();
        reader.onload = (event) => {
          const imageUrl = event.target?.result as string;
          setProfileData(prev => ({
            ...prev,
            personalInfo: {
              ...prev.personalInfo,
              profilePicture: imageUrl
