          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-white/20 scrollbar-track-white/5">
            {sections.map((section) => {
              const SectionIcon = section.icon;
              return (
                <Button
                  key={section.id}
