                <div>
                  <Label htmlFor="line2" className="text-white/80">Address Line 2 (Optional)</Label>
                  <Input
                    id="line2"
                    value={profileData.address.line2}
                    onChange={(e) => handleInputChange("address", "line2", e.target.value)}
                    disabled={!isEditing}
