const allTransactions = [
  { id: "1", accountId: "1", amount: 15000, date: "10 Sep 2024", status: "Success", time: "10:30 AM", period: "Q2 2024" },
  { id: "2", accountId: "1", amount: 15000, date: "10 Jun 2024", status: "Success", time: "03:15 PM", period: "Q1 2024" },
  { id: "3", accountId: "2", amount: 8500, date: "15 Sep 2024", status: "Success", time: "02:45 PM", period: "Q2 2024" },
  { id: "4", accountId: "1", amount: 15000, date: "10 Mar 2024", status: "Success", time: "11:45 AM", period: "Q4 2023" },
  { id: "5", accountId: "3", amount: 12000, date: "05 Sep 2024", status: "Success", time: "04:20 PM", period: "Q2 2024" },
  { id: "6", accountId: "2", amount: 8500, date: "15 Jun 2024", status: "Success", time: "01:15 PM", period: "Q1 2024" },
];

const dueTaxes = [
  { id: "d1", accountId: "1", amount: 15000, dueDate: "31 Oct 2024", period: "Q3 2024" },
];

const taxAmounts = [
  { id: "a1", amount: 5000, label: "Partial Payment" },
  { id: "a2", amount: 15000, label: "Full Tax", recommended: true },
  { id: "a3", amount: 20000, label: "Extra Payment" },
  { id: "a4", amount: 30000, label: "Advance Payment" },
];

export default function MunicipalTaxAccountDetail() {
  const [, navigate] = useLocation();
  const [, params] = useRoute("/municipal-tax/account/:id");
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useUrlTab("recent");
  const [paymentDialogOpen, setPaymentDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedAmount, setSelectedAmount] = useState<number | null>(null);
  const [customAmount, setCustomAmount] = useState("");
  const [isDueCardVisible, setIsDueCardVisible] = useState(true);

  const account = savedAccounts.find(acc => acc.id === params?.id) || savedAccounts[0];
  const accountRecentTransactions = allTransactions.filter(txn => txn.accountId === params?.id).slice(0, 3);
  const accountAllTransactions = allTransactions.filter(txn => txn.accountId === params?.id);
  const accountDueTaxes = dueTaxes.filter(txn => txn.accountId === params?.id);

  const handlePayTax = () => {
    setPaymentDialogOpen(true);
  };

  const handleAmountSelect = (amount: number) => {
    setSelectedAmount(amount);
    setCustomAmount("");
  };

  const handleProceedToPayment = () => {
    const payAmount = customAmount ? parseInt(customAmount) : selectedAmount;

    if (!payAmount) {
      toast({
        title: "Select Amount",
        description: "Please select or enter an amount to proceed",
        variant: "destructive",
      });
      return;
    }

    setPaymentDialogOpen(false);

    const paymentParams = new URLSearchParams({
      transactionType: 'municipal-tax',
      amount: payAmount.toString(),
      accountName: account.name,
      propertyId: account.propertyId,
      taxType: account.taxType,
      city: account.city,
      returnUrl: `/municipal-tax/account/${account.id}`
    });

    navigate(`/upi-payment?${paymentParams.toString()}`);
  };

  const handleDeleteAccount = () => {
    setDeleteDialogOpen(true);
  };

  const confirmDeleteAccount = () => {
    toast({
      title: "Account Deleted",
      description: `${account.name} has been removed from your saved accounts`,
    });
    setDeleteDialogOpen(false);
    navigate("/municipal-tax");
  };

  const handleTransactionClick = (transaction: any) => {
    navigate(`/municipal-tax/transaction/${transaction.id}`);
  };

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/municipal-tax")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">ACCOUNT DETAILS</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">{account.name}</p>
          </div>
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                const params = new URLSearchParams({
                  edit: 'true',
                  id: account.id,
                  name: account.name,
                  propertyNumber: account.propertyId,
                  taxType: account.taxType,
                  state: account.state,
                  district: account.district,
                  municipality: account.municipality
                });
                navigate(`/add-municipal-account?${params.toString()}`);
              }}
              className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
              data-testid="button-edit"
            >
              <Pencil className="h-5 w-5" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={handleDeleteAccount}
              className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
              data-testid="button-delete"
            >
              <Trash2 className="h-5 w-5" />
            </Button>
          </div>
        </div>
      </div>

      <div className="pt-20 pb-6 px-4 space-y-6 w-full max-w-screen-lg mx-auto">
        <div className="border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-6">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-14 h-14 border border-white/20 flex items-center justify-center">
              <Building2 className="h-7 w-7 text-white/60" />
            </div>
            <div className="flex-1">
              <h2 className="text-white font-light text-xl tracking-wide mb-1">{account.name}</h2>
              <p className="text-[10px] text-white/50 uppercase tracking-widest">{account.taxType} • {account.city}</p>
            </div>
            <Badge className="bg-white/10 text-white border-white/20 rounded-none text-[10px] uppercase tracking-widest">
              Active
            </Badge>
          </div>

          <div className="space-y-3 text-sm">
            <div className="flex justify-between">
              <span className="text-[10px] text-white/50 uppercase tracking-widest">Property ID</span>
              <span className="text-white font-light">{account.propertyId}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-white/50 uppercase tracking-widest">Current Tax</span>
              <span className="text-white font-light">{account.billAmount}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-white/50 uppercase tracking-widest">Due Date</span>
              <span className="text-white font-light">{account.dueDate}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-[10px] text-white/50 uppercase tracking-widest">Last Paid</span>
              <span className="text-white font-light">{account.lastPaid}</span>
            </div>
          </div>
        </div>

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="bg-transparent border-b border-white/10 w-full h-auto p-0 rounded-none grid grid-cols-2 gap-0">
            <TabsTrigger 
              value="recent" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent" 
              data-testid="tab-recent"
            >
              Recent
            </TabsTrigger>
            <TabsTrigger 
              value="transactions" 
              className="data-[state=active]:border-b-2 data-[state=active]:border-white data-[state=active]:text-white text-white/50 font-light text-[10px] uppercase tracking-widest rounded-none pb-3 border-b-2 border-transparent" 
              data-testid="tab-transactions"
            >
              Transactions
            </TabsTrigger>
          </TabsList>

          <TabsContent value="recent" className="mt-6 space-y-3">
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light mb-3">Recent Payments & Due Bills</p>

            {/* Due Taxes */}
            {accountDueTaxes.length > 0 && accountDueTaxes.map((tax) => (
              <div
                key={tax.id}
                className="border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-4"
                data-testid={`card-due-${tax.id}`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-light tracking-wide">₹{tax.amount.toLocaleString()}</p>
                    <p className="text-[10px] text-white/50 uppercase tracking-widest mt-1">{tax.period}</p>
                    <div className="flex items-center gap-1 mt-1">
                      <Calendar className="h-3 w-3 text-white/40" />
                      <p className="text-[10px] text-white/40 uppercase tracking-widest">Due: {tax.dueDate}</p>
                    </div>
                  </div>
                  <Button
                    onClick={(e) => {
                      e.stopPropagation();
                      const params = new URLSearchParams({
                        transactionType: 'municipal-tax',
                        amount: tax.amount.toString(),
                        accountName: account.name,
                        propertyId: account.propertyId,
                        taxType: account.taxType,
                        city: account.city,
                        returnUrl: `/municipal-tax/account/${account.id}`
                      });
                      navigate(`/upi-payment?${params.toString()}`);
                    }}
                    className="bg-white hover:bg-white/90 text-black h-9 px-6 rounded-none text-xs font-light tracking-wide"
                    data-testid={`button-pay-${tax.id}`}
                  >
                    Pay
                  </Button>
                </div>
              </div>
            ))}

            {/* Recent Transactions */}
            {accountRecentTransactions.map((transaction) => (
              <div
                key={transaction.id}
                onClick={() => handleTransactionClick(transaction)}
                className="cursor-pointer border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent hover:border-white/20 transition-all p-4"
                data-testid={`card-transaction-${transaction.id}`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-light tracking-wide">₹{transaction.amount.toLocaleString()}</p>
                    <p className="text-[10px] text-white/50 uppercase tracking-widest mt-1">{transaction.period}</p>
                    <div className="flex items-center gap-1 mt-1">
                      <Calendar className="h-3 w-3 text-white/40" />
                      <p className="text-[10px] text-white/40 uppercase tracking-widest">{transaction.date} • {transaction.time}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Badge className="bg-white/10 text-white/60 border-white/20 rounded-none text-[10px] uppercase tracking-widest">
                      {transaction.status}
                    </Badge>
                    <ChevronRight className="h-5 w-5 text-white/40" />
                  </div>
                </div>
              </div>
            ))}
          </TabsContent>

          <TabsContent value="transactions" className="mt-6 space-y-3">
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light mb-3">Transaction History</p>
            {accountAllTransactions.map((transaction) => (
              <div
                key={transaction.id}
                onClick={() => handleTransactionClick(transaction)}
                className="cursor-pointer border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent hover:border-white/20 transition-all p-4"
                data-testid={`card-transaction-history-${transaction.id}`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-white font-light tracking-wide">₹{transaction.amount.toLocaleString()}</p>
                    <p className="text-[10px] text-white/50 uppercase tracking-widest mt-1">{transaction.period}</p>
                    <div className="flex items-center gap-1 mt-1">
                      <Calendar className="h-3 w-3 text-white/40" />
                      <p className="text-[10px] text-white/40 uppercase tracking-widest">{transaction.date} • {transaction.time}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Badge className="bg-white/10 text-white/60 border-white/20 rounded-none text-[10px] uppercase tracking-widest">
                      {transaction.status}
                    </Badge>
                    <ChevronRight className="h-5 w-5 text-white/40" />
                  </div>
                </div>
              </div>
            ))}
          </TabsContent>
        </Tabs>
      </div>

      {isDueCardVisible && account.dueAmount && (
        <div className="px-4 pb-4">
          <div className="border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-4 flex items-center justify-between">
            <div className="flex items-start gap-3 flex-1">
              <AlertCircle className="h-5 w-5 text-white/60 mt-1" />
              <div>
                <h3 className="text-sm font-light text-white tracking-wide mb-2">Due Payment</h3>
                <div className="space-y-1">
                  <p className="text-lg font-medium text-white">₹{account.dueAmount.toLocaleString()}</p>
                  <p className="text-white/60 text-xs">Due Date: <span className="text-white font-light">{account.dueDate}</span></p>
                </div>
              </div>
            </div>
            <Button
              onClick={() => {
                const params = new URLSearchParams({
                  transactionType: 'municipal-tax',
                  amount: account.dueAmount.toString(),
                  accountName: account.name,
                  propertyId: account.propertyId,
                  taxType: account.taxType,
                  city: account.city,
                  returnUrl: `/municipal-tax/account/${account.id}`
                });
                navigate(`/upi-payment?${params.toString()}`);
              }}
              className="bg-red-500 hover:bg-red-600 text-white h-10 px-10 font-light tracking-wide rounded-none min-w-[100px]"
              data-testid="button-pay-due"
            >
              Pay
            </Button>
          </div>
        </div>
      )}

      <div className="fixed bottom-0 left-0 right-0 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4 z-50">
        <Button
          onClick={() => {
            if (isDueCardVisible && account.dueAmount) {
              const params = new URLSearchParams({
                transactionType: 'municipal-tax',
                amount: account.dueAmount.toString(),
                accountName: account.name,
                propertyId: account.propertyId,
                taxType: account.taxType,
                city: account.city,
                returnUrl: `/municipal-tax/account/${account.id}`
              });
              navigate(`/upi-payment?${params.toString()}`);
            } else {
              handlePayTax();
            }
          }}
          className="w-full bg-white hover:bg-white/90 text-black h-12 font-light text-base tracking-wide rounded-none flex items-center justify-center gap-2"
          data-testid="button-pay-now"
        >
          <Zap className="h-4 w-4" />
          Pay Now
        </Button>
      </div>

      {/* Payment Amount Selection Dialog */}
      <Dialog open={paymentDialogOpen} onOpenChange={setPaymentDialogOpen}>
        <DialogContent className="bg-black border-white/20 text-white max-w-2xl">
          <DialogHeader>
            <DialogTitle className="text-white font-light text-xl tracking-wide">Select Payment Amount</DialogTitle>
            <DialogDescription className="text-white/50 text-[10px] uppercase tracking-widest">
              Choose amount for {account.propertyId}
            </DialogDescription>
          </DialogHeader>

          <div className="mt-6 space-y-3">
            {taxAmounts.map((option) => (
              <div
                key={option.id}
                onClick={() => handleAmountSelect(option.amount)}
                className={`cursor-pointer border ${
                  selectedAmount === option.amount
                    ? "border-white/40 bg-white/10"
                    : "border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent hover:border-white/20"
                } transition-all p-4`}
                data-testid={`card-amount-${option.id}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <p className="text-2xl font-light text-white tracking-tight">₹{option.amount.toLocaleString()}</p>
                    <p className="text-[10px] text-white/50 uppercase tracking-widest mt-1">{option.label}</p>
                  </div>
                  {option.recommended && (
                    <Badge className="bg-white/20 text-white border-white/20 rounded-none text-[10px] uppercase tracking-widest">
                      Recommended
                    </Badge>
                  )}
                  {selectedAmount === option.amount && (
                    <CheckCircle className="h-5 w-5 text-white ml-2" />
                  )}
                </div>
              </div>
            ))}

            <div className="border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent p-4">
              <p className="text-[10px] text-white/50 uppercase tracking-widest mb-2">Custom Amount</p>
              <Input
                type="number"
                placeholder="Enter amount"
                value={customAmount}
                onChange={(e) => {
                  setCustomAmount(e.target.value);
                  setSelectedAmount(null);
                }}
                className="bg-white/5 border-white/20 text-white placeholder:text-white/40 rounded-none"
                data-testid="input-custom-amount"
              />
            </div>
          </div>

          <div className="mt-6 flex gap-3">
            <Button
              onClick={() => {
                setPaymentDialogOpen(false);
                setSelectedAmount(null);
                setCustomAmount("");
              }}
              className="flex-1 bg-white/10 hover:bg-white/15 text-white rounded-none"
              data-testid="button-cancel-payment"
            >
              Cancel
            </Button>
            <Button
              onClick={handleProceedToPayment}
              disabled={!selectedAmount && !customAmount}
              className="flex-1 bg-white hover:bg-white/90 text-black rounded-none disabled:opacity-50"
              data-testid="button-proceed-payment"
            >
              Pay ₹{customAmount ? parseInt(customAmount).toLocaleString() : selectedAmount?.toLocaleString() || 0}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Delete Account Confirmation Dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent className="bg-black border-white/20 text-white">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-white font-light text-xl tracking-wide">Delete Account</AlertDialogTitle>
            <AlertDialogDescription className="text-white/60 text-sm">
              Are you sure you want to delete "{account.name}" ({account.propertyId})? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="bg-white/10 hover:bg-white/15 text-white border-white/20 rounded-none">
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDeleteAccount}
              className="bg-white hover:bg-white/90 text-black rounded-none"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

client/src/pages/bank-transfer-payment.t.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { ArrowLeft, Building2, Lock, CheckCircle, Eye, EyeOff, Shield, TrendingUp, User } from "lucide-react";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";

interface BankAccount {
  id: string;
  bankName: string;
  accountNumber: string;
  balance: number;
  upiId: string;
}

export default function BankTransferPayment() {
  const [, navigate] = useLocation();
  const { toast } = useToast();

  const searchParams = new URLSearchParams(window.location.search);
  const recipientName = searchParams.get('recipientName') || '';
  const recipientAccount = searchParams.get('accountNumber') || '';
  const ifscCode = searchParams.get('ifscCode') || '';
  const bankName = searchParams.get('bankName') || '';
  const transferType = searchParams.get('transferType') || 'imps';

  const [amount, setAmount] = useState('');
  const [selectedAccount, setSelectedAccount] = useState<string>('1');
  const [upiPin, setUpiPin] = useState(['', '', '', '']);
  const [showPin, setShowPin] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showPinPopup, setShowPinPopup] = useState(false);

  const mockBankAccounts: BankAccount[] = [
    {
      id: '1',
      bankName: 'HDFC Bank',
      accountNumber: '****1234',
      balance: 125000,
      upiId: 'user@hdfcbank'
    },
    {
      id: '2',
      bankName: 'ICICI Bank',
      accountNumber: '****5678',
      balance: 45000,
      upiId: 'user@icici'
    },
    {
      id: '3',
      bankName: 'SBI',
      accountNumber: '****9012',
      balance: 78000,
      upiId: 'user@sbi'
    }
  ];

  const selectedAccountData = mockBankAccounts.find(acc => acc.id === selectedAccount);

  const handlePinChange = (index: number, value: string) => {
    if (value.length <= 1 && /^\d*$/.test(value)) {
      const newPin = [...upiPin];
      newPin[index] = value;
      setUpiPin(newPin);

      if (value && index < 3) {
        const nextInput = document.getElementById(`pin-${index + 1}`);
        nextInput?.focus();
      }
    }
  };

  const handlePinKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && !upiPin[index] && index > 0) {
      const prevInput = document.getElementById(`pin-${index - 1}`);
      prevInput?.focus();
    }
  };

  const handleAmountClick = () => {
    if (showPinPopup) {
      setShowPinPopup(false);
    }
  };

  const handlePayButtonClick = () => {
    const amountValue = parseFloat(amount);
    if (!amount || isNaN(amountValue) || amountValue <= 0) {
      toast({
        title: "Invalid Amount",
        description: "Please enter a valid payment amount",
        variant: "destructive"
      });
      return;
    }

    if (!showPinPopup) {
      setShowPinPopup(true);
      setTimeout(() => {
        const firstPinInput = document.getElementById('pin-0');
        firstPinInput?.focus();
      }, 300);
    } else {
      handlePayment();
    }
  };

  const handlePayment = async () => {
    const pin = upiPin.join('');
    if (pin.length !== 4) {
      toast({
        title: "Invalid PIN",
        description: "Please enter a 4-digit UPI PIN",
        variant: "destructive"
      });
      return;
    }

    const amountValue = parseFloat(amount);
    if (!amount || isNaN(amountValue) || amountValue <= 0) {
      toast({
        title: "Invalid Amount",
        description: "Please enter a valid payment amount",
        variant: "destructive"
      });
      return;
    }

    if (!selectedAccountData || amountValue > selectedAccountData.balance) {
      toast({
        title: "Insufficient Balance",
        description: "Selected account has insufficient balance",
        variant: "destructive"
      });
      return;
    }

    setIsProcessing(true);

    setTimeout(() => {
      const transactionId = `BT${Date.now()}`;
      const timestamp = new Date().toISOString();

      const successParams = new URLSearchParams({
        id: transactionId,
        type: 'bank-transfer',
        amount: amount,
        recipientName: recipientName,
        recipientAccount: recipientAccount,
        bankName: bankName,
        transferType: transferType,
        accountId: selectedAccount,
        senderBank: selectedAccountData.bankName,
        timestamp: timestamp
      });

      navigate(`/transaction-success?${successParams.toString()}`);
    }, 2000);
  };

  const formatCurrency = (value: number | string) => {
    const numValue = typeof value === 'string' ? parseFloat(value) : value;
    const strValue = typeof value === 'string' ? value : value.toString();
    const decimalPlaces = strValue.includes('.') ? strValue.split('.')[1]?.length || 0 : 0;

    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: decimalPlaces,
      maximumFractionDigits: decimalPlaces
    }).format(numValue);
  };

  const isAmountValid = amount && parseFloat(amount) > 0 && !isNaN(parseFloat(amount));

  return (
    <div className="min-h-screen bg-black text-white pb-32">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate('/bank-transfer')}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider uppercase">Bank Transfer</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Send money securely</p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      <div className="pt-20 px-4 space-y-8 w-full max-w-screen-lg mx-auto">
        {/* Recipient Info Card */}
        <div className="border border-white/20 bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl p-5">
          <div className="flex items-start gap-3 mb-4">
            <div className="w-10 h-10 border border-white/20 flex items-center justify-center flex-shrink-0">
              <User className="h-5 w-5 text-white/60" />
            </div>
            <div className="flex-1">
              <h3 className="text-lg font-light text-white mb-1 tracking-wide">{recipientName}</h3>
              <p className="text-xs text-white/60 font-light">{bankName}</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4 pt-3 border-t border-white/10">
            <div>
              <p className="text-[10px] text-white/50 uppercase tracking-widest font-light mb-1">Account</p>
              <p className="text-sm font-light text-white">{recipientAccount}</p>
            </div>
            <div>
              <p className="text-[10px] text-white/50 uppercase tracking-widest font-light mb-1">IFSC Code</p>
              <p className="text-sm font-light text-white">{ifscCode}</p>
            </div>
          </div>
          <div className="mt-3 pt-3 border-t border-white/10">
            <Badge className="bg-white/10 text-white border-white/20 rounded-none font-light text-[10px] uppercase tracking-widest">
              {transferType.toUpperCase()} Transfer
            </Badge>
          </div>
        </div>

        {/* Payment Amount Card */}
        <div className="border border-white/20 p-6 bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-xl">
          <div className="text-center">
            <Label className="text-xs text-white/60 mb-4 uppercase tracking-widest font-light block">Payment Amount</Label>
            <div className="relative max-w-md mx-auto">
              <span className="absolute left-0 top-1/2 -translate-y-1/2 text-4xl font-light text-white/60">₹</span>
              <Input
                type="text"
                inputMode="decimal"
                value={amount}
                onChange={(e) => {
                  const value = e.target.value.replace(/[^0-9.]/g, '');
                  const parts = value.split('.');
                  if (parts.length <= 2 && (!parts[1] || parts[1].length <= 2)) {
                    setAmount(value);
                  }
                }}
                onClick={handleAmountClick}
                placeholder="0"
                className="text-5xl font-light text-white tracking-tight bg-transparent border-0 border-b-2 border-white/20 rounded-none text-center pl-12 focus:border-white h-20 placeholder:text-white/20"
                data-testid="input-payment-amount"
              />
            </div>
            <div className="flex items-center justify-center gap-2 mt-4">
              <TrendingUp className="h-4 w-4 text-white/60" />
              <span className="text-xs text-white/60 font-light tracking-wider">Secure Transaction</span>
            </div>
          </div>
        </div>

        {/* Select Bank Account */}
        <div className="space-y-3">
          <Label className="text-white/60 text-xs uppercase tracking-widest font-light flex items-center gap-2">
            <Building2 className="h-3 w-3" />
            Select Bank Account
          </Label>
          <div className="space-y-3">
            {mockBankAccounts.map((account) => (
              <button
                key={account.id}
                onClick={() => setSelectedAccount(account.id)}
                className={cn(
                  "w-full p-4 border-b transition-all text-left",
                  selectedAccount === account.id
                    ? "border-white bg-white/5"
                    : "border-white/10 hover:border-white/30"
                )}
                data-testid={`account-option-${account.id}`}
              >
                <div className="flex items-center justify-between mb-2">
                  <p className={cn(
                    "font-light tracking-wider transition-opacity",
                    selectedAccount === account.id ? "opacity-100 text-white" : "opacity-60 text-white/60"
                  )}>
                    {account.bankName}
                  </p>
                  <Badge className={cn(
                    "rounded-none border font-light text-xs",
                    selectedAccount === account.id 
                      ? "bg-white/20 text-white border-white/30" 
                      : "bg-white/10 text-white/60 border-white/20"
                  )}>
                    {account.accountNumber}
                  </Badge>
                </div>
                <div className="flex items-center justify-between">
                  <p className="text-xs text-white/40 font-light">{account.upiId}</p>
                  <p className={cn(
                    "text-sm font-light",
                    selectedAccount === account.id ? "text-white" : "text-white/60"
                  )} data-testid={`balance-${account.id}`}>
                    {formatCurrency(account.balance)}
                  </p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Security Notice */}
        <div className="border border-white/20 p-5 bg-white/5 backdrop-blur-sm">
          <div className="flex items-start gap-3">
            <div className="bg-white/10 border border-white/20 rounded-none p-2">
              <Shield className="h-5 w-5 text-white" />
            </div>
            <div className="flex-1">
              <h3 className="text-sm font-light text-white mb-1 tracking-wider">Secure Payment</h3>
              <p className="text-xs text-white/60 font-light leading-relaxed">
                Your payment is secured with bank-grade encryption. UPI PIN is never stored or shared.
              </p>
            </div>
          </div>
        </div>
      </div>

      {showPinPopup && (
        <div
          className="fixed inset-0 bg-black/50 z-30 transition-opacity duration-300"
          onClick={() => setShowPinPopup(false)}
          data-testid="popup-backdrop"
        />
      )}

      <div 
        className={cn(
          "fixed left-0 right-0 bg-black/95 backdrop-blur-xl border-t border-white/10 z-40 transition-all duration-300 ease-in-out",
          showPinPopup ? "bottom-20" : "-bottom-[400px]"
        )}
        data-testid="pin-popup"
      >
        <div className="p-6 space-y-4">
          <div className="flex items-center justify-between">
            <Label className="text-white/60 text-xs uppercase tracking-widest font-light flex items-center gap-2">
              <Lock className="h-3 w-3" />
              Enter 4-Digit UPI PIN
            </Label>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowPin(!showPin)}
              className="text-white/60 hover:text-white hover:bg-white/10 rounded-none h-7 px-2 font-light"
              data-testid="button-toggle-pin"
            >
              {showPin ? (
                <EyeOff className="h-4 w-4" />
              ) : (
                <Eye className="h-4 w-4" />
              )}
            </Button>
          </div>
          <div className="flex justify-center gap-4">
            {[0, 1, 2, 3].map((index) => (
              <Input
                key={index}
                id={`pin-${index}`}
                type={showPin ? "text" : "password"}
                maxLength={1}
                value={upiPin[index]}
                onChange={(e) => handlePinChange(index, e.target.value)}
                onKeyDown={(e) => handlePinKeyDown(index, e)}
                className="w-16 h-16 text-center text-3xl font-light bg-transparent border-b-2 border-white/20 rounded-none text-white focus:border-white transition-colors"
                data-testid={`input-pin-${index}`}
              />
            ))}
          </div>
          <div className="flex items-center justify-center">
            <p className="text-xs text-white/60 font-light tracking-wider" data-testid="account-info">
              {selectedAccountData && `${selectedAccountData.bankName} • ${selectedAccountData.upiId}`}
            </p>
          </div>
        </div>
      </div>

      {/* Fixed Bottom Payment Button */}
      <div className="fixed bottom-0 left-0 right-0 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4 z-50">
        <Button
          onClick={handlePayButtonClick}
          disabled={!isAmountValid || isProcessing || (showPinPopup && upiPin.join('').length !== 4)}
          className={cn(
            "w-full rounded-none h-14 text-base font-light tracking-wider transition-all",
            isAmountValid && !isProcessing
              ? "bg-white text-black hover:bg-white/90"
              : "bg-white/20 text-white/40 cursor-not-allowed"
          )}
          data-testid="button-pay"
        >
          {isProcessing ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-black border-t-transparent mr-2" />
              Processing Payment...
            </>
          ) : showPinPopup ? (
            <>
              <CheckCircle className="h-5 w-5 mr-2" />
              {`CONFIRM PAYMENT ${formatCurrency(amount)}`}
            </>
          ) : (
            <>
              <CheckCircle className="h-5 w-5 mr-2" />
              {isAmountValid ? `PAY ${formatCurrency(amount)}` : 'ENTER AMOUNT'}
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

client/src/pages/electricity-bill-succes.content:
import { useEffect } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import {
  CheckCircle,
  ArrowLeft,
  Calendar,
  Clock,
  Zap,
  User,
  Building2,
  Receipt,
  Sparkles,
  Gift,
  TrendingUp
} from "lucide-react";

export default function ElectricityBillSuccess() {
  const [, navigate] = useLocation();

  const params = new URLSearchParams(window.location.search);
  const txnId = params.get("id");
  const amount = params.get("amount") || '';
  const accountName = params.get("accountName") || '';
  const accountNumber = params.get("accountNumber") || '';
  const consumerNumber = params.get("consumerNumber") || '';
  const provider = params.get("provider") || '';
  const timestamp = params.get("timestamp");
  const returnUrl = params.get("returnUrl") || "/electricity-bill";

  useEffect(() => {
    if (!txnId) {
      navigate("/home");
    }
  }, [txnId, navigate]);

  const formatCurrency = (amount: number | string) => {
    const num = typeof amount === 'string' ? parseFloat(amount) : amount;
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(num);
  };

  const formatDate = (date?: string | null) => {
    return new Date(date || Date.now()).toLocaleDateString('en-IN', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
    });
  };

  const formatTime = (date?: string | null) => {
    return new Date(date || Date.now()).toLocaleTimeString('en-IN', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const cashbackAmount = parseFloat(amount || '0') * 0.02;
  const pointsEarned = Math.floor(parseFloat(amount || '0') / 100);

  return (
    <div className="min-h-screen bg-black text-white pb-40">
      {/* Fixed Header - Cardless */}
      <div className="fixed top-0 left-0 right-0 z-20 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate(returnUrl)}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">PAYMENT SUCCESSFUL</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Electricity Bill</p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      <div className="pt-20 px-4 space-y-8 w-full max-w-screen-lg mx-auto">
        {/* Success Icon & Message - Cardless */}
        <div className="text-center py-8">
          <div className="flex justify-center mb-6">
            <div className="w-20 h-20 rounded-full bg-green-500/10 flex items-center justify-center">
              <CheckCircle className="h-12 w-12 text-green-400" />
            </div>
          </div>
          <h2 className="text-3xl font-light tracking-wide text-white mb-3">
            Payment Successful!
          </h2>
          <p className="text-white/50 text-sm font-light">
            Transaction completed successfully
          </p>
        </div>

        {/* Transaction Details - Hybrid */}
        <div className="space-y-6">
          <div className="space-y-4">
            {/* Transaction ID */}
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Receipt className="h-4 w-4 text-white/40" />
                <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">Transaction ID</p>
              </div>
              <div className="bg-white/5 border border-white/10 p-4">
                <p className="text-base font-light text-white tracking-wider font-mono" data-testid="text-transaction-id">
                  {txnId}
                </p>
              </div>
            </div>

            {/* Amount - Prominent */}
            <div className="bg-white/5 border border-white/10 p-6">
              <p className="text-[10px] text-white/40 uppercase tracking-widest font-light mb-2">Amount Paid</p>
              <p className="text-3xl font-light text-white" data-testid="text-amount">
                {formatCurrency(amount || 0)}
              </p>
            </div>

            {/* Account Details Grid */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <div className="flex items-center gap-2 mb-2">
                  <User className="h-4 w-4 text-white/40" />
                  <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">Account Name</p>
                </div>
                <div className="bg-white/5 border border-white/10 p-3">
                  <p className="text-sm font-light text-white" data-testid="text-account-name">
                    {accountName || 'N/A'}
                  </p>
                </div>
              </div>

              <div>
                <div className="flex items-center gap-2 mb-2">
                  <Zap className="h-4 w-4 text-white/40" />
                  <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">Consumer Number</p>
                </div>
                <div className="bg-white/5 border border-white/10 p-3">
                  <p className="text-sm font-light text-white" data-testid="text-account-number">
                    {consumerNumber || accountNumber || 'N/A'}
                  </p>
                </div>
              </div>
            </div>

            {/* Provider */}
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Building2 className="h-4 w-4 text-white/40" />
                <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">Provider</p>
              </div>
              <div className="bg-white/5 border border-white/10 p-3">
                <p className="text-sm font-light text-white" data-testid="text-provider">
                  {provider || 'N/A'}
                </p>
              </div>
            </div>

            {/* Date & Time Grid */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <div className="flex items-center gap-2 mb-2">
                  <Calendar className="h-4 w-4 text-white/40" />
                  <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">Date</p>
                </div>
                <div className="bg-white/5 border border-white/10 p-3">
                  <p className="text-sm font-light text-white" data-testid="text-date">
                    {formatDate(timestamp)}
                  </p>
                </div>
              </div>

              <div>
                <div className="flex items-center gap-2 mb-2">
                  <Clock className="h-4 w-4 text-white/40" />
                  <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">Time</p>
                </div>
                <div className="bg-white/5 border border-white/10 p-3">
                  <p className="text-sm font-light text-white" data-testid="text-time">
                    {formatTime(timestamp)}
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Rewards Section - Cardless */}
        <div className="pt-6 border-t border-white/10">
          <div className="flex items-center gap-2 mb-6">
            <Sparkles className="h-5 w-5 text-amber-400" />
            <div>
              <h3 className="text-base font-light tracking-wider text-white">Rewards Unlocked!</h3>
              <p className="text-xs text-white/40">Congratulations on your payment</p>
            </div>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between py-3 border-b border-white/10">
              <div className="flex items-center gap-3">
                <Gift className="h-4 w-4 text-green-400" />
                <div>
                  <p className="text-white font-light text-sm">Instant Cashback</p>
                  <p className="text-white/40 text-xs">Credited to wallet</p>
