      status: "active",
      riskLevel: "medium",
      vendor: "Groww"
    },
    {
      id: "2",
      name: "Axis Bluechip Fund SIP",
      category: "sip",
      amount: 120000,
      currentValue: 145800,
      units: 2890.45,
      averagePrice: 41.52,
      currentPrice: 50.43,
      investmentDate: "2021-06-10",
      lastUpdated: "2024-12-29",
