      sipDate: 15,
      riskLevel: "medium",
      vendor: "Paytm Money"
    },
    {
      id: "3",
      name: "Reliance Industries Ltd",
      category: "stock",
      amount: 75000,
      currentValue: 82500,
      units: 30,
      averagePrice: 2500,
      currentPrice: 2750,
      investmentDate: "2023-03-20",
