      units: 0.015,
      averagePrice: 3333333.33,
      currentPrice: 3866666.67,
      investmentDate: "2023-05-10",
      lastUpdated: "2024-12-29",
      returns: 8000,
      returnsPercentage: 16.0,
      status: "active",
      riskLevel: "high",
      vendor: "WazirX"
