      navigate("/");
    }
  }, [isAuthenticated, navigate]);

  // Data fetching with mock fallbacks
  const { 
    data: referralProgram, 
    isLoading: programLoading, 
    error: programError 
  } = useQuery<ReferralProgram>({
    queryKey: ['/api/referral/program'],
