import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { ArrowLeft, Save, Bell, BellOff, Zap, Target } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import type { CashParkAccount } from "@shared/schema";

export default function CashParkSettings() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [saving, setSaving] = useState(false);

  const { data: accountData, isLoading } = useQuery<{ account: CashParkAccount | null }>({
    queryKey: ["/api/cash-park/account"],
  });

  const account = accountData?.account;

  const [sweepThreshold, setSweepThreshold] = useState("10000");
  const [fdIncrement, setFdIncrement] = useState("1000");
  const [autoSweepEnabled, setAutoSweepEnabled] = useState(true);
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);

  useEffect(() => {
    if (account) {
      setSweepThreshold(account.sweepThreshold || "10000");
      setFdIncrement(account.fdIncrementAmount || "1000");
      setAutoSweepEnabled(account.autoSweepEnabled === 1);
      setNotificationsEnabled(account.notificationsEnabled === 1);
    }
  }, [account]);

  const handleSave = async () => {
    if (!account) {
      toast({
        title: "Account Not Found",
        description: "Please activate Cash Park first",
        variant: "destructive",
      });
      return;
    }

    const threshold = parseFloat(sweepThreshold);
    const increment = parseFloat(fdIncrement);

    if (isNaN(threshold) || threshold < 10000) {
      toast({
        title: "Invalid Threshold",
        description: "Minimum threshold is ₹10,000",
        variant: "destructive",
      });
      return;
    }

    if (isNaN(increment) || increment < 100) {
      toast({
        title: "Invalid Increment",
        description: "Minimum increment is ₹100",
        variant: "destructive",
      });
      return;
    }

    setSaving(true);
    try {
      const response = await apiRequest("POST", "/api/cash-park/settings", {
        sweepThreshold: threshold,
        fdIncrementAmount: increment,
        autoSweepEnabled: autoSweepEnabled ? 1 : 0,
        notificationsEnabled: notificationsEnabled ? 1 : 0,
      });

      const result = await response.json();

      if (!result.success) {
        toast({
          title: "Update Failed",
          description: result.message || "Failed to update settings",
          variant: "destructive",
        });
        return;
      }

      toast({
        title: "Success",
        description: "Settings updated successfully!",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/cash-park/account"] });
    } catch (error: any) {
      toast({
        title: "Update Failed",
        description: error.message || "Failed to update settings",
        variant: "destructive",
      });
    } finally {
      setSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-white text-xl font-light tracking-wider">Loading...</div>
      </div>
    );
  }

  if (!account) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-center space-y-4">
          <p className="text-xl font-light tracking-wider">Please activate Cash Park first</p>
          <Button
            onClick={() => navigate("/cash-park")}
            className="bg-white text-black hover:bg-white/90 rounded-none"
            data-testid="button-activate-first"
          >
            Go to Cash Park
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white pb-32">
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/cash-park")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">CASH PARK SETTINGS</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Configuration</p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      <div className="pt-20 px-4 space-y-8 max-w-3xl mx-auto">
        <div className="border border-white/20 bg-white/5 backdrop-blur-xl p-8 space-y-8">
          <div className="space-y-6">
            <div className="flex items-center gap-3 pb-4 border-b border-white/10">
              <Target className="h-6 w-6 text-white" />
              <h2 className="text-xl font-light tracking-wider uppercase">SWEEP CONFIGURATION</h2>
            </div>

            <div className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="threshold" className="text-white/60 text-xs uppercase tracking-widest font-light">
                  Sweep Threshold (₹)
                </Label>
                <Input
                  id="threshold"
                  type="number"
                  min="10000"
                  value={sweepThreshold}
                  onChange={(e) => setSweepThreshold(e.target.value)}
                  className="bg-transparent border-b-2 border-white/20 rounded-none text-white placeholder:text-white/40 focus:border-white text-xl font-light"
                  data-testid="input-threshold"
                />
                <p className="text-xs text-white/50 font-light">
                  Funds above this amount will be automatically swept to FDs. Minimum ₹10,000.
                </p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="increment" className="text-white/60 text-xs uppercase tracking-widest font-light">
                  FD Increment Amount (₹)
                </Label>
                <Input
                  id="increment"
                  type="number"
                  min="100"
                  value={fdIncrement}
                  onChange={(e) => setFdIncrement(e.target.value)}
                  className="bg-transparent border-b-2 border-white/20 rounded-none text-white placeholder:text-white/40 focus:border-white text-xl font-light"
                  data-testid="input-increment"
                />
                <p className="text-xs text-white/50 font-light">
                  Each FD unit will be created in this amount. Smaller increments provide better liquidity management.
                </p>
              </div>
            </div>
          </div>

          <div className="space-y-6 pt-4 border-t border-white/10">
            <div className="flex items-center gap-3 pb-4 border-b border-white/10">
              <Zap className="h-6 w-6 text-white" />
              <h2 className="text-xl font-light tracking-wider uppercase">AUTO-SWEEP OPTIONS</h2>
            </div>

            <div className="space-y-6">
              <div className="flex items-center justify-between p-4 border border-white/10 bg-white/5">
                <div className="flex-1">
                  <div className="font-light tracking-wider uppercase text-sm">Auto-Sweep Enabled</div>
                  <p className="text-xs text-white/60 font-light mt-1">
                    Automatically move funds to and from FDs based on threshold
                  </p>
                </div>
                <Switch
                  checked={autoSweepEnabled}
                  onCheckedChange={setAutoSweepEnabled}
                  className="data-[state=checked]:bg-white"
                  data-testid="switch-auto-sweep"
                />
              </div>

              <div className="flex items-center justify-between p-4 border border-white/10 bg-white/5">
                <div className="flex-1 flex items-center gap-3">
                  {notificationsEnabled ? (
                    <Bell className="h-5 w-5 text-white/60" />
                  ) : (
                    <BellOff className="h-5 w-5 text-white/60" />
                  )}
                  <div>
                    <div className="font-light tracking-wider uppercase text-sm">Notifications</div>
                    <p className="text-xs text-white/60 font-light mt-1">
                      Get notified about sweep transactions and FD creation
                    </p>
                  </div>
                </div>
                <Switch
                  checked={notificationsEnabled}
                  onCheckedChange={setNotificationsEnabled}
                  className="data-[state=checked]:bg-white"
                  data-testid="switch-notifications"
                />
              </div>
            </div>
          </div>

          <div className="pt-6">
            <Button
              onClick={handleSave}
              disabled={saving}
              className="w-full bg-white text-black hover:bg-white/90 rounded-none h-12 font-light tracking-wider flex items-center justify-center gap-2"
              data-testid="button-save-settings"
            >
              <Save className="h-5 w-5" />
              {saving ? "SAVING..." : "SAVE SETTINGS"}
            </Button>
          </div>
        </div>

        <div className="border border-white/30 bg-white/5 p-6 space-y-3">
          <h3 className="font-light uppercase tracking-wider text-sm">CURRENT STATUS</h3>
          <div className="grid md:grid-cols-2 gap-4 text-sm">
            <div>
              <span className="text-white/60">Total Parked: </span>
              <span className="text-white font-light" data-testid="text-total-parked">
                ₹{parseFloat(account.totalParkedAmount || "0").toLocaleString('en-IN')}
              </span>
            </div>
            <div>
              <span className="text-white/60">Interest Earned: </span>
              <span className="text-white font-light" data-testid="text-total-interest">
                ₹{parseFloat(account.totalInterestEarned || "0").toLocaleString('en-IN')}
              </span>
            </div>
            <div>
              <span className="text-white/60">Active FDs: </span>
              <span className="text-white font-light" data-testid="text-active-fds">
                {account.activeFdCount || 0}
              </span>
            </div>
            <div>
              <span className="text-white/60">Interest Rate: </span>
              <span className="text-white font-light" data-testid="text-current-rate">
                {account.currentInterestRate}% p.a.
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

client/src/pages/movie-fnb.tsx.content:
import { useState, useEffect, useRef } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { ArrowLeft, Plus, Minus, ShoppingCart } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/use-auth";
import { cn } from "@/lib/utils";
import type { FoodMenuItem } from "@shared/schema";

interface FoodItemWithQuantity extends FoodMenuItem {
  quantity: number;
}

export default function MovieFnB() {
  const [location, navigate] = useLocation();
  const { toast } = useToast();
  const { isAuthenticated, isLoading: authLoading } = useAuth();
  const [selectedItems, setSelectedItems] = useState<Record<string, number>>({});
  const redirectedRef = useRef(false);

  const bookingData = JSON.parse(sessionStorage.getItem("movieBooking") || "{}");
  const theaterId = bookingData.theaterId;
  const hasMovieId = !!bookingData.movieId;
  const hasShowtimeId = !!bookingData.showtimeId;
  const hasSelectedSeats = Array.isArray(bookingData.selectedSeats) && bookingData.selectedSeats.length > 0;

  const { data: foodMenuData, isLoading } = useQuery<{ success: boolean; foodMenu: FoodMenuItem[] }>({
    queryKey: ["/api/food-menu", theaterId],
    enabled: isAuthenticated && !!theaterId,
  });

  useEffect(() => {
    if (redirectedRef.current) return;

    if (!authLoading && !isAuthenticated) {
      redirectedRef.current = true;
      toast({
        title: "Login Required",
        description: "Please log in to continue booking.",
        variant: "destructive",
      });
      navigate(`/login?redirect=${encodeURIComponent(location)}`, { replace: true });
      return;
    }

    if (isAuthenticated && (!hasMovieId || !hasShowtimeId || !hasSelectedSeats)) {
      redirectedRef.current = true;
      navigate("/movies");
    }
  }, [isAuthenticated, authLoading, hasMovieId, hasShowtimeId, hasSelectedSeats, navigate, toast, location]);

  if (authLoading) {
    return (
      <div className="min-h-screen bg-black text-white p-4">
        <div className="max-w-4xl mx-auto">
          <Skeleton className="h-8 w-64 mb-4 rounded-none" />
          <Skeleton className="h-96 w-full rounded-none" />
        </div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return null;
  }

  const foodMenu = foodMenuData?.foodMenu || [];

  const categorizedMenu = foodMenu.reduce((acc, item) => {
    if (!acc[item.category]) {
      acc[item.category] = [];
    }
    acc[item.category].push(item);
    return acc;
  }, {} as Record<string, FoodMenuItem[]>);

  const updateQuantity = (itemId: string, delta: number) => {
    setSelectedItems(prev => {
      const current = prev[itemId] || 0;
      const newValue = Math.max(0, current + delta);
      if (newValue === 0) {
        const { [itemId]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [itemId]: newValue };
    });
  };

  const selectedItemsList = foodMenu
    .filter(item => selectedItems[item.id])
    .map(item => ({ ...item, quantity: selectedItems[item.id] }));

  const foodTotal = selectedItemsList.reduce((sum, item) => 
    sum + (parseFloat(item.price) * item.quantity), 0
  );

  const handleSkip = () => {
    const updatedBooking = {
      ...bookingData,
      foodItems: [],
      foodAmount: 0,
    };
    sessionStorage.setItem("movieBooking", JSON.stringify(updatedBooking));
    navigate("/movies/checkout");
  };

  const handleProceedToCheckout = () => {
    if (selectedItemsList.length === 0) {
      handleSkip();
      return;
    }

    const updatedBooking = {
      ...bookingData,
      foodItems: selectedItemsList.map(item => ({
        id: item.id,
        name: item.name,
        quantity: item.quantity,
        price: item.price,
      })),
      foodAmount: foodTotal,
    };
    sessionStorage.setItem("movieBooking", JSON.stringify(updatedBooking));
    navigate("/movies/checkout");
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-black text-white">
        <div className="container mx-auto px-4 py-6">
          <Skeleton className="h-8 w-32 mb-6 rounded-none" />
          <div className="space-y-4">
            {[...Array(4)].map((_, i) => (
              <Skeleton key={i} className="h-24 w-full rounded-none" />
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white pb-32">
      <div className="sticky top-0 z-10 bg-black/95 backdrop-blur supports-[backdrop-filter]:bg-black/60 border-b">
        <div className="container mx-auto px-4 py-4">
          <div className="flex items-center gap-4">
            <Button 
              variant="ghost" 
              size="icon"
              className="rounded-none"
              onClick={() => navigate(`/movies/${bookingData.movieId}/seats/${bookingData.showtimeId}`)}
              data-testid="button-back"
            >
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <h1 className="text-2xl font-bold">Food & Beverages</h1>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 py-6">
        {foodMenu.length === 0 ? (
          <div className="text-center py-12">
            <ShoppingCart className="h-12 w-12 mx-auto text-white/60 mb-3" />
            <p className="text-white/60 mb-4">No food items available for this theater</p>
            <Button className="rounded-none" onClick={handleSkip} data-testid="button-skip-no-items">
              Skip to Checkout
            </Button>
          </div>
        ) : (
          <div className="space-y-6">
            {Object.entries(categorizedMenu).map(([category, items]) => (
              <div key={category}>
                <h2 className="text-xl font-bold mb-4" data-testid={`text-category-${category.toLowerCase()}`}>
                  {category}
                </h2>
                <div className="grid gap-4">
                  {items.map(item => {
                    const quantity = selectedItems[item.id] || 0;
                    return (
                      <Card key={item.id} className="rounded-none" data-testid={`card-food-item-${item.id}`}>
                        <CardContent className="p-4">
                          <div className="flex gap-4">
                            {item.imageUrl && (
                              <div className="w-20 h-20 flex-shrink-0 rounded-none overflow-hidden bg-white/5">
                                <img 
                                  src={item.imageUrl} 
                                  alt={item.name} 
                                  className="w-full h-full object-cover"
                                  data-testid={`img-food-${item.id}`}
                                />
                              </div>
                            )}
                            <div className="flex-1 min-w-0">
                              <div className="flex items-start justify-between gap-2">
                                <div>
                                  <h3 className="font-semibold" data-testid={`text-food-name-${item.id}`}>
                                    {item.name}
                                    {item.isCombo === 1 && (
                                      <Badge variant="secondary" className="ml-2 rounded-none">Combo</Badge>
                                    )}
                                  </h3>
                                  {item.description && (
                                    <p className="text-sm text-white/60 line-clamp-2 mt-1" data-testid={`text-food-desc-${item.id}`}>
                                      {item.description}
                                    </p>
                                  )}
                                  {item.comboItems && item.comboItems.length > 0 && (
                                    <p className="text-xs text-white/60 mt-1">
                                      {item.comboItems.join(" • ")}
                                    </p>
                                  )}
                                  <p className="text-lg font-bold mt-2" data-testid={`text-food-price-${item.id}`}>
                                    ₹{item.price}
                                  </p>
                                </div>
                              </div>
                            </div>
                            <div className="flex-shrink-0">
                              {quantity === 0 ? (
                                <Button 
                                  variant="outline"
                                  size="sm"
                                  className="rounded-none"
                                  onClick={() => updateQuantity(item.id, 1)}
                                  data-testid={`button-add-${item.id}`}
                                >
                                  Add
                                </Button>
                              ) : (
                                <div className="flex items-center gap-2 border rounded-none">
                                  <Button 
                                    variant="ghost" 
                                    size="icon"
                                    className="h-8 w-8 rounded-none"
                                    onClick={() => updateQuantity(item.id, -1)}
                                    data-testid={`button-decrease-${item.id}`}
                                  >
                                    <Minus className="h-4 w-4" />
                                  </Button>
                                  <span className="font-medium min-w-[20px] text-center" data-testid={`text-quantity-${item.id}`}>
                                    {quantity}
                                  </span>
                                  <Button 
                                    variant="ghost" 
                                    size="icon"
                                    className="h-8 w-8 rounded-none"
                                    onClick={() => updateQuantity(item.id, 1)}
                                    data-testid={`button-increase-${item.id}`}
                                  >
                                    <Plus className="h-4 w-4" />
                                  </Button>
                                </div>
                              )}
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 bg-black border-t p-4 z-20">
        <div className="container mx-auto">
          <div className="flex items-center justify-between gap-4">
            <div>
              {selectedItemsList.length > 0 ? (
                <>
                  <p className="text-sm text-white/60" data-testid="text-items-count">
                    {selectedItemsList.length} item{selectedItemsList.length !== 1 ? "s" : ""}
                  </p>
                  <p className="text-lg font-bold" data-testid="text-food-total">
                    ₹{foodTotal.toFixed(2)}
                  </p>
                </>
              ) : (
                <p className="text-sm text-white/60">No items selected</p>
              )}
            </div>
            <div className="flex gap-2">
              <Button 
                variant="outline"
                className="rounded-none"
                onClick={handleSkip}
                data-testid="button-skip"
              >
                Skip
              </Button>
              <Button 
                className="rounded-none"
                onClick={handleProceedToCheckout}
                data-testid="button-proceed-to-checkout"
              >
                Proceed to Checkout
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

