  { id: "2", accountId: "1", amount: 650, date: "15 Aug 2024", status: "Success", time: "03:15 PM", billMonth: "August 2024" },
  { id: "3", accountId: "2", amount: 450, date: "15 Sep 2024", status: "Success", time: "02:45 PM", billMonth: "September 2024" },
  { id: "4", accountId: "1", amount: 720, date: "18 Jul 2024", status: "Success", time: "11:45 AM", billMonth: "July 2024" },
  { id: "5", accountId: "3", amount: 550, date: "12 Sep 2024", status: "Success", time: "04:20 PM", billMonth: "September 2024" },
  { id: "6", accountId: "2", amount: 480, date: "15 Aug 2024", status: "Success", time: "01:15 PM", billMonth: "August 2024" },
];

