import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { ArrowLeft } from "lucide-react";

interface PageHeaderProps {
  title: string;
  subtitle?: string;
  showBackButton?: boolean;
  backPath?: string;
  className?: string;
  children?: React.ReactNode;
}

export function PageHeader({ 
  title, 
  subtitle, 
  showBackButton = true, 
  backPath,
  className = "",
  children 
}: PageHeaderProps) {
  const [, navigate] = useLocation();

  const handleBack = () => {
    if (backPath) {
      navigate(backPath);
    } else if (window.history.length > 1) {
      window.history.back();
    } else {
      navigate("/home");
    }
  };

  return (
    <div className={`fixed top-0 left-0 right-0 z-50 bg-background border-b border-border backdrop-blur-sm ${className}`}>
      <div className="px-4 py-6">
        <div className="flex items-center gap-4">
          {showBackButton && (
            <Button
              onClick={handleBack}
              variant="ghost"
              size="sm"
              className="p-2 rounded-none hover:bg-muted"
              data-testid="button-back"
            >
              <ArrowLeft className="h-6 w-6" />
            </Button>
          )}

          <div className="flex-1">
            <h1 className="text-2xl font-bold text-foreground" data-testid="text-page-title">
              {title}
            </h1>
            {subtitle && (
              <p className="text-sm text-muted-foreground mt-1" data-testid="text-page-subtitle">
                {subtitle}
              </p>
            )}
          </div>

          {children && (
            <div className="flex items-center gap-2">
              {children}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

client/src/pages/flight-payment.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { useNavigationHistory } from "@/hooks/use-navigation-history";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import {
  ArrowLeft,
  CreditCard,
  Smartphone,
  Wallet,
  Building2,
  CheckCircle,
  Shield,
  Lock
} from "lucide-react";

export default function FlightPayment() {
  const { goBack } = useNavigationHistory();
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [paymentMethod, setPaymentMethod] = useState("upi");
  const [isProcessing, setIsProcessing] = useState(false);

  const [upiId, setUpiId] = useState("");
  const [cardNumber, setCardNumber] = useState("");
  const [cardName, setCardName] = useState("");
  const [cardExpiry, setCardExpiry] = useState("");
  const [cardCvv, setCardCvv] = useState("");
  const [cardType, setCardType] = useState<"credit" | "debit">("credit");
  const [selectedBank, setSelectedBank] = useState("");
  const [selectedWallet, setSelectedWallet] = useState("");

  const params = new URLSearchParams(window.location.search);
  const amount = parseFloat(params.get("amount") || "0");
  const type = params.get("type") || "flight";

  const formatCurrency = (amt: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0
    }).format(amt);
  };

  const handlePayment = () => {
    if (paymentMethod === "upi" && !upiId) {
      toast({
        title: "UPI ID Required",
        description: "Please enter your UPI ID",
        variant: "destructive"
      });
      return;
    }

    if (paymentMethod === "card") {
      if (!cardNumber || !cardName || !cardExpiry || !cardCvv) {
        toast({
          title: "Card Details Required",
          description: "Please fill in all card details",
          variant: "destructive"
        });
        return;
      }
    }

    if (paymentMethod === "netbanking" && !selectedBank) {
      toast({
        title: "Bank Selection Required",
        description: "Please select your bank",
        variant: "destructive"
      });
      return;
    }

    if (paymentMethod === "wallet" && !selectedWallet) {
      toast({
        title: "Wallet Selection Required",
        description: "Please select a wallet",
        variant: "destructive"
      });
      return;
    }

    if (paymentMethod === "upi") {
      navigate(`/upi-payment?amount=${amount}`);
      return;
    }

    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      toast({
        title: "Payment Successful!",
        description: "Your booking has been confirmed.",
      });
      navigate(type === "bus" ? "/booking/bus/success" : "/flights/booking-success");
    }, 2000);
  };

  const BANKS = [
    { id: "sbi", name: "State Bank of India", accountNumber: "****1234" },
    { id: "hdfc", name: "HDFC Bank", accountNumber: "****5678" },
    { id: "icici", name: "ICICI Bank", accountNumber: "****9012" },
    { id: "axis", name: "Axis Bank", accountNumber: "****3456" },
    { id: "pnb", name: "Punjab National Bank", accountNumber: "****7890" },
    { id: "bob", name: "Bank of Baroda", accountNumber: "****2345" },
    { id: "canara", name: "Canara Bank", accountNumber: "****6789" },
    { id: "union", name: "Union Bank of India", accountNumber: "****0123" },
    { id: "kotak", name: "Kotak Mahindra Bank", accountNumber: "****4567" },
    { id: "idfc", name: "IDFC First Bank", accountNumber: "****8901" }
  ];

  const WALLETS = [
    { id: "paytm", name: "Paytm", balance: "₹15,000" },
    { id: "phonepe", name: "PhonePe", balance: "₹8,500" },
    { id: "googlepay", name: "Google Pay", balance: "₹12,000" },
    { id: "amazonpay", name: "Amazon Pay", balance: "₹6,200" },
    { id: "mobikwik", name: "Mobikwik", balance: "₹4,800" }
  ];

  const PAYMENT_METHODS = [
    { id: "upi", name: "UPI", icon: Smartphone },
    { id: "card", name: "Card", icon: CreditCard },
    { id: "netbanking", name: "Net Banking", icon: Building2 },
    { id: "wallet", name: "Wallet", icon: Wallet }
  ];

  return (
    <div className="min-h-screen bg-black text-white pb-32">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => goBack()}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">SECURE PAYMENT</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Complete your booking</p>
          </div>
          <div className="w-10"></div>
        </div>
      </div>

      <div className="pt-20 px-4 space-y-8 w-full max-w-screen-lg mx-auto">
        {/* Security Notice - Cardless */}
        <div className="py-6 border-b border-white/10">
          <div className="flex items-start gap-3">
            <Shield className="h-5 w-5 text-white/60 mt-0.5" />
            <div className="flex-1">
              <h3 className="text-sm font-light text-white mb-1 tracking-wider">Secure Payment</h3>
              <p className="text-xs text-white/40 font-light leading-relaxed">
                Your payment is secured with 256-bit SSL encrypted transaction
              </p>
            </div>
          </div>
        </div>

        {/* Payment Method Tabs */}
        <div className="space-y-4">
          <Label className="text-white/60 text-xs uppercase tracking-widest font-light">
            Select Payment Method
          </Label>
          <div className="grid grid-cols-4 gap-2">
            {PAYMENT_METHODS.map((method) => {
              const Icon = method.icon;
              return (
                <button
                  key={method.id}
                  onClick={() => setPaymentMethod(method.id)}
                  className={cn(
                    "p-4 border-b-2 transition-all flex flex-col items-center gap-2",
                    paymentMethod === method.id
                      ? "border-white bg-white/5"
                      : "border-white/20 hover:border-white/40"
                  )}
                  data-testid={`button-payment-${method.id}`}
                >
                  <Icon className={cn(
                    "h-6 w-6 transition-opacity",
                    paymentMethod === method.id ? "opacity-100 text-white" : "opacity-40 text-white/60"
                  )} />
                  <span className={cn(
                    "text-xs font-light tracking-wider transition-opacity",
                    paymentMethod === method.id ? "opacity-100 text-white" : "opacity-40 text-white/60"
                  )}>
                    {method.name}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* UPI Payment - Cardless */}
        {paymentMethod === "upi" && (
          <div className="space-y-4 py-4 border-b border-white/10">
            <Label className="text-white/60 text-xs uppercase tracking-widest font-light block">
              Enter UPI ID
            </Label>
            <Input
              value={upiId}
              onChange={(e) => setUpiId(e.target.value)}
              placeholder="yourname@upi"
              className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-4"
              data-testid="input-upi-id"
            />
            <p className="text-xs text-white/40 font-light">e.g., 9876543210@paytm, yourname@okaxis</p>
          </div>
        )}

        {/* Card Payment - Cardless */}
        {paymentMethod === "card" && (
          <div className="space-y-6 py-4 border-b border-white/10">
            <div className="flex gap-2">
              <button
                onClick={() => setCardType("credit")}
                className={cn(
                  "flex-1 p-3 border-b-2 transition-all text-center",
                  cardType === "credit"
                    ? "border-white bg-white/5 text-white"
                    : "border-white/20 text-white/60 hover:border-white/40"
                )}
                data-testid="button-credit-card"
              >
                <span className="text-sm font-light tracking-wider">CREDIT CARD</span>
              </button>
              <button
                onClick={() => setCardType("debit")}
                className={cn(
                  "flex-1 p-3 border-b-2 transition-all text-center",
                  cardType === "debit"
                    ? "border-white bg-white/5 text-white"
                    : "border-white/20 text-white/60 hover:border-white/40"
                )}
                data-testid="button-debit-card"
              >
                <span className="text-sm font-light tracking-wider">DEBIT CARD</span>
              </button>
            </div>

            <div className="space-y-2">
              <Label className="text-white/60 text-xs uppercase tracking-widest font-light">Card Number</Label>
              <Input
                value={cardNumber}
                onChange={(e) => setCardNumber(e.target.value.replace(/\D/g, '').substring(0, 16))}
                placeholder="1234 5678 9012 3456"
                maxLength={16}
                className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-4"
                data-testid="input-card-number"
              />
            </div>

            <div className="space-y-2">
              <Label className="text-white/60 text-xs uppercase tracking-widest font-light">Cardholder Name</Label>
              <Input
                value={cardName}
                onChange={(e) => setCardName(e.target.value)}
                placeholder="Name on card"
                className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-4"
                data-testid="input-card-name"
              />
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label className="text-white/60 text-xs uppercase tracking-widest font-light">Expiry Date</Label>
                <Input
                  value={cardExpiry}
                  onChange={(e) => setCardExpiry(e.target.value)}
                  placeholder="MM/YY"
                  maxLength={5}
                  className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-4"
                  data-testid="input-card-expiry"
                />
              </div>
              <div className="space-y-2">
                <Label className="text-white/60 text-xs uppercase tracking-widest font-light">CVV</Label>
                <Input
                  value={cardCvv}
                  onChange={(e) => setCardCvv(e.target.value.replace(/\D/g, '').substring(0, 3))}
                  placeholder="123"
                  type="password"
                  maxLength={3}
                  className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 font-light focus:border-white px-4"
                  data-testid="input-card-cvv"
                />
              </div>
            </div>
          </div>
        )}

        {/* Net Banking - Cardless */}
        {paymentMethod === "netbanking" && (
          <div className="space-y-4 py-4">
            <Label className="text-white/60 text-xs uppercase tracking-widest font-light flex items-center gap-2">
              <Building2 className="h-3 w-3" />
              Select Your Bank
            </Label>
            <div className="space-y-0">
              {BANKS.map((bank) => (
                <button
                  key={bank.id}
                  onClick={() => setSelectedBank(bank.id)}
                  className={cn(
                    "w-full p-4 border-b transition-all text-left",
                    selectedBank === bank.id
                      ? "border-white bg-white/5"
                      : "border-white/10 hover:border-white/30"
                  )}
                  data-testid={`button-bank-${bank.id}`}
                >
                  <div className="flex items-center justify-between">
                    <p className={cn(
                      "font-light tracking-wider transition-opacity",
                      selectedBank === bank.id ? "opacity-100 text-white" : "opacity-60 text-white/60"
                    )}>
                      {bank.name}
                    </p>
                    <span className={cn(
                      "text-xs font-light",
                      selectedBank === bank.id ? "text-white/60" : "text-white/40"
                    )}>
                      {bank.accountNumber}
                    </span>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Digital Wallet - Cardless */}
        {paymentMethod === "wallet" && (
          <div className="space-y-4 py-4">
            <Label className="text-white/60 text-xs uppercase tracking-widest font-light flex items-center gap-2">
              <Wallet className="h-3 w-3" />
              Select Wallet
            </Label>
            <div className="space-y-0">
              {WALLETS.map((wallet) => (
                <button
                  key={wallet.id}
                  onClick={() => setSelectedWallet(wallet.id)}
                  className={cn(
                    "w-full p-4 border-b transition-all text-left",
                    selectedWallet === wallet.id
                      ? "border-white bg-white/5"
                      : "border-white/10 hover:border-white/30"
                  )}
                  data-testid={`button-wallet-${wallet.id}`}
                >
                  <div className="flex items-center justify-between">
                    <p className={cn(
                      "font-light tracking-wider transition-opacity",
                      selectedWallet === wallet.id ? "opacity-100 text-white" : "opacity-60 text-white/60"
                    )}>
                      {wallet.name}
                    </p>
                    <p className={cn(
                      "text-sm font-light",
                      selectedWallet === wallet.id ? "text-white" : "text-white/60"
                    )}>
                      {wallet.balance}
                    </p>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Amount Display - Cardless */}
        <div className="py-6 border-b border-white/10">
          <div className="flex justify-between items-center">
            <span className="text-white/60 text-xs uppercase tracking-widest font-light">Total Amount</span>
            <span className="text-3xl font-light text-white" data-testid="text-total-amount">
              {formatCurrency(amount)}
            </span>
          </div>
        </div>
      </div>

      {/* Fixed Bottom Payment Button */}
      <div className="fixed bottom-0 left-0 right-0 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4 z-40">
        <Button
          onClick={handlePayment}
          disabled={isProcessing}
          className="w-full bg-white text-black hover:bg-white/90 rounded-none h-14 text-base font-light tracking-wider disabled:opacity-50 disabled:cursor-not-allowed"
          data-testid="button-pay-now"
        >
          {isProcessing ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-black border-t-transparent mr-2" />
              Processing Payment...
            </>
          ) : (
            <>
              <CheckCircle className="h-5 w-5 mr-2" />
              PAY {formatCurrency(amount)}
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

client/src/pages/movies-listing.tsx.content:
import { useState, useEffect, useMemo } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";
import { Clock, Star, Search, ArrowLeft, MapPin, Film, TrendingUp, Popcorn } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import type { Movie } from "@shared/schema";

export default function MoviesListing() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [searchTerm, setSearchTerm] = useState("");
  const [genreFilter, setGenreFilter] = useState<string>("all");
  const [languageFilter, setLanguageFilter] = useState<string>("all");
  const [cityFilter, setCityFilter] = useState<string>("all");

  const { data: moviesData, isLoading, error } = useQuery<{ success: boolean; movies: Movie[] }>({
    queryKey: ["/api/movies"],
  });

  useEffect(() => {
    if (error) {
      toast({
        title: "Error",
        description: "Failed to load movies. Please try again.",
        variant: "destructive",
      });
    }
  }, [error, toast]);

  const movies = moviesData?.movies || [];

  // Filter movies by search, genre, and language
  // Note: City is stored as user preference but not used for filtering since movies
  // aren't city-specific - cities are associated with theaters/showtimes instead
  const filteredMovies = useMemo(() => {
    return movies.filter(movie => {
      const matchesSearch = movie.title.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesGenre = genreFilter === "all" || movie.genre?.includes(genreFilter);
      const matchesLanguage = languageFilter === "all" || movie.language === languageFilter;
      return matchesSearch && matchesGenre && matchesLanguage;
    });
  }, [movies, searchTerm, genreFilter, languageFilter]);

  const genres = Array.from(new Set(movies.flatMap(m => m.genre || [])));
  const languages = Array.from(new Set(movies.map(m => m.language)));
  const cities = ["Mumbai", "Delhi", "Bangalore", "Hyderabad", "Chennai", "Kolkata", "Pune"];

  // Featured movies for banner (first 3)
  const featuredMovies = filteredMovies.slice(0, 3);

  const pagination = usePagination({
    data: filteredMovies,
    itemsPerPage: 20,
  });

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      <div className="sticky top-0 z-10 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="container mx-auto px-4 py-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <Button 
                variant="ghost" 
                size="icon" 
                onClick={() => navigate("/pro-tools")}
                className="rounded-none"
                data-testid="button-back"
              >
                <ArrowLeft className="h-5 w-5" />
              </Button>
              <div>
                <h1 className="text-2xl font-bold flex items-center gap-2">
                  <Film className="h-6 w-6" />
                  Book Movies
                </h1>
                <p className="text-sm text-white/60">Book tickets for latest movies</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <MapPin className="h-4 w-4 text-white/60" />
              <Select value={cityFilter} onValueChange={setCityFilter}>
                <SelectTrigger className="w-36 rounded-none" data-testid="select-city-filter">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="rounded-none">
                  <SelectItem value="all" data-testid="select-option-city-all">All Cities</SelectItem>
                  {cities.map(city => (
                    <SelectItem key={city} value={city} data-testid={`select-option-city-${city.toLowerCase()}`}>
                      {city}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-3">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/60" />
              <Input
                type="text"
                placeholder="Search for movies..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10 rounded-none"
                data-testid="input-search-movies"
              />
            </div>

            <Select value={languageFilter} onValueChange={setLanguageFilter}>
              <SelectTrigger className="w-full sm:w-36 rounded-none" data-testid="select-language-filter">
                <SelectValue placeholder="Language" />
              </SelectTrigger>
              <SelectContent className="rounded-none">
                <SelectItem value="all" data-testid="select-option-language-all">All Languages</SelectItem>
                {languages.map(language => (
                  <SelectItem key={language} value={language} data-testid={`select-option-language-${language.toLowerCase()}`}>
                    {language}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Select value={genreFilter} onValueChange={setGenreFilter}>
              <SelectTrigger className="w-full sm:w-36 rounded-none" data-testid="select-genre-filter">
                <SelectValue placeholder="Genre" />
              </SelectTrigger>
              <SelectContent className="rounded-none">
                <SelectItem value="all" data-testid="select-option-genre-all">All Genres</SelectItem>
                {genres.map(genre => (
                  <SelectItem key={genre} value={genre} data-testid={`select-option-genre-${genre.toLowerCase()}`}>
                    {genre}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 py-6 space-y-8">
        {/* Featured Movies Banner */}
        {featuredMovies.length > 0 && !searchTerm && !isLoading && (
          <div className="space-y-4">
            <h2 className="text-xl font-bold flex items-center gap-2">
              <TrendingUp className="h-5 w-5" />
              Now Showing
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {featuredMovies.map(movie => (
                <Card
                  key={`featured-${movie.id}`}
                  className="group cursor-pointer overflow-hidden border-white/10 rounded-none hover:border-primary/50 transition-all"
                  onClick={() => navigate(`/movies/${movie.id}`)}
                  data-testid={`card-featured-${movie.id}`}
                >
                  <div className="relative aspect-[16/9] bg-white/5 overflow-hidden">
                    {movie.bannerUrl ? (
                      <img
                        src={movie.bannerUrl}
                        alt={movie.title}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Popcorn className="h-12 w-12 text-white/60" />
                      </div>
                    )}
                    {movie.imdbRating && (
                      <div className="absolute top-3 right-3 bg-black/80 px-2 py-1 flex items-center gap-1 rounded-none">
                        <Star className="h-3 w-3 fill-white text-white/80" />
                        <span className="text-xs font-bold text-white">{movie.imdbRating}</span>
                      </div>
                    )}
                  </div>
                  <CardContent className="p-4 space-y-2">
                    <h3 className="font-bold text-lg">{movie.title}</h3>
                    <div className="flex flex-wrap gap-2">
                      {movie.genre?.map(g => (
                        <Badge key={g} variant="secondary" className="rounded-none text-xs">
                          {g}
                        </Badge>
                      ))}
                    </div>
                    <div className="flex items-center justify-between text-sm text-white/60">
                      <span>{movie.language}</span>
                      <span className="flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        {movie.duration} mins
                      </span>
                    </div>
                    <Button
                      className="w-full rounded-none mt-2"
                      data-testid={`button-book-featured-${movie.id}`}
                    >
                      Book Tickets
                    </Button>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        )}

        {/* All Movies Section */}
        <div className="space-y-4">
          <h2 className="text-xl font-bold">
            {searchTerm ? `Search Results (${filteredMovies.length})` : "All Movies"}
          </h2>
          {isLoading ? (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
              {[...Array(10)].map((_, i) => (
                <div key={i} className="space-y-3">
                  <Skeleton className="aspect-[2/3] w-full rounded-none" />
                  <Skeleton className="h-4 w-3/4 rounded-none" />
                  <Skeleton className="h-3 w-1/2 rounded-none" />
                </div>
              ))}
            </div>
          ) : filteredMovies.length === 0 ? (
            <div className="text-center py-12">
              <Film className="h-16 w-16 mx-auto text-white/60 mb-4" />
              <h3 className="text-lg font-semibold mb-2">No movies found</h3>
              <p className="text-sm text-white/60">Try adjusting your filters or search term</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
              {pagination.paginatedData.map((movie) => (
                <Card
                  key={movie.id}
                  className="group cursor-pointer overflow-hidden border-white/10 rounded-none hover:border-primary/50 transition-all"
                  onClick={() => navigate(`/movies/${movie.id}`)}
                  data-testid={`card-movie-${movie.id}`}
                >
                  <div className="aspect-[2/3] relative overflow-hidden bg-white/5">
                    {movie.posterUrl ? (
                      <img
                        src={movie.posterUrl}
                        alt={movie.title}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                        data-testid={`img-movie-poster-${movie.id}`}
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Popcorn className="h-12 w-12 text-white/60" />
                      </div>
                    )}
                    <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/90 to-transparent p-3">
                      <div className="flex items-center justify-between text-white">
                        <div className="flex items-center gap-1 text-xs">
                          <Star className="h-3 w-3 fill-white text-white/80" />
                          <span data-testid={`text-rating-${movie.id}`}>{movie.imdbRating || movie.rating || "N/A"}</span>
                        </div>
                        <Badge variant="secondary" className="rounded-none text-xs">
                          {movie.language}
                        </Badge>
                      </div>
                    </div>
                  </div>
                  <CardContent className="p-3 space-y-1">
                    <h3 className="font-semibold text-sm line-clamp-1" data-testid={`text-movie-title-${movie.id}`}>
                      {movie.title}
                    </h3>
                    <p className="text-xs text-white/60 line-clamp-1" data-testid={`text-genre-${movie.id}`}>
                      {movie.genre?.join(", ") || "Drama"}
                    </p>
                    <Button
                      size="sm"
                      className="w-full rounded-none text-xs mt-2"
                      data-testid={`button-book-${movie.id}`}
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate(`/movies/${movie.id}`);
                      }}
                    >
                      Book
                    </Button>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}

          {filteredMovies.length > 0 && !isLoading && (
            <PaginationControls
              currentPage={pagination.currentPage}
              totalPages={pagination.totalPages}
              onPageChange={pagination.goToPage}
              canGoNext={pagination.canGoNext}
              canGoPrevious={pagination.canGoPrevious}
              startIndex={pagination.startIndex}
              endIndex={pagination.endIndex}
              totalItems={pagination.totalItems}
              className="mt-6"
            />
          )}
        </div>
      </div>
    </div>
  );
}

