import { useState, useEffect, useRef } from "react";
import { useLocation } from "wouter";
import { useNavigationHistory } from "@/hooks/use-navigation-history";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import {
  ArrowLeft,
  ArrowRight,
  Train,
  CheckCircle,
  Users,
  Shield,
  Clock,
  MapPin,
  User,
  UserCircle,
  Calendar,
  Star,
  Wifi,
  Utensils,
  CreditCard,
  Plus,
  X,
  Mail,
  Phone,
  Smartphone,
  Building2
} from "lucide-react";

interface PassengerInfo {
  title: string;
  firstName: string;
  lastName: string;
  age: string;
  gender: string;
  berth: string;
}

interface BookingStage {
  id: string;
  title: string;
  shortTitle: string;
  icon: React.ComponentType<{ className?: string }>;
  description: string;
}

const BOOKING_STAGES: BookingStage[] = [
  {
    id: 'train-details',
    title: 'Train Information',
    shortTitle: 'Train',
    icon: Train,
    description: 'Review train details and journey information'
  },
  {
    id: 'traveler-info',
    title: 'Traveler Details',
    shortTitle: 'Details',
    icon: UserCircle,
    description: 'Passenger and contact information'
  },
  {
    id: 'summary',
    title: 'Booking Summary',
    shortTitle: 'Summary',
    icon: CheckCircle,
    description: 'Review your booking before payment'
  },
  {
    id: 'payment',
    title: 'Payment Method',
    shortTitle: 'Payment',
    icon: CreditCard,
