  Heart,
  Film,
  PartyPopper,
  Dumbbell,
  BookOpen,
  Wrench,
  Gem,
  Newspaper,
  AlertCircle,
  ArrowRight
} from "lucide-react";

interface ProfileSection {
  id: string;
  title: string;
  description: string;
  icon: any;
  route: string;
  value?: string;
  subtitle?: string;
  badge?: string;
  isNew?: boolean;
  color?: string;
  shadow?: string;
}

export default function Profile() {
  const { user, isAuthenticated, logout } = useAuth();
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [hideAmounts, setHideAmounts] = useState(false);
  const [showLogoutDialog, setShowLogoutDialog] = useState(false);
  const [showLoadingScreen, setShowLoadingScreen] = useState(false);
  const [fadeOutLoading, setFadeOutLoading] = useState(false);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate("/");
    }
  }, [isAuthenticated, navigate]);

  const profileStats = {
    walletBalance: 245600,
    totalInvestments: 1850000,
    activeLoans: 2,
    todaysSpend: 2450,
    netWorth: 2850000,
    creditScore: 785,
    kycStatus: "verified",
    membershipTier: "Gold",
    rewardPoints: 8450
  };

  const formatCurrency = useCallback((amount: number) => {
    if (hideAmounts) return "₹••••••";
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount);
  }, [hideAmounts]);

  const formatCompact = useCallback((amount: number) => {
    if (hideAmounts) return "••••";
    if (amount >= 10000000) return `₹${(amount / 10000000).toFixed(1)}Cr`;
    if (amount >= 100000) return `₹${(amount / 100000).toFixed(1)}L`;
    if (amount >= 1000) return `₹${(amount / 1000).toFixed(1)}K`;
    return `₹${amount}`;
  }, [hideAmounts]);

  const profileSections: ProfileSection[] = [
    {
      id: "about",
      title: "About",
      description: "Identity & KYC details",
      icon: User,
      route: "/profile/about",
      badge: profileStats.kycStatus === "verified" ? "Verified" : "Pending"
    },
    {
      id: "edit-profile",
      title: "Edit Profile",
      description: "Update personal info",
      icon: Edit3,
      route: "/edit-profile"
    },
    {
      id: "my-loans",
      title: "My Loans",
      description: "All loans & repayments",
      icon: Building2,
      route: "/my-loans",
      value: `${profileStats.activeLoans} active`,
      subtitle: "View details"
    },
    {
      id: "my-investments",
