  currentIndex: number;
  forecastIndex: number;
  change: number;
  changePercent: number;
  outlook: 'bullish' | 'bearish' | 'neutral';
  confidence: number;
  keyDrivers: string[];
  riskFactors: string[];
  timeframe: string;
}

interface EconomicIndicator {
  name: string;
  current: number;
  forecast: number;
  change: number;
  unit: string;
  importance: 'high' | 'medium' | 'low';
  trend: 'improving' | 'declining' | 'stable';
