                    "font-light tracking-wider transition-opacity",
                    selectedAccount === account.id ? "opacity-100 text-white" : "opacity-60 text-white/60"
                  )}>
                    {account.bankName}
                  </p>
                  <Badge className={cn(
                    "rounded-none border font-light text-xs",
