                  </div>
                </div>
              </div>
            </div>
          ))}

          {filteredCryptos.length === 0 && (
            <div className="text-center py-12">
              <Search className="h-12 w-12 text-white/20 mx-auto mb-3" />
              <p className="text-white/60 mb-2">No cryptocurrencies found</p>
