    icon: Users,
    description: 'Choose your preferred seats'
  },
  {
    id: 'fnb-selection',
    title: 'Food & Beverages',
    shortTitle: 'F&B',
    icon: Popcorn,
    description: 'Add snacks and beverages'
  },
  {
    id: 'contact-info',
