    },
    "3": {
      id: "3",
      name: "Cinepolis - Royal Meenakshi Mall",
      area: "Bannerghatta Road",
      city: "Bangalore",
      address: "Royal Meenakshi Mall, Bannerghatta Road",
      contact: "+91 1800-102-2555",
      screens: 10,
      totalSeats: 1850,
      buildYear: 2020,
      facilities: {
        parking: true,
        food_court: true,
        wheelchair_access: true,
        "3d_screen": true,
        dolby_atmos: true
      },
      amenities: {
        ac: true,
        recliner_seats: true,
        premium_seats: true,
        valet_parking: true
      },
      otherMovies: ["Jawan", "Pathaan", "Tiger 3"]
    }
  };
