} from "lucide-react";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";

interface Flight {
  id: string;
  airline: string;
  flightNumber: string;
  from: string;
  to: string;
  fromCode: string;
  toCode: string;
  departTime: string;
  arriveTime: string;
  duration: string;
  price: number;
  stops: number;
  class: string;
  amenities: string[];
  rating: number;
}

const SAMPLE_FLIGHTS: Flight[] = [
  {
    id: "1",
    airline: "IndiGo",
    flightNumber: "6E 2345",
    from: "Delhi",
