    price: 2999,
    stops: 0,
    class: "Economy",
    amenities: ["Meal"],
    rating: 4.2,
  },
  {
    id: "4",
    airline: "Vistara",
    flightNumber: "UK 995",
    from: "Delhi",
    to: "Mumbai",
    fromCode: "DEL",
    toCode: "BOM",
    departTime: "16:20",
    arriveTime: "18:35",
    duration: "2h 15m",
    price: 4899,
    stops: 0,
    class: "Economy",
    amenities: ["WiFi", "Meal", "Lounge", "Extra Legroom"],
    rating: 4.8,
  },
  {
    id: "5",
    airline: "AirAsia",
    flightNumber: "I5 764",
    from: "Delhi",
    to: "Mumbai",
    fromCode: "DEL",
    toCode: "BOM",
    departTime: "19:00",
    arriveTime: "21:20",
