    price: 2699,
    stops: 0,
    class: "Economy",
    amenities: [],
    rating: 4.0,
  },
];

export default function FlightsResults() {
  const [location, navigate] = useLocation();
  const searchParams = new URLSearchParams(location.split('?')[1]);

  const from = searchParams.get('from') || '';
  const to = searchParams.get('to') || '';
  const departDate = searchParams.get('departDate') || '';
  const passengers = searchParams.get('passengers') || '1';
  const flightClass = searchParams.get('class') || 'Economy';

  const [flights, setFlights] = useState<Flight[]>(SAMPLE_FLIGHTS);
  const [searchQuery, setSearchQuery] = useState("");
  const [sortBy, setSortBy] = useState("price");
  const [filterStops, setFilterStops] = useState("all");

  useEffect(() => {
    let filtered = [...SAMPLE_FLIGHTS];

    // Search filter
    if (searchQuery) {
      filtered = filtered.filter(flight => 
        flight.airline.toLowerCase().includes(searchQuery.toLowerCase()) ||
        flight.flightNumber.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    // Stops filter
    if (filterStops === "nonstop") {
      filtered = filtered.filter(flight => flight.stops === 0);
    } else if (filterStops === "onestop") {
      filtered = filtered.filter(flight => flight.stops === 1);
    }

    // Sort
    if (sortBy === "price") {
      filtered.sort((a, b) => a.price - b.price);
    } else if (sortBy === "duration") {
      filtered.sort((a, b) => parseInt(a.duration) - parseInt(b.duration));
    } else if (sortBy === "rating") {
      filtered.sort((a, b) => b.rating - a.rating);
    } else if (sortBy === "departure") {
      filtered.sort((a, b) => a.departTime.localeCompare(b.departTime));
    }

    setFlights(filtered);
  }, [searchQuery, sortBy, filterStops]);

  const pagination = usePagination({
    data: flights,
    itemsPerPage: 10,
  });

  const handleFlightSelect = (flightId: string) => {
    navigate(`/flights/details/${flightId}?from=${from}&to=${to}&date=${departDate}&passengers=${passengers}&class=${flightClass}`);
  };

  return (
    <div className="min-h-screen bg-black text-white pb-24">
      {/* Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/flights/search")}
            className="text-white/60 hover:text-white hover:bg-white/10 p-2 rounded-none"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">{from} → {to}</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">{departDate} • {passengers} {passengers === "1" ? "Passenger" : "Passengers"}</p>
          </div>
          <div className="w-10" />
        </div>
      </div>

      {/* Search & Filter Bar */}
      <div className="fixed top-[65px] left-0 right-0 z-40 bg-black/95 backdrop-blur-xl border-b border-white/10 p-3 space-y-2">
        <div className="flex gap-2">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-white/40" />
            <Input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search airline or flight number..."
              className="bg-white/5 border-white/10 text-white rounded-none pl-10"
              data-testid="input-search-flights"
            />
          </div>
        </div>
        <div className="flex gap-2">
          <Select value={sortBy} onValueChange={setSortBy}>
            <SelectTrigger className="flex-1 bg-white/5 border-white/10 text-white rounded-none text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="bg-zinc-900 border-white/10">
              <SelectItem value="price">Sort: Price</SelectItem>
              <SelectItem value="duration">Sort: Duration</SelectItem>
              <SelectItem value="rating">Sort: Rating</SelectItem>
              <SelectItem value="departure">Sort: Departure</SelectItem>
            </SelectContent>
          </Select>

          <Select value={filterStops} onValueChange={setFilterStops}>
            <SelectTrigger className="flex-1 bg-white/5 border-white/10 text-white rounded-none text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="bg-zinc-900 border-white/10">
              <SelectItem value="all">All Flights</SelectItem>
              <SelectItem value="nonstop">Non-stop</SelectItem>
              <SelectItem value="onestop">1 Stop</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Main Content */}
      <div className="pt-[175px] px-4 space-y-3">
        {/* Results Header */}
        <div className="flex items-center justify-between">
          <p className="text-sm text-white/60 font-light">
            {flights.length} {flights.length === 1 ? 'flight' : 'flights'} available
          </p>
          <Badge className="bg-white/10 text-white border-white/20 rounded-none font-light text-xs">
            {flightClass}
          </Badge>
        </div>

        {/* Flights List */}
        {flights.length === 0 ? (
          <div className="bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl border border-white/10 p-8 text-center">
            <Plane className="h-12 w-12 text-white/40 mx-auto mb-3" />
            <p className="text-white/60 font-light">No flights found</p>
            <p className="text-xs text-white/40 mt-1">Try adjusting your filters</p>
          </div>
        ) : (
          pagination.paginatedData.map((flight) => (
            <button
              key={flight.id}
              onClick={() => handleFlightSelect(flight.id)}
              className="w-full bg-gradient-to-br from-white/10 via-white/5 to-transparent backdrop-blur-xl border border-white/10 hover:border-white/20 transition-all"
              data-testid={`flight-${flight.id}`}
            >
              <CardContent className="p-4">
                {/* Airline & Flight Number */}
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-white/10 border border-white/20 flex items-center justify-center">
                      <Plane className="h-4 w-4 text-white" />
                    </div>
                    <div className="text-left">
                      <p className="text-sm font-light text-white">{flight.airline}</p>
                      <p className="text-[10px] text-white/50 uppercase tracking-wider">{flight.flightNumber}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-1">
                    <Star className="h-3 w-3 text-yellow-500 fill-yellow-500" />
                    <span className="text-xs text-white/60 font-light">{flight.rating}</span>
                  </div>
                </div>

                {/* Flight Times */}
                <div className="flex items-center justify-between mb-3">
                  <div className="text-left">
                    <p className="text-lg font-light text-white">{flight.departTime}</p>
                    <p className="text-xs text-white/50">{flight.fromCode}</p>
                  </div>

                  <div className="flex-1 mx-4 text-center">
                    <p className="text-[10px] text-white/40 uppercase tracking-wider mb-1">{flight.duration}</p>
                    <div className="flex items-center">
                      <div className="h-px flex-1 bg-white/20"></div>
                      <Plane className="h-3 w-3 text-white/40 mx-2" />
                      <div className="h-px flex-1 bg-white/20"></div>
                    </div>
                    <p className="text-[10px] text-white/40 mt-1">
                      {flight.stops === 0 ? 'Non-stop' : `${flight.stops} stop${flight.stops > 1 ? 's' : ''}`}
                    </p>
                  </div>

                  <div className="text-right">
                    <p className="text-lg font-light text-white">{flight.arriveTime}</p>
                    <p className="text-xs text-white/50">{flight.toCode}</p>
                  </div>
                </div>

                {/* Amenities */}
                {flight.amenities.length > 0 && (
                  <div className="flex gap-2 mb-3 flex-wrap">
                    {flight.amenities.map((amenity, idx) => (
                      <Badge key={idx} className="bg-white/5 text-white/70 border-white/10 rounded-none text-[10px] font-light">
                        {amenity}
                      </Badge>
                    ))}
                  </div>
                )}

                {/* Price */}
                <div className="flex items-center justify-between pt-3 border-t border-white/10">
                  <p className="text-xs text-white/40 uppercase tracking-wider font-light">Starting from</p>
                  <div className="text-right">
                    <p className="text-xl font-light text-white">₹{flight.price.toLocaleString()}</p>
                    <p className="text-[10px] text-white/40">per person</p>
                  </div>
                </div>
              </CardContent>
            </button>
          ))
        )}

        {flights.length > 0 && (
          <PaginationControls
            currentPage={pagination.currentPage}
            totalPages={pagination.totalPages}
            onPageChange={pagination.goToPage}
            canGoNext={pagination.canGoNext}
            canGoPrevious={pagination.canGoPrevious}
            startIndex={pagination.startIndex}
            endIndex={pagination.endIndex}
            totalItems={pagination.totalItems}
            className="mt-6 mb-6"
          />
        )}
      </div>
    </div>
  );
}

client/src/pages/my-movie-tickets.tsx.content:
import { useEffect } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/hooks/use-auth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { ArrowLeft, Calendar, MapPin, Ticket, ChevronRight, Film } from "lucide-react";
import { format } from "date-fns";
import type { MovieBooking } from "@shared/schema";
import { usePagination } from "@/hooks/use-pagination";
import { PaginationControls } from "@/components/ui/pagination-controls";

export default function MyMovieTickets() {
  const { isAuthenticated, isLoading: authLoading } = useAuth();
  const [, navigate] = useLocation();

  useEffect(() => {
    if (!authLoading && !isAuthenticated) {
      navigate("/login");
    }
  }, [isAuthenticated, authLoading, navigate]);

  const { data: bookingsData, isLoading } = useQuery<{ success: boolean; bookings: MovieBooking[] }>({
    queryKey: ["/api/movie-bookings/user"],
    enabled: isAuthenticated,
  });

  const bookings = bookingsData?.bookings || [];
  const now = new Date();
  const upcomingBookings = bookings.filter(b => new Date(b.showAt) >= now);
  const pastBookings = bookings.filter(b => new Date(b.showAt) < now);

  const getStatusColor = (status: string) => {
    switch (status) {
      case "confirmed":
        return "bg-white/10 text-white/80 border-white/20";
      case "cancelled":
        return "bg-white/10 text-white/80 border-white/20";
      case "used":
        return "bg-white/10 text-white/80 border-white/20";
      default:
        return "bg-white/10 text-white/60 border-white/20";
    }
  };

  if (authLoading || isLoading) {
    return (
      <div className="min-h-screen bg-black text-white">
        <div className="container mx-auto px-4 py-6 max-w-4xl">
          <Skeleton className="h-8 w-48 mb-6 bg-white/10" />
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-40 w-full bg-white/10" />
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return null;
  }

  return (
    <div className="min-h-screen bg-black text-white pb-24">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-black/95 backdrop-blur-md border-b border-white/10">
        <div className="container mx-auto px-4 py-4 max-w-4xl">
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => navigate("/profile")}
              className="text-white hover:bg-white/10 rounded-full"
              data-testid="button-back"
            >
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <h1 className="text-2xl font-bold">My Movie Tickets</h1>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 py-6 max-w-4xl">
        {bookings.length === 0 ? (
          <div className="text-center py-16">
            <Film className="h-16 w-16 text-white/20 mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">No Movie Tickets</h2>
            <p className="text-white/60 mb-6">You haven't booked any movie tickets yet</p>
            <Button
              onClick={() => navigate("/movies")}
              className="bg-white text-black hover:bg-white/90 rounded-full px-6"
              data-testid="button-browse-movies"
            >
              Browse Movies
            </Button>
          </div>
        ) : (
          <>
            {/* Upcoming Bookings */}
            {upcomingBookings.length > 0 && (
              <div className="mb-8">
                <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                  <Ticket className="h-5 w-5" />
                  Upcoming Shows
                </h2>
                <div className="space-y-4">
                  {upcomingBookings.map((booking) => (
                    <Card
                      key={booking.id}
                      onClick={() => navigate(`/movie-ticket/${booking.id}`)}
                      className="bg-white/5 border-white/10 hover:bg-white/10 transition-colors cursor-pointer rounded-xl overflow-hidden"
                      data-testid={`card-booking-${booking.id}`}
                    >
                      <CardContent className="p-4">
                        <div className="flex items-start justify-between mb-3">
                          <div className="flex-1">
                            <h3 className="text-lg font-bold mb-1" data-testid={`text-movie-title-${booking.id}`}>
                              {booking.movieTitle}
                            </h3>
                            <p className="text-sm text-white/60" data-testid={`text-theater-${booking.id}`}>
                              {booking.theaterName}
                            </p>
                          </div>
                          <Badge className={getStatusColor(booking.status)} data-testid={`badge-status-${booking.id}`}>
                            {booking.status}
                          </Badge>
                        </div>

                        <div className="space-y-2 mb-3">
                          <div className="flex items-center gap-2 text-sm text-white/80">
                            <Calendar className="h-4 w-4" />
                            <span data-testid={`text-showtime-${booking.id}`}>
                              {format(new Date(booking.showAt), "EEE, dd MMM yyyy • hh:mm a")}
                            </span>
                          </div>
                          <div className="flex items-center gap-2 text-sm text-white/80">
                            <Ticket className="h-4 w-4" />
                            <span data-testid={`text-seats-${booking.id}`}>
                              {booking.seatNumbers && booking.seatNumbers.length > 0 ? booking.seatNumbers.join(", ") : "N/A"} • {booking.totalSeats} seat{booking.totalSeats !== 1 ? "s" : ""}
                            </span>
                          </div>
                        </div>

                        <div className="flex items-center justify-between pt-3 border-t border-white/10">
                          <div>
                            <p className="text-xs text-white/60">Booking ID</p>
                            <p className="text-sm font-mono" data-testid={`text-booking-ref-${booking.id}`}>
                              {booking.bookingReference}
                            </p>
                          </div>
                          <div className="text-right">
                            <p className="text-xs text-white/60">Total Amount</p>
                            <p className="text-lg font-bold" data-testid={`text-amount-${booking.id}`}>
                              ₹{booking.totalAmount}
                            </p>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            )}

            {/* Past Bookings */}
            {pastBookings.length > 0 && (
              <div>
                <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                  <Film className="h-5 w-5" />
                  Past Shows
                </h2>
                <div className="space-y-4">
                  {pastBookings.map((booking) => (
                    <Card
                      key={booking.id}
                      onClick={() => navigate(`/movie-ticket/${booking.id}`)}
                      className="bg-white/5 border-white/10 hover:bg-white/10 transition-colors cursor-pointer rounded-xl opacity-70 hover:opacity-100"
                      data-testid={`card-past-booking-${booking.id}`}
                    >
                      <CardContent className="p-4">
                        <div className="flex items-start justify-between mb-3">
                          <div className="flex-1">
                            <h3 className="text-lg font-bold mb-1" data-testid={`text-past-movie-title-${booking.id}`}>
                              {booking.movieTitle}
                            </h3>
                            <p className="text-sm text-white/60" data-testid={`text-past-theater-${booking.id}`}>
                              {booking.theaterName}
                            </p>
                          </div>
                          <Badge className={getStatusColor(booking.status)} data-testid={`badge-past-status-${booking.id}`}>
                            {booking.status === "used" ? "completed" : booking.status}
                          </Badge>
                        </div>

                        <div className="space-y-2 mb-3">
                          <div className="flex items-center gap-2 text-sm text-white/80">
                            <Calendar className="h-4 w-4" />
                            <span data-testid={`text-past-showtime-${booking.id}`}>
                              {format(new Date(booking.showAt), "EEE, dd MMM yyyy • hh:mm a")}
                            </span>
                          </div>
                          <div className="flex items-center gap-2 text-sm text-white/80">
                            <Ticket className="h-4 w-4" />
                            <span data-testid={`text-past-seats-${booking.id}`}>
                              {booking.seatNumbers && booking.seatNumbers.length > 0 ? booking.seatNumbers.join(", ") : "N/A"} • {booking.totalSeats} seat{booking.totalSeats !== 1 ? "s" : ""}
                            </span>
                          </div>
                        </div>

                        <div className="flex items-center justify-between pt-3 border-t border-white/10">
                          <div>
                            <p className="text-xs text-white/60">Booking ID</p>
                            <p className="text-sm font-mono" data-testid={`text-past-booking-ref-${booking.id}`}>
                              {booking.bookingReference}
                            </p>
                          </div>
                          <ChevronRight className="h-5 w-5 text-white/40" />
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

