  minAmount: number;
  maxDiscount?: number;
  category: "bills" | "travel" | "investments" | "shopping" | "food" | "all";
  merchantName: string;
  validFrom: string;
  validUntil: string;
  isUsed: boolean;
  usedAt?: string;
  termsConditions: string[];
