    return new Date(dateString).toLocaleDateString('en-IN', { 
      day: '2-digit',
      month: 'short', 
      year: 'numeric' 
    });
  };

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case "bills": return Ticket;
      case "travel": return ShoppingBag;
