        </div>

        {/* Tabs */}
        <div className="px-4 mt-6">
          <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
            <TabsList className="bg-white/5 border border-white/10 w-full h-auto p-1 rounded-xl grid grid-cols-3">
