## Implementation Guidelines

### 1. Component Structure

Every component should follow this structure:

```
ComponentName/
├── ComponentName.tsx          # Main component implementation
├── ComponentName.types.ts     # TypeScript interfaces and types
├── ComponentName.stories.tsx  # Storybook stories (optional)
├── ComponentName.test.tsx     # Unit tests
└── index.ts                   # Barrel export
```

### 2. Component Template

```typescript
// ComponentName.types.ts
import { HTMLAttributes } from 'react';

export interface ComponentNameProps extends HTMLAttributes<HTMLDivElement> {
  variant?: 'default' | 'primary' | 'secondary';
  size?: 'sm' | 'md' | 'lg';
  isDisabled?: boolean;
  'data-testid'?: string;
}

// ComponentName.tsx
import { forwardRef } from 'react';
import { cn } from '@/lib/utils';
import { ComponentNameProps } from './ComponentName.types';

export const ComponentName = forwardRef<HTMLDivElement, ComponentNameProps>(
  ({ 
    variant = 'default', 
    size = 'md', 
    isDisabled = false,
    className,
    'data-testid': dataTestId,
    ...props 
  }, ref) => {
    return (
      <div
        ref={ref}
        data-testid={dataTestId || 'component-name'}
        className={cn(
          'base-classes',
          {
            'variant-default': variant === 'default',
            'variant-primary': variant === 'primary',
            'size-sm': size === 'sm',
            'size-md': size === 'md',
            'opacity-50 cursor-not-allowed': isDisabled,
          },
          className
        )}
        {...props}
      />
    );
  }
);

ComponentName.displayName = 'ComponentName';

// index.ts
export { ComponentName } from './ComponentName';
export type { ComponentNameProps } from './ComponentName.types';
```

### 3. Styling Guidelines

#### Use Tailwind Classes with cn() Utility
```typescript
import { cn } from '@/lib/utils';

const classes = cn(
  'base-class',
  condition && 'conditional-class',
  {
    'variant-a': variant === 'a',
    'variant-b': variant === 'b',
  },
  className // Allow className override
);
```

#### Design Token Usage
```typescript
// Use CSS variables from design tokens
<div style={{ 
  backgroundColor: 'var(--background)',
  color: 'var(--foreground)',
}} />

// Or use Tailwind classes
<div className="bg-background text-foreground" />
```

#### Component Variants with CVA
```typescript
import { cva, type VariantProps } from 'class-variance-authority';

const buttonVariants = cva(
  'inline-flex items-center justify-center transition-colors font-medium',
  {
    variants: {
      variant: {
        primary: 'bg-primary text-primary-foreground hover:bg-primary/90',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
      },
      size: {
        sm: 'h-9 px-3 text-sm',
        md: 'h-10 px-4',
        lg: 'h-11 px-8 text-lg',
      },
    },
    defaultVariants: {
      variant: 'primary',
      size: 'md',
    },
  }
);
```

### 4. State Management

```typescript
// Local state with useState
const [value, setValue] = useState<string>('');

// Form state with react-hook-form
const form = useForm<FormData>({
  resolver: zodResolver(schema),
});

// Server state with React Query
const { data, isLoading } = useQuery({
  queryKey: ['/api/data'],
});
```

### 5. Accessibility (a11y)

```typescript
// Always include ARIA attributes
<button
  aria-label="Close dialog"
  aria-pressed={isPressed}
  aria-disabled={isDisabled}
  role="button"
  tabIndex={0}
/>

// Keyboard navigation
const handleKeyDown = (e: React.KeyboardEvent) => {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    onClick?.();
  }
};

// Focus management
const ref = useRef<HTMLElement>(null);
useEffect(() => {
  if (isOpen) {
    ref.current?.focus();
  }
}, [isOpen]);
```

### 6. Error Handling

```typescript
// Error boundaries for component errors
<ErrorBoundary fallback={<ErrorFallback />}>
  <Component />
</ErrorBoundary>

// Async error handling
const { data, error, isError } = useQuery({
  queryKey: ['/api/data'],
  onError: (error) => {
    toast.error('Failed to load data');
  },
});

if (isError) {
  return <ErrorState error={error} />;
}
```

### 7. Performance Optimization

```typescript
// Memoization
const MemoizedComponent = memo(Component);

// Callback memoization
const handleClick = useCallback(() => {
  // handler logic
}, [dependencies]);

// Value memoization
const computedValue = useMemo(() => {
  return expensiveComputation(data);
}, [data]);

// Code splitting
const LazyComponent = lazy(() => import('./Component'));

// Virtualization for large lists
<VirtualList
  items={largeDataset}
  itemHeight={50}
  renderItem={(item) => <ListItem {...item} />}
/>
```

