      const newSet = new Set(currentHidden);

      if (newSet.has(userId)) {
        newSet.delete(userId);
      } else {
        newSet.add(userId);
      }

      if (newSet.size === 0) {
        newMap.delete(expenseId);
      } else {
        newMap.set(expenseId, newSet);
      }

      return newMap;
    });
  };

