const categoryInfo: Record<string, { name: string; description: string }> = {
  "hotel-food": { name: "Hotel Food", description: "Order from restaurants" },
  "supermart": { name: "Supermart", description: "Groceries in 10 minutes" },
  "medicine": { name: "Medicine", description: "Pharmacy & healthcare" },
  "electronics": { name: "Electronics", description: "Gadgets & accessories" },
  "beauty": { name: "Beauty & Personal Care", description: "Cosmetics & wellness" },
  "pet": { name: "Pet Supplies", description: "For your furry friends" },
  "home": { name: "Home & Kitchen", description: "Home essentials" }
};

export default function FoodDeliveryListing() {
  const { user } = useAuth();
  const [, navigate] = useLocation();
  const [, params] = useRoute("/food-delivery/:category");
  const category = params?.category || "hotel-food";

  const [searchTerm, setSearchTerm] = useState("");
  const [selectedFilters, setSelectedFilters] = useState<{
    veg: boolean;
    rating: string;
    deliveryTime: string;
    sortBy: string;
    premium: boolean;
  }>({
    veg: false,
    rating: "all",
    deliveryTime: "all",
    sortBy: "relevance",
    premium: false
  });

  const info = categoryInfo[category] || categoryInfo["hotel-food"];
  const vendors = categoryVendors[category] || [];

  const filteredVendors = useMemo(() => {
    let filtered = [...vendors];

    if (searchTerm) {
      filtered = filtered.filter(v => 
        v.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.cuisines.some((c: string) => c.toLowerCase().includes(searchTerm.toLowerCase()))
      );
    }

    if (selectedFilters.veg) {
      filtered = filtered.filter(v => v.isVeg === 1);
    }

    if (selectedFilters.premium) {
      filtered = filtered.filter(v => v.isPremium === 1);
    }

    if (selectedFilters.rating !== "all") {
      const minRating = parseFloat(selectedFilters.rating);
      filtered = filtered.filter(v => v.rating >= minRating);
    }

    if (selectedFilters.sortBy === "rating") {
      filtered.sort((a, b) => b.rating - a.rating);
    } else if (selectedFilters.sortBy === "delivery-time") {
      filtered.sort((a, b) => parseInt(a.deliveryTime) - parseInt(b.deliveryTime));
    } else if (selectedFilters.sortBy === "distance") {
      filtered.sort((a, b) => parseFloat(a.distance) - parseFloat(b.distance));
    }

    return filtered;
  }, [vendors, searchTerm, selectedFilters]);

  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (selectedFilters.veg) count++;
    if (selectedFilters.premium) count++;
    if (selectedFilters.rating !== "all") count++;
    if (selectedFilters.sortBy !== "relevance") count++;
    return count;
  }, [selectedFilters]);

  const clearFilters = () => {
    setSelectedFilters({
      veg: false,
      rating: "all",
      deliveryTime: "all",
      sortBy: "relevance",
      premium: false
    });
  };

  return (
    <div className="min-h-screen bg-black text-white pb-24">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <div className="flex items-center gap-3 flex-1">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => navigate("/food-delivery")}
