            <SheetContent side="bottom" className="bg-black border-white/10 max-h-[90vh] overflow-y-auto">
              <SheetHeader>
                <SheetTitle className="text-white uppercase tracking-wider text-sm">Filters & Sort</SheetTitle>
              </SheetHeader>
              <div className="mt-6 space-y-6">
                {category === "hotel-food" && (
                  <>
                    <div>
                      <h3 className="text-xs font-semibold text-white/60 mb-3 uppercase tracking-widest">Food Preference</h3>
                      <Button
                        variant={selectedFilters.veg ? "default" : "outline"}
                        size="sm"
                        onClick={() => setSelectedFilters(prev => ({ ...prev, veg: !prev.veg }))}
                        className={selectedFilters.veg ? "bg-white text-black rounded-none" : "bg-white/5 border-white/20 text-white rounded-none"}
