import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  ArrowLeft,
  MapPin,
  Plus,
  ChevronRight,
  CreditCard,
  Wallet,
  Banknote,
  Check,
  AlertCircle,
  Clock,
  User,
  Phone
} from "lucide-react";

export default function FoodCheckout() {
  const [, navigate] = useLocation();
  const [cart, setCart] = useState<any>(null);
  const [billDetails, setBillDetails] = useState<any>(null);
  const [selectedAddress, setSelectedAddress] = useState<string>("1");
  const [selectedPayment, setSelectedPayment] = useState<string>("upi");

  useEffect(() => {
    const savedCart = localStorage.getItem('foodCart');
    const savedBill = localStorage.getItem('foodCartTotal');

    if (savedCart) setCart(JSON.parse(savedCart));
    if (savedBill) setBillDetails(JSON.parse(savedBill));
  }, []);

  const addresses = [
    {
      id: "1",
      type: "Home",
      name: "John Doe",
      phone: "9876543210",
      address: "123, MG Road, Sector 18",
      city: "Noida, Uttar Pradesh",
      pincode: "201301"
    },
    {
      id: "2",
      type: "Work",
      name: "John Doe",
      phone: "9876543210",
      address: "456, Tech Park, Sector 62",
      city: "Noida, Uttar Pradesh",
      pincode: "201309"
    }
  ];

  const paymentMethods = [
    { id: "upi", name: "UPI", icon: Wallet, description: "Pay via UPI apps" },
    { id: "card", name: "Card", icon: CreditCard, description: "Credit/Debit Card" },
    { id: "cash", name: "Cash", icon: Banknote, description: "Cash on Delivery" }
  ];

  const handlePlaceOrder = () => {
    const orderId = `ORD${Date.now()}`;
    const orderData = {
      id: orderId,
      vendorName: cart?.vendorName || "Restaurant",
      items: cart?.items || {},
      products: cart?.products || [],
      billDetails,
      address: addresses.find(a => a.id === selectedAddress),
      paymentMethod: paymentMethods.find(p => p.id === selectedPayment)?.name,
      status: "confirmed",
      timestamp: new Date().toISOString()
    };

    localStorage.setItem('currentOrder', JSON.stringify(orderData));

    const existingOrders = localStorage.getItem('foodOrders');
    const orders = existingOrders ? JSON.parse(existingOrders) : [];
    orders.unshift(orderData);
    localStorage.setItem('foodOrders', JSON.stringify(orders));

    localStorage.removeItem('foodCart');
    localStorage.removeItem('foodCartTotal');

    navigate(`/food-delivery/success/${orderId}`);
  };

  if (!cart || !billDetails) {
    return (
