import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  ArrowLeft, 
  ShoppingBag, 
  Clock, 
  ChevronRight,
  Package,
  CheckCircle
} from "lucide-react";

export default function FoodOrderHistory() {
  const [, navigate] = useLocation();
  const [orders, setOrders] = useState<any[]>([]);

  useEffect(() => {
    const savedOrders = localStorage.getItem('foodOrders');
    if (savedOrders) {
      setOrders(JSON.parse(savedOrders));
    }
  }, []);

  const getStatusColor = (status: string) => {
    switch (status) {
      case "confirmed": return "bg-green-500/20 text-green-300 border-green-500/30";
      case "preparing": return "bg-yellow-500/20 text-yellow-300 border-yellow-500/30";
      case "delivered": return "bg-blue-500/20 text-blue-300 border-blue-500/30";
      default: return "bg-white/10 text-white border-white/20";
    }
  };

  return (
    <div className="min-h-screen bg-black text-white pb-24">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center gap-3 py-4 px-4">
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={() => navigate("/food-delivery")} 
            className="text-white/60 hover:text-white hover:bg-white/10 rounded-none h-8 w-8" 
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" strokeWidth={1} />
          </Button>
          <div>
            <h1 className="text-sm font-bold tracking-wider uppercase">My Orders</h1>
            <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">Order History</p>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="pt-20 px-4 pb-8 w-full max-w-screen-lg mx-auto">
        {orders.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-[70vh]">
            <ShoppingBag className="h-16 w-16 text-white/20 mb-4" strokeWidth={1} />
            <h2 className="text-xl font-bold mb-2 tracking-wide">No orders yet</h2>
            <p className="text-white/60 text-center mb-6 text-sm font-light">
              Start ordering to see your order history
            </p>
            <Button 
              onClick={() => navigate("/food-delivery")} 
              className="bg-white text-black hover:bg-white/90 rounded-none h-12 px-8 font-semibold tracking-wider" 
              data-testid="button-browse-now"
            >
              BROWSE NOW
            </Button>
          </div>
        ) : (
          <>
            <div className="mb-4 pb-4 border-b border-white/10">
              <p className="text-sm font-semibold tracking-wide">
                {orders.length} {orders.length === 1 ? 'Order' : 'Orders'}
              </p>
              <p className="text-[10px] text-white/40 font-light uppercase tracking-widest">
                Total orders placed
              </p>
            </div>

            <div className="space-y-0">
              {orders.map((order) => {
                const cartItems = Object.entries(order.items).map(([productId, quantity]) => {
                  const product = order.products.find((p: any) => p.id === productId);
                  return product ? { ...product, quantity } : null;
                }).filter(Boolean);

                return (
                  <div
                    key={order.id}
                    onClick={() => navigate(`/food-delivery/order-detail/${order.id}`)}
                    className="group border-b border-white/10 cursor-pointer hover:border-white/30 transition-all bg-black hover:bg-white/5 p-6"
                    data-testid={`order-${order.id}`}
                  >
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex-1">
                        <h3 className="text-base font-semibold mb-1">{order.vendorName}</h3>
                        <p className="text-xs text-white/50 font-light mb-2">
                          {cartItems.map((item: any) => item.name).join(", ")}
                        </p>
                      </div>
                      <Badge className={`${getStatusColor(order.status)} rounded-none text-[10px] px-2 py-0.5 font-light tracking-widest shrink-0 ml-2`}>
                        {order.status.toUpperCase()}
                      </Badge>
                    </div>

                    <div className="flex items-center justify-between mb-3 text-[10px] font-light uppercase tracking-widest">
                      <div className="flex items-center gap-3 text-white/60">
                        <div className="flex items-center gap-1">
                          <Package className="h-3 w-3" strokeWidth={1} />
                          <span>{cartItems.length} items</span>
                        </div>
                        <div className="flex items-center gap-1">
                          <Clock className="h-3 w-3" strokeWidth={1} />
                          <span>{new Date(order.timestamp).toLocaleDateString()}</span>
                        </div>
                      </div>
                      <span className="text-white font-semibold">₹{order.billDetails?.total || 0}</span>
                    </div>

                    <div className="flex items-center justify-between pt-3 border-t border-white/10">
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={(e) => {
                            e.stopPropagation();
                            navigate(`/food-delivery/track/${order.id}`);
                          }}
                          className="bg-white/5 border-white/20 text-white hover:bg-white/10 rounded-none h-8 px-4 text-[10px] font-light tracking-widest"
                          data-testid={`button-track-${order.id}`}
                        >
                          TRACK ORDER
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={(e) => {
                            e.stopPropagation();
                            alert("Reorder functionality");
                          }}
                          className="bg-white/5 border-white/20 text-white hover:bg-white/10 rounded-none h-8 px-4 text-[10px] font-light tracking-widest"
                          data-testid={`button-reorder-${order.id}`}
                        >
                          REORDER
                        </Button>
                      </div>
                      <ChevronRight className="h-4 w-4 text-white/20 group-hover:text-white/40 group-hover:translate-x-1 transition-all" strokeWidth={1} />
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

client/src/pages/food-delivery/order-det.content:
import { useState, useEffect } from "react";
import { useLocation, useRoute } from "wouter";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  ArrowLeft,
  Download,
  Phone,
  MapPin,
  Clock,
  Package,
  Star
} from "lucide-react";

export default function FoodOrderDetail() {
  const [, navigate] = useLocation();
  const [, params] = useRoute("/food-delivery/order-detail/:id");
  const [order, setOrder] = useState<any>(null);

  useEffect(() => {
    const savedOrders = localStorage.getItem('foodOrders');
    if (savedOrders) {
      const orders = JSON.parse(savedOrders);
      const foundOrder = orders.find((o: any) => o.id === params?.id);
      if (foundOrder) {
        setOrder(foundOrder);
      }
    }
  }, [params?.id]);

  if (!order) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center">
        <Package className="h-12 w-12 text-white/40 mb-4" strokeWidth={1} />
      </div>
    );
  }

  const cartItems = Object.entries(order.items).map(([productId, quantity]) => {
    const product = order.products.find((p: any) => p.id === productId);
    return product ? { ...product, quantity } : null;
  }).filter(Boolean);

  const getStatusColor = (status: string) => {
    switch (status) {
      case "confirmed": return "bg-green-500/20 text-green-300 border-green-500/30";
      case "preparing": return "bg-yellow-500/20 text-yellow-300 border-yellow-500/30";
      case "delivered": return "bg-blue-500/20 text-blue-300 border-blue-500/30";
      default: return "bg-white/10 text-white border-white/20";
    }
  };

  return (
    <div className="min-h-screen bg-black text-white pb-24">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <div className="flex items-center gap-3">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => navigate("/food-delivery/orders")}
              className="text-white/60 hover:text-white hover:bg-white/10 rounded-none h-8 w-8"
              data-testid="button-back"
            >
              <ArrowLeft className="h-5 w-5" strokeWidth={1} />
            </Button>
            <div>
              <h1 className="text-sm font-bold tracking-wider uppercase">Order Details</h1>
              <p className="text-[10px] text-white/40 uppercase tracking-widest font-light">ID: {params?.id}</p>
            </div>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => alert("Download invoice")}
            className="text-white/60 hover:text-white hover:bg-white/10 rounded-none h-8 px-3"
            data-testid="button-download-invoice"
          >
            <Download className="h-4 w-4 mr-1" strokeWidth={1} />
            <span className="text-xs font-light tracking-widest">INVOICE</span>
          </Button>
        </div>
      </div>

      {/* Main Content */}
      <div className="pt-20 px-4 pb-8 w-full max-w-screen-lg mx-auto">
        {/* Order Status */}
        <div className="mb-6">
          <Badge className={`${getStatusColor(order.status)} rounded-none text-xs px-4 py-1 font-light tracking-widest`}>
            {order.status.toUpperCase()}
          </Badge>
          <p className="text-xs text-white/50 font-light mt-2">
            Ordered on {new Date(order.timestamp).toLocaleString()}
          </p>
        </div>

        {/* Restaurant Info */}
        <div className="mb-6 border border-white/10 bg-white/5 p-4">
          <h3 className="text-xs font-semibold text-white/60 uppercase tracking-widest mb-3">
            Restaurant
          </h3>
          <h4 className="text-base font-semibold">{order.vendorName}</h4>
        </div>

        {/* Items */}
        <div className="mb-6 border border-white/10 bg-white/5 p-4">
          <h3 className="text-xs font-semibold text-white/60 uppercase tracking-widest mb-4">
            Items Ordered
          </h3>
          <div className="space-y-3">
            {cartItems.map((item: any) => (
              <div key={item.id} className="flex justify-between">
                <div className="flex items-start gap-2 flex-1">
                  {item.isVeg === 1 ? (
                    <div className="w-4 h-4 border border-green-500 flex items-center justify-center shrink-0 mt-0.5">
                      <div className="w-2 h-2 bg-green-500 rounded-full" />
                    </div>
                  ) : (
                    <div className="w-4 h-4 border border-red-500 flex items-center justify-center shrink-0 mt-0.5">
                      <div className="w-2 h-2 bg-red-500 rounded-full" />
                    </div>
                  )}
                  <div>
                    <p className="text-sm font-semibold">{item.name}</p>
                    <p className="text-xs text-white/50 font-light">Qty: {item.quantity}</p>
                  </div>
                </div>
                <p className="text-sm font-semibold">₹{item.price * item.quantity}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Bill Details */}
        <div className="mb-6 border border-white/10 bg-white/5 p-4">
          <h3 className="text-xs font-semibold text-white/60 uppercase tracking-widest mb-4">
            Bill Details
          </h3>
          <div className="space-y-2 text-sm">
            <div className="flex justify-between font-light">
              <span className="text-white/60">Item Total</span>
              <span className="font-semibold">₹{order.billDetails?.subtotal || 0}</span>
            </div>
            <div className="flex justify-between font-light">
              <span className="text-white/60">Delivery Fee</span>
              <span className="font-semibold">₹{order.billDetails?.deliveryFee || 0}</span>
            </div>
            <div className="flex justify-between font-light">
              <span className="text-white/60">Taxes & Charges</span>
              <span className="font-semibold">₹{(order.billDetails?.platformFee || 0) + (order.billDetails?.gst || 0)}</span>
            </div>
            {order.billDetails?.tipAmount > 0 && (
              <div className="flex justify-between font-light">
                <span className="text-white/60">Delivery Tip</span>
