        vehicle: {
          id: "auto",
          code: "auto",
          name: "Auto",
          description: "Medium parcels & boxes",
          maxWeightKg: 150,
          maxDimensions: "80×60×60 cm",
          basePrice: 89,
          pricePerKm: 12,
          eta: "15-20 mins",
          features: ["GPS Tracking", "Covered", "Best for parcels"]
        },
        contactDetails: {
          pickupContactName: "Amit Sharma",
          pickupContactPhone: "9876543210",
          dropContactName: "Priya Singh",
          dropContactPhone: "9876543211"
        },
        pricing: {
          basePrice: 89,
          distanceCharge: 102,
          platformFee: 10,
          insuranceCharge: 0,
          gst: 36,
          estimatedDistance: 8.5,
          total: 237
        },
        insuranceRequired: false,
        insuranceValue: 0,
        codRequired: false,
        codAmount: 0,
        paymentMethod: "online",
        totalAmount: 237,
        status: "in_transit",
