import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Tag, X, Check, AlertCircle } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useToast } from "@/hooks/use-toast";
import type { TravelCoupon } from "@shared/schema";

interface TravelCouponInputProps {
  serviceType: "flight" | "bus" | "train" | "cab" | "metro" | "rental" | "hotel" | "event" | "movie";
  bookingAmount: number;
  onCouponApply: (coupon: TravelCoupon, discount: number) => void;
  onCouponRemove: () => void;
  appliedCoupon?: TravelCoupon | null;
  discount?: number;
}

export function TravelCouponInput({
  serviceType,
  bookingAmount,
  onCouponApply,
  onCouponRemove,
  appliedCoupon = null,
  discount = 0
}: TravelCouponInputProps) {
  const [couponCode, setCouponCode] = useState("");
  const [couponSheetOpen, setCouponSheetOpen] = useState(false);
  const [availableCoupons, setAvailableCoupons] = useState<TravelCoupon[]>([]);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    fetchAvailableCoupons();
  }, [serviceType]);

  useEffect(() => {
    if (appliedCoupon) {
      const minAmount = Number(appliedCoupon.minBookingAmount);
      if (bookingAmount < minAmount) {
        onCouponRemove();
        toast({
          title: "Coupon Removed",
          description: `Minimum booking amount of ₹${minAmount} required`,
          variant: "destructive"
        });
      }
    }
  }, [bookingAmount, appliedCoupon]);

  const fetchAvailableCoupons = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/travel-coupons?serviceType=${serviceType}`);
      if (response.ok) {
        const data = await response.json();
        setAvailableCoupons(data);
      }
    } catch (error) {
      console.error("Error fetching coupons:", error);
    } finally {
      setLoading(false);
    }
  };

  const calculateDiscount = (coupon: TravelCoupon, amount: number): number => {
    const discountValue = Number(coupon.discountValue);
    const maxDiscount = coupon.maxDiscount ? Number(coupon.maxDiscount) : Infinity;

    if (coupon.type === "flat") {
      return Math.min(discountValue, maxDiscount);
    } else {
      return Math.min(Math.round(amount * (discountValue / 100)), maxDiscount);
    }
  };

  const applyCoupon = (coupon: TravelCoupon) => {
    const minAmount = Number(coupon.minBookingAmount);
    if (bookingAmount >= minAmount) {
      const discountAmount = calculateDiscount(coupon, bookingAmount);
      onCouponApply(coupon, discountAmount);
      setCouponCode(coupon.code);
      setCouponSheetOpen(false);
      toast({
        title: "Coupon Applied!",
        description: `You saved ₹${discountAmount}`,
      });
    } else {
      toast({
        title: "Invalid Coupon",
        description: `Minimum booking amount of ₹${minAmount} required`,
        variant: "destructive"
      });
    }
  };

  const applyCouponByCode = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/travel-coupons/validate`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          code: couponCode,
          serviceType,
          bookingAmount
        })
      });

      if (response.ok) {
        const coupon = await response.json();
        applyCoupon(coupon);
      } else {
        const error = await response.json();
        toast({
          title: "Invalid Coupon",
          description: error.message || "Coupon code is invalid",
          variant: "destructive"
        });
      }
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to apply coupon. Please try again.",
        variant: "destructive"
      });
    } finally {
      setLoading(false);
    }
  };

  const removeCoupon = () => {
    onCouponRemove();
    setCouponCode("");
    toast({
      title: "Coupon Removed",
      description: "Coupon has been removed from your booking"
    });
  };

  return (
    <div className="border border-white/10 bg-white/5 p-4 dark:border-gray-800 dark:bg-gray-900/50">
      <h3 className="text-xs font-semibold text-white/60 dark:text-gray-400 uppercase tracking-widest mb-3">
        Apply Coupon
      </h3>

      <AnimatePresence mode="wait">
        {appliedCoupon ? (
          <motion.div 
            key="applied-coupon"
            initial={{ opacity: 0, height: 0, y: -10 }}
            animate={{ opacity: 1, height: "auto", y: 0 }}
            exit={{ opacity: 0, height: 0, y: -10 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="border border-green-500/30 bg-green-500/5 dark:bg-green-500/10 p-3 flex items-center justify-between overflow-hidden"
            data-testid="applied-coupon"
          >
            <div className="flex items-start gap-2">
              <Tag className="h-4 w-4 text-green-500 mt-0.5" strokeWidth={1} />
              <div>
                <p className="text-sm font-semibold text-white dark:text-gray-100" data-testid="text-coupon-code">
                  {appliedCoupon.code}
                </p>
                <p className="text-xs text-white/60 dark:text-gray-400 mt-0.5">
                  {appliedCoupon.description}
                </p>
                <p className="text-xs text-green-500 font-semibold mt-1" data-testid="text-discount">
                  You saved ₹{discount}
                </p>
              </div>
            </div>
            <button
              onClick={removeCoupon}
              className="text-white/60 hover:text-white dark:text-gray-400 dark:hover:text-gray-100"
              data-testid="button-remove-coupon"
            >
              <X className="h-4 w-4" strokeWidth={1} />
            </button>
          </motion.div>
        ) : (
          <>
            <div className="flex gap-2 mb-3">
              <Input
                type="text"
                placeholder="Enter coupon code"
                value={couponCode}
                onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                className="flex-1 bg-white/5 border-white/20 text-white dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 placeholder:text-white/30 dark:placeholder:text-gray-500 placeholder:text-sm placeholder:font-light focus:border-white/40 dark:focus:border-gray-600 rounded-none uppercase"
                data-testid="input-coupon-code"
                disabled={loading}
              />
              <Button
                onClick={applyCouponByCode}
                disabled={!couponCode || loading}
                className="bg-white text-black hover:bg-white/90 dark:bg-gray-100 dark:text-gray-900 dark:hover:bg-gray-200 rounded-none px-6 font-semibold disabled:opacity-50 disabled:cursor-not-allowed"
                data-testid="button-apply-coupon"
              >
                {loading ? "..." : "APPLY"}
              </Button>
            </div>
            <Sheet open={couponSheetOpen} onOpenChange={setCouponSheetOpen}>
              <SheetTrigger asChild>
                <Button
                  variant="outline"
                  className="w-full bg-white/5 border-white/20 text-white hover:bg-white/10 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 dark:hover:bg-gray-700 rounded-none"
                  data-testid="button-view-coupons"
                >
                  <Tag className="h-4 w-4 mr-2" strokeWidth={1} />
                  VIEW AVAILABLE COUPONS
                </Button>
              </SheetTrigger>
              <SheetContent 
                side="bottom" 
                className="bg-black text-white dark:bg-gray-950 dark:text-gray-100 border-white/10 dark:border-gray-800 rounded-none max-h-[80vh] overflow-y-auto"
              >
                <SheetHeader>
                  <SheetTitle className="text-white dark:text-gray-100 font-bold tracking-wide">
                    AVAILABLE COUPONS
                  </SheetTitle>
                </SheetHeader>
                <div className="mt-6 space-y-3">
                  {loading ? (
                    <div className="text-center py-8 text-white/60 dark:text-gray-400">
                      Loading coupons...
                    </div>
                  ) : availableCoupons.length === 0 ? (
                    <div className="text-center py-8">
                      <AlertCircle className="h-12 w-12 text-white/20 dark:text-gray-700 mx-auto mb-3" />
                      <p className="text-white/60 dark:text-gray-400">No coupons available</p>
                    </div>
                  ) : (
                    availableCoupons
                      .sort((a, b) => {
                        const aUsable = bookingAmount >= Number(a.minBookingAmount);
                        const bUsable = bookingAmount >= Number(b.minBookingAmount);
                        if (aUsable && !bUsable) return -1;
                        if (!aUsable && bUsable) return 1;
                        return 0;
                      })
                      .map((coupon) => {
                        const minAmount = Number(coupon.minBookingAmount);
                        const isUsable = bookingAmount >= minAmount;
                        const potentialDiscount = calculateDiscount(coupon, bookingAmount);

                        return (
                          <div
                            key={coupon.id}
                            className={`border p-4 ${
                              isUsable
                                ? "border-white/20 bg-white/5 dark:border-gray-700 dark:bg-gray-800/50 cursor-pointer hover:bg-white/10 dark:hover:bg-gray-800"
                                : "border-white/10 bg-white/5 dark:border-gray-800 dark:bg-gray-900/30 opacity-50 cursor-not-allowed"
                            }`}
                            onClick={() => isUsable && applyCoupon(coupon)}
                            data-testid={`coupon-${coupon.code}`}
                          >
                            <div className="flex items-start justify-between gap-3">
                              <div className="flex-1">
                                <div className="flex items-center gap-2 mb-2">
                                  <Tag className="h-4 w-4 text-white/60 dark:text-gray-400" strokeWidth={1} />
                                  <p className="text-sm font-bold tracking-wider">{coupon.code}</p>
                                </div>
                                <p className="text-sm font-semibold mb-1">{coupon.title}</p>
                                <p className="text-xs text-white/60 dark:text-gray-400 mb-2">
                                  {coupon.description}
                                </p>
                                {isUsable ? (
                                  <p className="text-xs text-green-500 font-semibold">
                                    You will save ₹{potentialDiscount}
                                  </p>
                                ) : (
                                  <p className="text-xs text-white/40 dark:text-gray-500">
                                    Add ₹{minAmount - bookingAmount} more to use this coupon
                                  </p>
                                )}
                              </div>
                              {isUsable && (
                                <Button
                                  size="sm"
                                  className="bg-white text-black hover:bg-white/90 dark:bg-gray-100 dark:text-gray-900 dark:hover:bg-gray-200 rounded-none text-xs font-semibold px-4"
                                  data-testid={`button-apply-${coupon.code}`}
                                >
                                  APPLY
                                </Button>
                              )}
                            </div>
                          </div>
                        );
                      })
                  )}
                </div>
              </SheetContent>
            </Sheet>
          </>
        )}
      </AnimatePresence>
    </div>
  );
}

client/src/components/booking/coupon-sel.content:
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { Ticket, Tag, Check, X, Percent, Gift, AlertCircle } from "lucide-react";

interface Coupon {
  id: string;
  code: string;
  title: string;
  description: string;
  type: "discount" | "cashback" | "free_service" | "offer";
  value: number;
  valueType: "percentage" | "fixed" | "points";
  minAmount: number;
  maxDiscount?: number;
  category: "bills" | "travel" | "investments" | "shopping" | "food" | "all";
  merchantName: string;
  validFrom: string;
  validUntil: string;
  isUsed: boolean;
  eligibleOn: string[];
  isActive: boolean;
}

interface CouponSelectorProps {
  bookingAmount: number;
  category?: string;
  appliedCoupon: Coupon | null;
  onApplyCoupon: (coupon: Coupon | null) => void;
  className?: string;
}

const mockAvailableCoupons: Coupon[] = [
  {
    id: "1",
    code: "TRAVEL100",
    title: "₹100 Off on Travel Booking",
    description: "Flat ₹100 discount on flight & bus bookings",
    type: "discount",
    value: 100,
    valueType: "fixed",
    minAmount: 1000,
    category: "travel",
    merchantName: "InCred Travel",
    validFrom: "2024-11-01",
    validUntil: "2024-12-31",
    isUsed: false,
    eligibleOn: ["Flights", "Bus", "Train", "Metro", "Hotel", "Rental"],
    isActive: true,
  },
  {
    id: "2",
    code: "TRAVEL20",
    title: "20% Off up to ₹200",
    description: "Get 20% discount on your booking",
    type: "discount",
    value: 20,
    valueType: "percentage",
    minAmount: 500,
    maxDiscount: 200,
    category: "travel",
    merchantName: "InCred",
    validFrom: "2024-11-01",
    validUntil: "2024-12-31",
    isUsed: false,
    eligibleOn: ["Flights", "Bus", "Train", "Metro", "Hotel", "Rental", "Movie", "Event"],
    isActive: true,
  },
  {
    id: "3",
    code: "FIRST50",
    title: "₹50 Off on First Booking",
    description: "First time user discount",
    type: "discount",
    value: 50,
    valueType: "fixed",
    minAmount: 200,
    category: "all",
    merchantName: "InCred",
    validFrom: "2024-01-01",
    validUntil: "2024-12-31",
    isUsed: false,
    eligibleOn: ["Flights", "Bus", "Train", "Metro", "Hotel", "Rental", "Movie", "Event", "Cab"],
    isActive: true,
  },
  {
    id: "4",
    code: "MOVIE30",
    title: "30% Off on Movie Tickets",
    description: "Get 30% off on movie bookings",
    type: "discount",
    value: 30,
    valueType: "percentage",
    minAmount: 300,
    maxDiscount: 150,
    category: "travel",
    merchantName: "PVR",
    validFrom: "2024-11-01",
    validUntil: "2024-12-31",
    isUsed: false,
    eligibleOn: ["Movie"],
    isActive: true,
  },
];

export function CouponSelector({ 
  bookingAmount, 
  category = "all",
  appliedCoupon, 
  onApplyCoupon,
  className 
}: CouponSelectorProps) {
  const { toast } = useToast();
  const [couponCode, setCouponCode] = useState("");
  const [showCouponDialog, setShowCouponDialog] = useState(false);
  const [selectedCouponId, setSelectedCouponId] = useState<string | null>(appliedCoupon?.id || null);

  const calculateDiscount = (coupon: Coupon): number => {
    if (coupon.valueType === "percentage") {
      const discount = (bookingAmount * coupon.value) / 100;
      return coupon.maxDiscount ? Math.min(discount, coupon.maxDiscount) : discount;
    }
    return coupon.value;
  };

  const isCouponValid = (coupon: Coupon): { valid: boolean; reason?: string } => {
    if (!coupon.isActive) {
      return { valid: false, reason: "This coupon has expired" };
    }
    if (coupon.isUsed) {
      return { valid: false, reason: "This coupon has already been used" };
    }
    if (bookingAmount < coupon.minAmount) {
      return { valid: false, reason: `Minimum booking amount ₹${coupon.minAmount} required` };
    }
    return { valid: true };
  };

  const handleApplyCouponCode = () => {
    if (!couponCode.trim()) {
      toast({
        title: "Coupon Code Required",
        description: "Please enter a coupon code",
        variant: "destructive",
      });
      return;
    }

    const coupon = mockAvailableCoupons.find(
      c => c.code.toLowerCase() === couponCode.toLowerCase()
    );

    if (!coupon) {
      toast({
        title: "Invalid Coupon",
        description: "This coupon code is not valid",
        variant: "destructive",
      });
      return;
    }

    const validation = isCouponValid(coupon);
    if (!validation.valid) {
      toast({
        title: "Cannot Apply Coupon",
        description: validation.reason,
        variant: "destructive",
      });
      return;
    }

    onApplyCoupon(coupon);
    toast({
      title: "Coupon Applied!",
      description: `You saved ₹${calculateDiscount(coupon).toFixed(0)}`,
    });
    setCouponCode("");
  };

  const handleSelectFromDialog = () => {
    const coupon = mockAvailableCoupons.find(c => c.id === selectedCouponId);
    if (!coupon) return;

    const validation = isCouponValid(coupon);
    if (!validation.valid) {
      toast({
        title: "Cannot Apply Coupon",
        description: validation.reason,
        variant: "destructive",
      });
      return;
    }

    onApplyCoupon(coupon);
    setShowCouponDialog(false);
    toast({
      title: "Coupon Applied!",
      description: `You saved ₹${calculateDiscount(coupon).toFixed(0)}`,
    });
  };

  const handleRemoveCoupon = () => {
    onApplyCoupon(null);
    setSelectedCouponId(null);
    toast({
      title: "Coupon Removed",
      description: "Coupon has been removed from your booking",
    });
  };

  const availableCoupons = mockAvailableCoupons.filter(coupon => {
    const validation = isCouponValid(coupon);
    return validation.valid;
  });

  return (
    <div className={cn("space-y-4", className)}>
      <div className="border border-white/20 bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-xl p-6">
        <h3 className="text-lg font-light tracking-wider mb-6 text-white flex items-center gap-2">
          <Tag className="h-5 w-5" />
          Apply Coupon
        </h3>

        {appliedCoupon ? (
          <div className="space-y-4">
            <div className="border border-green-500/30 bg-green-500/10 p-4">
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <Badge className="bg-green-500/20 text-green-400 border-green-500/30 rounded-none font-mono text-sm">
                      {appliedCoupon.code}
                    </Badge>
                    <Check className="h-4 w-4 text-green-400" />
                  </div>
                  <p className="text-white font-light mb-1">{appliedCoupon.title}</p>
                  <p className="text-xs text-white/60">{appliedCoupon.description}</p>
                  <div className="mt-3 flex items-center gap-2">
                    <Gift className="h-4 w-4 text-green-400" />
                    <span className="text-green-400 font-light">
                      You saved ₹{calculateDiscount(appliedCoupon).toFixed(0)}
                    </span>
                  </div>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={handleRemoveCoupon}
                  className="text-white/60 hover:text-white hover:bg-white/10 p-2"
                  data-testid="button-remove-coupon"
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex gap-2">
              <Input
                value={couponCode}
                onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                placeholder="Enter coupon code"
                className="bg-transparent border-b-2 border-white/20 rounded-none text-white h-12 uppercase font-mono focus:border-white"
                data-testid="input-coupon-code"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleApplyCouponCode();
                  }
                }}
              />
              <Button
                onClick={handleApplyCouponCode}
                className="bg-white text-black hover:bg-white/90 rounded-none px-6 h-12"
                data-testid="button-apply-coupon"
              >
                APPLY
              </Button>
            </div>

            {availableCoupons.length > 0 && (
              <div className="pt-2">
                <Dialog open={showCouponDialog} onOpenChange={setShowCouponDialog}>
                  <DialogTrigger asChild>
                    <Button
                      variant="ghost"
                      className="text-white/80 hover:text-white hover:bg-white/10 p-0 h-auto font-light"
                      data-testid="button-view-coupons"
                    >
                      <Ticket className="h-4 w-4 mr-2" />
                      View Available Coupons ({availableCoupons.length})
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="bg-black border-white/20 text-white max-w-2xl max-h-[80vh] overflow-y-auto">
                    <DialogHeader>
                      <DialogTitle className="text-white font-light text-xl">Available Coupons</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-3 mt-4">
                      <RadioGroup value={selectedCouponId || ""} onValueChange={setSelectedCouponId}>
                        {availableCoupons.map((coupon) => {
                          const discount = calculateDiscount(coupon);
                          return (
                            <div
                              key={coupon.id}
                              className={cn(
                                "border p-4 cursor-pointer transition-all",
                                selectedCouponId === coupon.id
                                  ? "bg-white/10 border-white"
                                  : "bg-white/5 border-white/20 hover:border-white/40"
                              )}
                              onClick={() => setSelectedCouponId(coupon.id)}
                              data-testid={`coupon-option-${coupon.code}`}
                            >
                              <div className="flex items-start gap-3">
                                <RadioGroupItem
                                  value={coupon.id}
                                  id={coupon.id}
                                  className="border-white/40 text-white mt-1"
                                />
                                <div className="flex-1">
                                  <div className="flex items-center justify-between mb-2">
                                    <Badge className="bg-white/10 text-white border-white/20 rounded-none font-mono">
                                      {coupon.code}
                                    </Badge>
                                    <span className="text-green-400 font-light flex items-center gap-1">
                                      <Percent className="h-3 w-3" />
                                      Save ₹{discount.toFixed(0)}
                                    </span>
                                  </div>
                                  <p className="text-white font-light mb-1">{coupon.title}</p>
                                  <p className="text-xs text-white/60 mb-2">{coupon.description}</p>
                                  <div className="flex items-center gap-4 text-xs text-white/50">
                                    <span>Min: ₹{coupon.minAmount}</span>
                                    {coupon.maxDiscount && <span>Max discount: ₹{coupon.maxDiscount}</span>}
                                    <span>Valid till: {new Date(coupon.validUntil).toLocaleDateString()}</span>
                                  </div>
                                </div>
                              </div>
                            </div>
                          );
                        })}
                      </RadioGroup>
                    </div>
                    <div className="mt-6 flex gap-3">
                      <Button
                        variant="outline"
                        onClick={() => setShowCouponDialog(false)}
                        className="flex-1 border-white/20 text-white hover:bg-white/10 rounded-none"
                        data-testid="button-cancel-coupon"
                      >
                        Cancel
                      </Button>
                      <Button
                        onClick={handleSelectFromDialog}
                        disabled={!selectedCouponId}
                        className="flex-1 bg-white text-black hover:bg-white/90 rounded-none"
                        data-testid="button-select-coupon"
                      >
                        Apply Coupon
                      </Button>
                    </div>
                  </DialogContent>
                </Dialog>
              </div>
            )}
          </div>
        )}

        {!appliedCoupon && availableCoupons.length === 0 && (
          <div className="p-4 bg-white/5 border border-white/10 flex items-start gap-3">
            <AlertCircle className="h-5 w-5 text-white/40 mt-0.5" />
            <div>
              <p className="text-white/60 text-sm font-light">No coupons available</p>
              <p className="text-white/40 text-xs mt-1">
                Minimum booking amount of ₹{Math.min(...mockAvailableCoupons.map(c => c.minAmount))} required
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

client/src/pages/coupex.tsx.content:
import { useState, useEffect, useRef } from "react";
import { useAuth } from "@/hooks/use-auth";
import { useLocation } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { format, differenceInDays } from "date-fns";
import { getBrandImage } from "@/lib/brand-images";
import {
  ArrowLeft,
  Plus,
  ShoppingBag,
  Repeat,
  Clock,
  Tag,
  Eye,
  ChevronLeft,
  ChevronRight,
  Calendar,
  TrendingUp,
  Filter,
  Info,
  Search,
  List,
  Sparkles
} from "lucide-react";
import { getValueScoreBadge } from "@shared/coupon-value-calculator";

interface CouponData {
  code: string;
  title: string;
  brand: string;
  category: string;
  type: string;
  value: number | string;
  valueType: string;
  description?: string;
  images?: string[];
  expiryDate: string;
  minAmount?: number | string | null;
  maxDiscount?: number | string | null;
  termsConditions?: string;
  valueScore: number | string;
}

interface Listing {
  id: string;
  userId: string;
  coupons: CouponData[];
  totalCouponCount: number;
  totalFaceValue?: string;
  primaryCategory: string;
  couponCategory?: string;
  listingNote?: string;
  listingType: string;
  sellingPrice?: string;
  tradePreference?: string;
  tradeNote?: string;
  status: string;
  views: number;
  createdAt: string;
}

export default function CoupEx() {
  const { user, isAuthenticated } = useAuth();
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate("/");
    }
  }, [isAuthenticated, navigate]);

  const { data: marketplaceListings = [] } = useQuery<Listing[]>({
    queryKey: ["/api/coupex/listings", { category: categoryFilter !== "all" ? categoryFilter : undefined, status: "active" }],
  });

  const filteredListings = marketplaceListings.filter(listing => {
    if (searchTerm) {
      const search = searchTerm.toLowerCase();
      return listing.coupons.some(coupon => 
        coupon.title.toLowerCase().includes(search) ||
        coupon.brand.toLowerCase().includes(search) ||
        coupon.description?.toLowerCase().includes(search)
      ) || listing.listingNote?.toLowerCase().includes(search);
    }
    return true;
  });

  const formatDate = (dateString: string) => {
    return format(new Date(dateString), "dd MMM yyyy");
  };

  const getDaysUntilExpiry = (dateString: string) => {
    const days = differenceInDays(new Date(dateString), new Date());
    return days;
  };

  const isExpiringSoon = (dateString: string) => {
    const days = getDaysUntilExpiry(dateString);
    return days <= 7 && days > 0;
  };

  const scrollLeft = () => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollBy({ left: -300, behavior: 'smooth' });
    }
  };

  const scrollRight = () => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollBy({ left: 300, behavior: 'smooth' });
    }
  };

  const categories = [
    { id: "all", label: "All", icon: Tag },
    { id: "combo", label: "Combo", icon: Tag },
    { id: "food", label: "Food", icon: Tag },
    { id: "travel", label: "Travel", icon: Tag },
    { id: "shopping", label: "Shopping", icon: ShoppingBag },
    { id: "bills", label: "Bills", icon: Tag },
    { id: "medical", label: "Medical", icon: Tag },
    { id: "fitness", label: "Fitness", icon: Tag },
    { id: "education", label: "Education", icon: Tag },
    { id: "entertainment", label: "Entertainment", icon: Tag },
  ];

  return (
    <div className="min-h-screen bg-black text-white pb-20">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <button
            onClick={() => navigate("/pro-tools")}
            className="text-white hover:text-white/80"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" strokeWidth={1} />
          </button>
          <div className="text-center">
            <h1 className="text-base font-bold tracking-wider">COUPEX</h1>
            <p className="text-[10px] text-white/50 uppercase tracking-widest font-light">Coupon Marketplace</p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={() => navigate("/coupex/info")}
              className="text-white hover:text-white/80"
              data-testid="button-header-info"
            >
              <Info className="h-5 w-5" strokeWidth={1} />
            </button>
            <button
              onClick={() => navigate("/coupex/my-listings")}
              className="text-white hover:text-white/80"
              data-testid="button-header-my-listings"
            >
              <List className="h-5 w-5" strokeWidth={1} />
            </button>
            <button
              onClick={() => navigate("/coupex/new-listing")}
              className="text-white hover:text-white/80"
              data-testid="button-header-new-listing"
            >
              <Plus className="h-5 w-5" strokeWidth={1} />
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="pt-20 pb-6">
        {/* Search & Filter Section */}
        <div className="px-4 mb-6 space-y-4">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 h-4 w-4 text-white/40" />
            <Input
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Search coupons..."
              className="bg-transparent border-0 border-b-2 border-white/20 text-white pl-11 rounded-none h-12 focus:border-white placeholder:text-white/30"
              data-testid="input-search"
            />
          </div>

          {/* Category Filter */}
          <div className="flex gap-2 overflow-x-auto scrollbar-hide">
            {categories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setCategoryFilter(cat.id)}
                className={`shrink-0 px-4 py-2 text-xs font-semibold tracking-wider whitespace-nowrap transition-colors border ${
                  categoryFilter === cat.id
                    ? "bg-white text-black border-white"
                    : "bg-transparent text-white/70 border-white/20 hover:border-white/40"
                }`}
                data-testid={`button-category-${cat.id}`}
              >
                {cat.label.toUpperCase()}
              </button>
            ))}
          </div>
        </div>

        {/* Featured Coupons Section */}
        <div className="px-4 py-3 relative">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-sm font-bold tracking-wider uppercase">Featured Coupons</h2>
            <div className="flex gap-2">
              <button
                onClick={scrollLeft}
                className="border border-white/20 bg-white/5 p-2 hover:bg-white/10 transition-colors"
                data-testid="button-scroll-left"
              >
                <ChevronLeft className="h-4 w-4" strokeWidth={1} />
              </button>
              <button
                onClick={scrollRight}
                className="border border-white/20 bg-white/5 p-2 hover:bg-white/10 transition-colors"
                data-testid="button-scroll-right"
              >
                <ChevronRight className="h-4 w-4" strokeWidth={1} />
              </button>
            </div>
          </div>

          <div
            ref={scrollContainerRef}
            className="flex gap-3 overflow-x-auto scrollbar-hide scroll-smooth"
          >
            {filteredListings.slice(0, 6).map((listing) => {
              if (!listing.coupons || listing.coupons.length === 0) return null;
              const daysLeft = getDaysUntilExpiry(listing.coupons[0].expiryDate);
              const expiring = isExpiringSoon(listing.coupons[0].expiryDate);
              const valueScore = listing.coupons[0].valueScore ? parseFloat(listing.coupons[0].valueScore.toString()) : 5.0;
              const valueBadge = getValueScoreBadge(valueScore);

              return (
                <div
                  key={listing.id}
                  onClick={() => navigate(`/coupex/listing/${listing.id}`)}
                  className="shrink-0 w-72 border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent backdrop-blur-xl cursor-pointer hover:border-white/20 transition-all"
                  data-testid={`card-featured-${listing.id}`}
                >
                  {/* Coupon Image */}
                  <div className="aspect-video bg-white/5 overflow-hidden flex items-center justify-center relative">
                    <img
                      src={getBrandImage(listing.coupons[0]?.brand || "", listing.coupons[0]?.category || "") || ""}
                      alt={listing.coupons[0]?.title || ""}
                      className="w-full h-full object-cover"
                    />
                    <div className="absolute top-2 right-2">
                      <Badge className={`rounded-none text-[10px] ${valueBadge.bgClass} ${valueBadge.textClass} ${valueBadge.borderClass}`}>
                        <Sparkles className="h-3 w-3 mr-1" />
                        {valueScore.toFixed(1)}
                      </Badge>
                    </div>
                  </div>

                  <div className="p-4 space-y-3">
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2 flex-wrap">
                          <Badge className="bg-white/10 text-white border-white/10 rounded-none text-[10px] uppercase">
                            {listing.listingType}
                          </Badge>
                          {listing.totalCouponCount > 1 && (
                            <Badge className="bg-white text-black border-white rounded-none text-[10px] font-bold">
                              COMBO × {listing.totalCouponCount}
                            </Badge>
                          )}
                          {listing.totalCouponCount > 1 && listing.totalCouponCount <= 5 && (
                            <span className="text-[8px] text-green-400">MAX 5 CARDS</span>
                          )}
                        </div>
                        <h3 className="font-light text-white text-base tracking-wide line-clamp-2">{listing.coupons[0]?.title || ""}</h3>
                        <p className="text-xs text-white/50 uppercase tracking-widest mt-1">{listing.coupons[0]?.brand || ""}</p>
                      </div>
                      <div className="text-right">
                        <div className="text-xl font-light text-white">
                          {listing.coupons[0]?.valueType === "percentage" 
                            ? `${listing.coupons[0]?.value}%` 
                            : `₹${listing.coupons[0]?.value}`}
                        </div>
                      </div>
                    </div>

                    <div className="border-t border-white/10 pt-3 space-y-2">
                      <div className="flex items-center justify-between text-xs">
                        <div className="flex items-center gap-2 text-white/60">
                          <Calendar className="h-3 w-3" strokeWidth={1} />
                          <span className={expiring ? "text-red-400" : ""}>
                            {daysLeft > 0 ? `${daysLeft}d left` : "Expired"}
                          </span>
                        </div>
                        <div className="flex items-center gap-2 text-white/60">
                          <Eye className="h-3 w-3" strokeWidth={1} />
                          <span>{listing.views}</span>
                        </div>
                      </div>

                      {listing.listingType === "sell" && listing.sellingPrice && (
                        <div className="flex items-center justify-between bg-white/5 p-2">
                          <span className="text-xs text-white/60 uppercase tracking-widest">Price</span>
                          <span className="text-base font-light text-white">₹{listing.sellingPrice}</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* All Listings Grid */}
        <div className="px-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-sm font-bold tracking-wider uppercase">All Coupons</h2>
            <p className="text-xs text-white/50">{filteredListings.length} listings</p>
          </div>

          <div className="space-y-3">
            {filteredListings.length === 0 ? (
              <div className="border border-white/10 p-12 text-center" data-testid="empty-listings">
                <Tag className="h-12 w-12 text-white/20 mx-auto mb-3" strokeWidth={1} />
                <p className="text-white/50 text-sm">No coupons found</p>
              </div>
            ) : (
              filteredListings.map((listing) => {
                if (!listing.coupons || listing.coupons.length === 0) return null;
                const daysLeft = getDaysUntilExpiry(listing.coupons[0].expiryDate);
                const expiring = isExpiringSoon(listing.coupons[0].expiryDate);
                const valueScore = listing.coupons[0].valueScore ? parseFloat(listing.coupons[0].valueScore.toString()) : 5.0;
                const valueBadge = getValueScoreBadge(valueScore);

                return (
                  <div
                    key={listing.id}
                    onClick={() => navigate(`/coupex/listing/${listing.id}`)}
                    className="border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent backdrop-blur-xl p-4 hover:border-white/20 transition-all cursor-pointer"
                    data-testid={`card-listing-${listing.id}`}
                  >
                    <div className="flex gap-4">
                      {/* Brand Image and Score */}
                      <div className="w-24 shrink-0 space-y-2">
                        <div className="w-24 h-24 bg-white/5 overflow-hidden flex items-center justify-center border border-white/10 relative">
                          <img
                            src={getBrandImage(listing.coupons[0]?.brand || "", listing.coupons[0]?.category || "") || ""}
                            alt={listing.coupons[0]?.title || ""}
                            className="w-full h-full object-cover"
                          />
                          {listing.totalCouponCount > 1 && (
                            <div className="absolute top-1 right-1 bg-green-700 text-white text-[8px] font-bold px-1.5 py-0.5 rounded-sm">
                              ×{listing.totalCouponCount}
                            </div>
                          )}
                        </div>
                        <Badge className={`rounded-none text-sm font-semibold ${valueBadge.bgClass} ${valueBadge.textClass} ${valueBadge.borderClass} w-full justify-center`}>
                          <Sparkles className="h-4 w-4 mr-1" />
                          {valueScore.toFixed(1)}
                        </Badge>
                      </div>

                      {/* Details */}
                      <div className="flex-1 space-y-3">
                        <div className="flex items-start justify-between gap-2">
                          <div className="flex-1 space-y-2">
                            <div className="flex items-center gap-2 flex-wrap">
                              <Badge className="bg-white/10 text-white border-white/10 rounded-none text-[10px] uppercase">
                                {listing.listingType}
                              </Badge>
                              {listing.totalCouponCount > 1 && (
                                <Badge className="bg-white text-black border-white rounded-none text-[10px] font-bold">
                                  COMBO × {listing.totalCouponCount}
                                </Badge>
                              )}
                              <Badge className="bg-white/10 text-white border-white/10 rounded-none text-[10px] uppercase">
                                {listing.couponCategory || listing.coupons[0]?.category}
                              </Badge>
                              {expiring && (
                                <Badge className="bg-red-500/20 text-red-400 border-red-500/20 rounded-none text-[10px] uppercase">
                                  Expiring Soon
                                </Badge>
                              )}
                            </div>
                            <h4 className="font-light text-white text-base tracking-wide">{listing.coupons[0]?.title || ""}</h4>
                            <p className="text-xs text-white/50 uppercase tracking-widest">{listing.coupons[0]?.brand || ""}</p>
                          </div>
                          <div className="text-right">
                            <div className="text-xl font-light text-white">
                              {listing.coupons[0]?.valueType === "percentage" 
                                ? `${listing.coupons[0]?.value}%` 
                                : `₹${listing.coupons[0]?.value}`}
                            </div>
                            <p className="text-[10px] text-white/50 uppercase tracking-widest">
                              {listing.coupons[0]?.type.replace("_", " ")}
                            </p>
                          </div>
                        </div>

                        <div className="border-t border-white/10 pt-3 space-y-2">
                          <div className="grid grid-cols-2 gap-2 text-xs">
                            <div className="flex items-center gap-2 text-white/60">
                              <Calendar className="h-3 w-3" strokeWidth={1} />
                              <span className={expiring ? "text-red-400" : ""}>
                                Expires: {formatDate(listing.coupons[0].expiryDate)}
                              </span>
                            </div>
                            <div className="flex items-center gap-2 text-white/60">
                              <Eye className="h-3 w-3" strokeWidth={1} />
                              <span>{listing.views} views</span>
                            </div>
                          </div>

                          {listing.listingType === "sell" && listing.sellingPrice && (
                            <div className="flex items-center justify-between bg-white/5 p-2">
                              <span className="text-xs text-white/60 uppercase tracking-widest">Price</span>
                              <span className="text-base font-light text-white">₹{listing.sellingPrice}</span>
                            </div>
                          )}

                          {listing.listingType === "trade" && listing.tradePreference && (
                            <div className="bg-white/5 p-2">
                              <span className="text-xs text-white/60 uppercase tracking-widest block mb-1">Looking For</span>
                              <p className="text-xs text-white line-clamp-2">{listing.tradePreference}</p>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

