        couponBrand: "Amazon",
        couponCategory: "Books",
        couponValue: "350",
        couponValueType: "fixed",
        expiryDate: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
        listingType: "sell",
        sellingPrice: "350",
        status: "sold",
        views: 234,
        createdAt: new Date(Date.now() - 25 * 24 * 60 * 60 * 1000).toISOString()
      }
    }
  ];

  // Fetch trade offers (sent and received)
  const { data: tradeOffersData } = useQuery<{ sent: TradeOffer[]; received: TradeOffer[] }>({
