          >
            <ArrowLeft className="h-5 w-5" strokeWidth={1} />
          </button>
          <h1 className="text-sm font-light tracking-wider">LISTINGS</h1>
          <button
            onClick={() => navigate("/coupex/new-listing")}
            className="text-white hover:text-white/80"
            data-testid="button-new-listing"
          >
            <Plus className="h-5 w-5" strokeWidth={1} />
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="pt-20 px-4">
        <Tabs defaultValue="my-listings" className="w-full">
          <TabsList className="grid w-full grid-cols-3 bg-white/5 border border-white/10 rounded-none mb-6">
            <TabsTrigger 
              value="my-listings" 
              className="data-[state=active]:bg-white data-[state=active]:text-black rounded-none text-xs"
              data-testid="tab-my-listings"
            >
              My Listings
            </TabsTrigger>
            <TabsTrigger 
              value="purchased" 
              className="data-[state=active]:bg-white data-[state=active]:text-black rounded-none text-xs"
              data-testid="tab-purchased"
            >
              Purchased
            </TabsTrigger>
            <TabsTrigger 
              value="offers" 
              className="data-[state=active]:bg-white data-[state=active]:text-black rounded-none text-xs"
              data-testid="tab-offers"
            >
              Offers
            </TabsTrigger>
          </TabsList>

          {/* My Listings Tab */}
          <TabsContent value="my-listings" className="mt-0">
            {myListings.length === 0 ? (
              <div className="border border-white/10 p-12 text-center mt-8" data-testid="empty-listings">
                <Tag className="h-16 w-16 text-white/20 mx-auto mb-4" strokeWidth={1} />
                <p className="text-white/50 text-sm mb-4">You haven't listed any coupons yet</p>
                <Button
                  onClick={() => navigate("/coupex/new-listing")}
                  className="bg-white text-black hover:bg-white/90 rounded-none"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Create First Listing
                </Button>
              </div>
            ) : (
              <>
                <p className="text-xs text-white/50 mb-4 uppercase tracking-widest">
                  {myListings.length} {myListings.length === 1 ? "listing" : "listings"}
                </p>
                <div className="space-y-3">
                  {myListings.map((listing) => {
                    const daysLeft = getDaysUntilExpiry(listing.expiryDate);
                    const expiring = isExpiringSoon(listing.expiryDate);
                    const valueScore = listing.valueScore ? parseFloat(listing.valueScore) : 5.0;
                    const valueBadge = getValueScoreBadge(valueScore);

                    return (
                      <div
                        key={listing.id}
                        className="border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent backdrop-blur-xl p-4 hover:border-white/20 transition-all cursor-pointer"
                        onClick={() => navigate(`/coupex/listing/${listing.id}`)}
                        data-testid={`card-listing-${listing.id}`}
                      >
                        <div className="space-y-3">
                          {/* Card Header */}
                          <div className="flex items-start justify-between">
                            <div className="flex items-start gap-3">
                              <div className="w-9 h-9 border border-white/20 flex items-center justify-center shrink-0">
                                <Tag className="h-4 w-4 text-white/60" />
                              </div>
                              <div className="space-y-1">
                                <h4 className="font-light text-white text-sm tracking-wide">{listing.couponTitle}</h4>
                                <p className="text-[10px] text-white/50 tracking-widest uppercase">{listing.couponBrand}</p>
                                <div className="flex items-center gap-2">
                                  <Badge className={`rounded-none text-[9px] uppercase ${
                                    listing.status === "active" ? "bg-green-500/20 text-green-400 border-green-500/20" :
                                    listing.status === "sold" ? "bg-white/20 text-white border-white/20" :
                                    "bg-white/10 text-white/60 border-white/10"
                                  }`}>
                                    {listing.status}
                                  </Badge>
                                  <Badge className="bg-white/10 text-white/60 border-white/10 rounded-none text-[9px] uppercase">
                                    {listing.listingType}
                                  </Badge>
                                  {expiring && listing.status === "active" && (
                                    <Badge className="bg-red-500/20 text-red-400 border-red-500/20 rounded-none text-[9px] uppercase">
                                      Expiring
                                    </Badge>
                                  )}
                                </div>
                              </div>
                            </div>
                            <div className="text-right space-y-1">
                              <p className="text-lg font-light text-white tracking-tight">
                                {listing.couponValueType === "percentage"
                                  ? `${listing.couponValue}%`
                                  : `₹${listing.couponValue}`}
                              </p>
                              <p className="text-[10px] text-white/50 uppercase tracking-widest">Value</p>
                            </div>
                          </div>

                          {/* Details Section */}
                          <div className="space-y-2 pt-2 border-t border-white/10">
                            <div className="flex justify-between text-[10px] text-white/50 uppercase tracking-widest">
                              <div className="flex items-center gap-2">
                                <Calendar className="h-3 w-3" />
                                <span className={expiring ? "text-red-400" : ""}>Exp: {formatDate(listing.expiryDate)}</span>
                              </div>
                              <div className="flex items-center gap-2">
                                <Eye className="h-3 w-3" />
                                <span>{listing.views} views</span>
                              </div>
                            </div>

                            {listing.listingType === "sell" && listing.sellingPrice && (
                              <div className="flex justify-between items-center bg-white/5 p-2">
                                <span className="text-[10px] text-white/50 uppercase tracking-widest">Selling Price</span>
                                <span className="text-sm font-light text-white">₹{listing.sellingPrice}</span>
                              </div>
                            )}

                            <div className="flex items-center gap-2 pt-1">
                              <Badge className="bg-white/10 text-white/60 border-white/10 rounded-none text-[9px]">
                                <Sparkles className="h-3 w-3 mr-1" />
                                Score: {valueScore.toFixed(1)}
                              </Badge>
                            </div>
                          </div>

                          {/* Actions */}
                          {listing.status === "active" && (
                            <div className="pt-2 border-t border-white/10">
                              <Button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setListingToDelete(listing.id);
                                }}
                                size="sm"
                                className="w-full bg-red-700 text-white hover:bg-red-800 rounded-none h-9"
                                data-testid={`button-delete-${listing.id}`}
                              >
                                <Trash2 className="h-4 w-4 mr-2" strokeWidth={1} />
                                Delete Listing
                              </Button>
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </>
            )}
          </TabsContent>

          {/* Purchased Coupons Tab */}
          <TabsContent value="purchased" className="mt-0">
            {purchasedCoupons.length === 0 ? (
              <div className="border border-white/10 p-12 text-center mt-8" data-testid="empty-purchased">
                <ShoppingBag className="h-16 w-16 text-white/20 mx-auto mb-4" strokeWidth={1} />
                <p className="text-white/50 text-sm mb-2">No purchased coupons yet</p>
                <p className="text-xs text-white/40 mb-4">Browse the marketplace to buy coupons</p>
                <Button
                  onClick={() => navigate("/coupex")}
                  className="bg-white text-black hover:bg-white/90 rounded-none"
                >
                  Browse Coupons
                </Button>
              </div>
            ) : (
              <>
                <p className="text-xs text-white/50 mb-4 uppercase tracking-widest">
                  {purchasedCoupons.length} {purchasedCoupons.length === 1 ? "coupon" : "coupons"}
                </p>
                <div className="space-y-3">
                  {purchasedCoupons.map((purchase) => {
                    const listing = purchase.listing;
                    if (!listing) return null;

                    const daysLeft = getDaysUntilExpiry(listing.expiryDate);
                    const expiring = isExpiringSoon(listing.expiryDate);
                    const isExpired = daysLeft < 0;

                    return (
                      <div
                        key={purchase.id}
                        className="border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent backdrop-blur-xl p-4"
                        data-testid={`card-purchased-${purchase.id}`}
                      >
                        <div className="space-y-3">
                          {/* Card Header */}
                          <div className="flex items-start justify-between">
                            <div className="flex items-start gap-3">
                              <div className="w-9 h-9 border border-white/20 flex items-center justify-center shrink-0">
                                <ShoppingBag className="h-4 w-4 text-white/60" />
                              </div>
                              <div className="space-y-1">
                                <h4 className="font-light text-white text-sm tracking-wide">{listing.couponTitle}</h4>
                                <p className="text-[10px] text-white/50 tracking-widest uppercase">{listing.couponBrand}</p>
                                <Badge className={`rounded-none text-[9px] uppercase ${
                                  isExpired ? "bg-red-500/20 text-red-400 border-red-500/20" :
                                  expiring ? "bg-yellow-500/20 text-yellow-400 border-yellow-500/20" :
                                  "bg-green-500/20 text-green-400 border-green-500/20"
                                }`}>
                                  {isExpired ? "Expired" : expiring ? "Expiring" : "Active"}
                                </Badge>
                              </div>
                            </div>
                            <div className="text-right space-y-1">
                              <p className="text-lg font-light text-white tracking-tight">
                                {listing.couponValueType === "percentage"
                                  ? `${listing.couponValue}%`
                                  : `₹${listing.couponValue}`}
                              </p>
                              <p className="text-[10px] text-white/50 uppercase tracking-widest">Value</p>
                            </div>
                          </div>

                          {/* Coupon Code */}
                          <div className="bg-white/10 border border-white/20 p-3 space-y-2 pt-2 border-t border-white/10">
                            <div className="flex items-center justify-between gap-3">
                              <div className="flex-1">
                                <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Coupon Code</p>
                                <p className="text-base font-mono font-light text-white tracking-wider">{purchase.revealedCode}</p>
                              </div>
                              <Button
                                onClick={() => copyToClipboard(purchase.revealedCode, purchase.id)}
                                variant="ghost"
                                size="sm"
                                className="text-white hover:text-white hover:bg-white/10 rounded-none h-9 px-3"
                                data-testid={`button-copy-${purchase.id}`}
                              >
                                {copiedCode === purchase.id ? (
                                  <Check className="h-4 w-4 text-green-400" strokeWidth={1} />
                                ) : (
                                  <Copy className="h-4 w-4" strokeWidth={1} />
                                )}
                              </Button>
                            </div>
                          </div>

                          {/* Transaction Details */}
                          <div className="space-y-2 pt-2 border-t border-white/10">
                            <div className="flex justify-between text-[10px] text-white/50 uppercase tracking-widest">
                              <div>
                                <p className="mb-1">Purchased</p>
                                <p className="text-white">{formatDate(purchase.createdAt)}</p>
                              </div>
                              <div className="text-right">
                                <p className="mb-1">Expires</p>
                                <p className={expiring || isExpired ? "text-red-400" : "text-white"}>
                                  {formatDate(listing.expiryDate)}
                                </p>
                              </div>
                            </div>

                            <div className="flex justify-between items-center bg-white/5 p-2">
                              <span className="text-[10px] text-white/50 uppercase tracking-widest">Amount Paid</span>
                              <span className="text-sm font-light text-white">₹{purchase.amount}</span>
                            </div>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </>
            )}
          </TabsContent>

          {/* Offers Tab */}
          <TabsContent value="offers" className="mt-0">
            <Tabs defaultValue="received" className="w-full">
              <TabsList className="grid w-full grid-cols-2 bg-white/5 border border-white/10 rounded-none mb-6">
                <TabsTrigger 
                  value="received" 
                  className="data-[state=active]:bg-white data-[state=active]:text-black rounded-none text-xs"
                  data-testid="tab-received-offers"
                >
                  <Inbox className="h-3 w-3 mr-1" />
                  Received
                </TabsTrigger>
                <TabsTrigger 
                  value="sent" 
                  className="data-[state=active]:bg-white data-[state=active]:text-black rounded-none text-xs"
                  data-testid="tab-sent-offers"
                >
                  <Send className="h-3 w-3 mr-1" />
                  Sent
                </TabsTrigger>
              </TabsList>

              {/* Received Offers Tab */}
              <TabsContent value="received" className="mt-0">
                {receivedOffers.length === 0 ? (
                  <div className="border border-white/10 p-12 text-center mt-8" data-testid="empty-received-offers">
                    <Inbox className="h-16 w-16 text-white/20 mx-auto mb-4" strokeWidth={1} />
                    <p className="text-white/50 text-sm mb-2">No trade offers received yet</p>
                    <p className="text-xs text-white/40">Offers from other users will appear here</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <p className="text-xs text-white/50 mb-4 uppercase tracking-widest">
                      {receivedOffers.length} {receivedOffers.length === 1 ? "offer" : "offers"}
                    </p>
                    {receivedOffers.map((offer) => (
                      <div
                        key={offer.id}
                        onClick={() => navigate(`/coupex/offer/${offer.id}`)}
                        className="border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent backdrop-blur-xl p-4 cursor-pointer hover:border-white/20 transition-colors"
                        data-testid={`card-received-offer-${offer.id}`}
                      >
                        <div className="space-y-3">
                          {/* Card Header */}
                          <div className="flex items-start justify-between">
                            <div className="flex items-start gap-3">
                              <div className="w-9 h-9 border border-white/20 flex items-center justify-center shrink-0">
                                <Inbox className="h-4 w-4 text-white/60" />
                              </div>
                              <div className="space-y-1">
                                <h4 className="font-light text-white text-sm tracking-wide">
                                  {offer.listing?.couponTitle || 'Your Listing'}
                                </h4>
                                <p className="text-[10px] text-white/50 tracking-widest uppercase">
                                  From: {offer.offererName}
                                </p>
                                <div className="flex items-center gap-2">
                                  <Badge className={`rounded-none text-[9px] uppercase ${
                                    offer.status === 'pending' ? 'bg-yellow-500/20 text-yellow-400 border-yellow-500/20' :
                                    offer.status === 'accepted' ? 'bg-green-500/20 text-green-400 border-green-500/20' :
                                    'bg-red-500/20 text-red-400 border-red-500/20'
                                  }`}>
                                    {offer.status}
                                  </Badge>
                                  <Badge className={`rounded-none text-[9px] uppercase ${
                                    offer.offerType === 'cash' ? 'bg-white/10 text-white/60 border-white/10' :
                                    'bg-white/10 text-white/60 border-white/10'
                                  }`}>
                                    {offer.offerType === 'cash' ? 'Cash Offer' : 'Trade Offer'}
                                  </Badge>
                                </div>
                              </div>
                            </div>
                            <div className="text-right space-y-1">
                              <p className="text-lg font-light text-white tracking-tight">
                                {offer.offerType === 'cash' ? `₹${offer.cashAmount}` : `₹${offer.offeredCouponValue}`}
                              </p>
                              <p className="text-[10px] text-white/50 uppercase tracking-widest">Offer</p>
                            </div>
                          </div>

                          {/* Offer Details */}
                          <div className="space-y-2 pt-2 border-t border-white/10">
                            <div className="flex justify-between text-[10px] text-white/50 uppercase tracking-widest">
                              <span>Code: {offer.listingCode}</span>
                              <span>{formatDate(offer.createdAt)}</span>
                            </div>

                            {offer.offerType === 'trade' && (
                              <div className="flex justify-between items-center bg-white/5 p-2">
                                <div>
                                  <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Offering</p>
                                  <p className="text-xs text-white">{offer.offeredCouponBrand} - {offer.offeredCouponTitle}</p>
                                </div>
                                <p className="text-xs text-white/50">Exp: {formatDate(offer.offeredCouponExpiry)}</p>
                              </div>
                            )}

                            {offer.offerNote && (
                              <div className="bg-white/5 p-2">
                                <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Note</p>
                                <p className="text-xs text-white/70">{offer.offerNote}</p>
                              </div>
                            )}

                            {offer.respondedAt && (
                              <p className="text-[10px] text-white/50 uppercase tracking-widest">
                                Responded: {formatDate(offer.respondedAt)}
                              </p>
                            )}
                          </div>

                          {/* Actions */}
                          {offer.status === 'pending' && (
                            <div className="pt-2 border-t border-white/10">
                              <p className="text-[10px] text-white/50 uppercase tracking-widest text-center">
                                Click to review and respond
                              </p>
                            </div>
                          )}
                          {offer.responseNote && (
                            <div className="pt-2 border-t border-white/10 bg-white/5 p-2">
                              <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Response</p>
                              <p className="text-xs text-white/70">{offer.responseNote}</p>
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </TabsContent>

              {/* Sent Offers Tab */}
              <TabsContent value="sent" className="mt-0">
                {sentOffers.length === 0 ? (
                  <div className="border border-white/10 p-12 text-center mt-8" data-testid="empty-sent-offers">
                    <Send className="h-16 w-16 text-white/20 mx-auto mb-4" strokeWidth={1} />
                    <p className="text-white/50 text-sm mb-2">No trade offers sent yet</p>
                    <p className="text-xs text-white/40">Offers you propose will appear here</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <p className="text-xs text-white/50 mb-4 uppercase tracking-widest">
                      {sentOffers.length} {sentOffers.length === 1 ? "offer" : "offers"}
                    </p>
                    {sentOffers.map((offer) => (
                      <div
                        key={offer.id}
                        onClick={() => navigate(`/coupex/offer/${offer.id}`)}
                        className="border border-white/10 bg-gradient-to-br from-white/5 via-transparent to-transparent backdrop-blur-xl p-4 cursor-pointer hover:border-white/20 transition-colors"
                        data-testid={`card-sent-offer-${offer.id}`}
                      >
                        <div className="space-y-3">
                          {/* Card Header */}
                          <div className="flex items-start justify-between">
                            <div className="flex items-start gap-3">
                              <div className="w-9 h-9 border border-white/20 flex items-center justify-center shrink-0">
                                <Send className="h-4 w-4 text-white/60" />
                              </div>
                              <div className="space-y-1">
                                <h4 className="font-light text-white text-sm tracking-wide">
                                  {offer.listing?.couponTitle || 'Target Listing'}
                                </h4>
                                <p className="text-[10px] text-white/50 tracking-widest uppercase">
                                  Your Offer
                                </p>
                                <div className="flex items-center gap-2">
                                  <Badge className={`rounded-none text-[9px] uppercase ${
                                    offer.status === 'pending' ? 'bg-yellow-500/20 text-yellow-400 border-yellow-500/20' :
                                    offer.status === 'accepted' ? 'bg-green-500/20 text-green-400 border-green-500/20' :
                                    'bg-red-500/20 text-red-400 border-red-500/20'
                                  }`}>
                                    {offer.status}
                                  </Badge>
                                  <Badge className={`rounded-none text-[9px] uppercase ${
                                    offer.offerType === 'cash' ? 'bg-white/10 text-white/60 border-white/10' :
                                    'bg-white/10 text-white/60 border-white/10'
                                  }`}>
                                    {offer.offerType === 'cash' ? 'Cash Offer' : 'Trade Offer'}
                                  </Badge>
                                </div>
                              </div>
                            </div>
                            <div className="text-right space-y-1">
                              <p className="text-lg font-light text-white tracking-tight">
                                {offer.offerType === 'cash' ? `₹${offer.cashAmount}` : `₹${offer.offeredCouponValue}`}
                              </p>
                              <p className="text-[10px] text-white/50 uppercase tracking-widest">Offer</p>
                            </div>
                          </div>

                          {/* Offer Details */}
                          <div className="space-y-2 pt-2 border-t border-white/10">
                            <div className="flex justify-between text-[10px] text-white/50 uppercase tracking-widest">
                              <span>Code: {offer.listingCode}</span>
                              <span>{formatDate(offer.createdAt)}</span>
                            </div>

                            {offer.offerType === 'trade' && (
                              <div className="flex justify-between items-center bg-white/5 p-2">
                                <div>
                                  <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Offering</p>
                                  <p className="text-xs text-white">{offer.offeredCouponBrand} - {offer.offeredCouponTitle}</p>
                                </div>
                                <p className="text-xs text-white/50">Exp: {formatDate(offer.offeredCouponExpiry)}</p>
                              </div>
                            )}

                            {offer.offerNote && (
                              <div className="bg-white/5 p-2">
                                <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Note</p>
                                <p className="text-xs text-white/70">{offer.offerNote}</p>
                              </div>
                            )}

                            {offer.respondedAt && (
                              <p className="text-[10px] text-white/50 uppercase tracking-widest">
                                {offer.status === 'accepted' && 'Accepted: '}
                                {offer.status === 'rejected' && 'Rejected: '}
                                {formatDate(offer.respondedAt)}
                              </p>
                            )}

                            {offer.responseNote && (
                              <div className="bg-white/5 p-2">
                                <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">
                                  Seller's Response
                                </p>
                                <p className="text-xs text-white/70">{offer.responseNote}</p>
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </TabsContent>
            </Tabs>
          </TabsContent>
        </Tabs>
      </div>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={listingToDelete !== null} onOpenChange={() => setListingToDelete(null)}>
        <AlertDialogContent className="bg-black border border-white/20 text-white">
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertCircle className="h-5 w-5 text-red-400" strokeWidth={1} />
              Cancel Listing
            </AlertDialogTitle>
            <AlertDialogDescription className="text-white/60">
              Are you sure you want to cancel this listing? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="bg-transparent border-white/20 text-white hover:bg-white/10 rounded-none">
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => listingToDelete && deleteListingMutation.mutate(listingToDelete)}
              className="bg-red-500 text-white hover:bg-red-600 rounded-none"
            >
              Delete Listing
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

