          </div>

          {showQr ? (
            <div className="space-y-4">
              <div className="bg-white p-6 mx-auto w-fit rounded-lg">
                <QRCode
                  value={upiPaymentString}
                  size={200}
                  level="H"
                  data-testid="qr-code"
                />
