import { useState, useEffect, useRef } from "react";
import { useAuth } from "@/hooks/use-auth";
import { useLocation, useRoute } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  ArrowLeft,
  ShoppingBag,
  Repeat,
  Sparkles,
  CheckCircle,
  Loader2,
  FileText,
  TrendingDown,
  Package,
  AlertCircle,
} from "lucide-react";

interface Listing {
  id: string;
  userId: string;
  couponCode: string;
  couponTitle: string;
  couponBrand: string;
  couponCategory: string;
  couponType: string;
  couponValue: string;
  couponValueType: string;
  couponDescription?: string;
  expiryDate: string;
  minAmount?: string;
  maxDiscount?: string;
  termsConditions?: string;
  listingType: string;
  sellingPrice?: string;
  tradePreference?: string;
  tradeNote?: string;
  status: string;
  valueScore?: string;
}

interface BookingStage {
  id: string;
  title: string;
  shortTitle: string;
  icon: React.ComponentType<{ className?: string }>;
  description: string;
}

interface TradeCard {
  id: string;
  category: string;
  minValue: number;
}

const LISTING_STAGES: BookingStage[] = [
  { id: 'type', title: 'Listing Type', shortTitle: 'Type', icon: ShoppingBag, description: 'Cash In or Trade' },
  { id: 'buy-details', title: 'Update Details', shortTitle: 'Details', icon: Sparkles, description: 'Update your terms' },
  { id: 'review', title: 'Review & Update', shortTitle: 'Review', icon: CheckCircle, description: 'Confirm changes' },
];

const categories = [
  { id: "any", label: "Any Category" },
  { id: "food", label: "Food & Dining" },
  { id: "travel", label: "Travel" },
  { id: "shopping", label: "Shopping" },
  { id: "bills", label: "Bills & Recharge" },
  { id: "medical", label: "Medical" },
  { id: "fitness", label: "Fitness" },
  { id: "education", label: "Education" },
  { id: "entertainment", label: "Entertainment" },
];

export default function CoupExEditListing() {
  const { user, isAuthenticated } = useAuth();
  const [, navigate] = useLocation();
  const [, params] = useRoute("/coupex/edit-listing/:id");
  const { toast } = useToast();
  const scrollableContentRef = useRef<HTMLDivElement>(null);

  const listingId = params?.id || "";

  const [currentStageIndex, setCurrentStageIndex] = useState(0);
  const [completedStages, setCompletedStages] = useState<number[]>([]);
  const [showConfirmDialog, setShowConfirmDialog] = useState(false);

  // Form states
  const [listingType, setListingType] = useState<"sell" | "trade">("sell");
  const [additionalNote, setAdditionalNote] = useState("");
  const [sellingPrice, setSellingPrice] = useState("");
  const [enableAutoDecrease, setEnableAutoDecrease] = useState(false);
  const [offerStartDays, setOfferStartDays] = useState("7");
  const [dailyDecreasePercent, setDailyDecreasePercent] = useState("2");
  const [tradeCards, setTradeCards] = useState<TradeCard[]>([
    { id: "1", category: "", minValue: 0 }
  ]);

  const currentStage = LISTING_STAGES[currentStageIndex];
  const progressPercentage = ((currentStageIndex + 1) / LISTING_STAGES.length) * 100;

  useEffect(() => {
    if (!isAuthenticated) {
      navigate("/");
    }
  }, [isAuthenticated, navigate]);

  const { data: listing, isLoading } = useQuery<Listing>({
    queryKey: ["/api/coupex/listings", listingId],
    enabled: !!listingId,
  });

  useEffect(() => {
    if (listing) {
      if (listing.userId !== user?.id) {
        toast({
          title: "Unauthorized",
          description: "You can only edit your own listings",
          variant: "destructive",
        });
        navigate("/coupex");
        return;
      }

      // Pre-fill form with existing data
      setListingType(listing.listingType as "sell" | "trade");
      setAdditionalNote(listing.couponDescription || listing.tradeNote || "");
      setSellingPrice(listing.sellingPrice || "");

      if (listing.tradePreference) {
        const preferences = listing.tradePreference.split(", ").filter(Boolean);
        const cards = preferences.map((pref, index) => ({
          id: (index + 1).toString(),
          category: pref.toLowerCase(),
          minValue: 100,
        }));
        setTradeCards(cards.length > 0 ? cards : [{ id: "1", category: "", minValue: 0 }]);
      }
    }
  }, [listing, user, navigate, toast]);

  useEffect(() => {
    window.scrollTo(0, 0);
    if (scrollableContentRef.current) {
      scrollableContentRef.current.scrollTop = 0;
    }
  }, [currentStageIndex]);

  const updateListingMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest("PATCH", `/api/coupex/listings/${listingId}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/coupex/my-listings"] });
      queryClient.invalidateQueries({ queryKey: ["/api/coupex/listings"] });
      queryClient.invalidateQueries({ queryKey: ["/api/coupex/listings", listingId] });
      toast({
        title: "Success!",
        description: "Your listing has been updated successfully",
      });
      navigate("/coupex/my-listings");
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update listing",
        variant: "destructive",
      });
    },
  });

  const handleNextStage = () => {
    // Validate listing type
    if (currentStage.id === 'type') {
      if (!listingType) {
        toast({
          title: "Selection Required",
          description: "Please select a listing type",
          variant: "destructive"
        });
        return;
      }
    }

    // Validate buy details
    if (currentStage.id === 'buy-details') {
      if (listingType === 'sell' && !sellingPrice) {
        toast({
          title: "Price Required",
          description: "Please enter a selling price",
          variant: "destructive"
        });
        return;
      }
      if (listingType === 'trade') {
        const hasValidCard = tradeCards.some(card => 
          card.category && card.minValue > 0
        );
        if (!hasValidCard) {
          toast({
            title: "Trade Requirements Missing",
            description: "Please specify at least one valid card requirement",
            variant: "destructive"
          });
          return;
        }
      }
    }

    if (!completedStages.includes(currentStageIndex)) {
      setCompletedStages([...completedStages, currentStageIndex]);
    }
    if (currentStageIndex < LISTING_STAGES.length - 1) {
      setCurrentStageIndex(currentStageIndex + 1);
    }
  };

  const handleStageClick = (stageIndex: number) => {
    if (completedStages.includes(stageIndex) || stageIndex <= currentStageIndex) {
      setCurrentStageIndex(stageIndex);
      if (scrollableContentRef.current) {
        scrollableContentRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
    }
  };

  const handleAddTradeCard = () => {
    if (tradeCards.length >= 8) {
      toast({
        title: "Maximum Reached",
        description: "You can only add up to 8 card requirements",
        variant: "destructive"
      });
      return;
    }
    const newId = (tradeCards.length + 1).toString();
    setTradeCards([...tradeCards, {
      id: newId,
      category: "any",
      minValue: 0
    }]);
  };

  const handleRemoveTradeCard = (id: string) => {
    if (tradeCards.length > 1) {
      setTradeCards(tradeCards.filter(card => card.id !== id));
    }
  };

  const handleUpdateTradeCard = (id: string, field: keyof TradeCard, value: any) => {
    setTradeCards(tradeCards.map(card => 
      card.id === id ? { ...card, [field]: value } : card
    ));
  };

  const handleSubmit = () => {
    const updateData: any = {
      listingType,
      couponDescription: additionalNote || null,
    };

    if (listingType === "sell") {
      updateData.sellingPrice = sellingPrice ? parseFloat(sellingPrice) : null;
      updateData.tradePreference = null;
      updateData.tradeNote = null;
    } else if (listingType === "trade") {
      const validTradeCards = tradeCards.filter(card => card.category && card.minValue > 0);
      if (validTradeCards.length > 0) {
        updateData.tradePreference = validTradeCards.map(card => card.category).join(", ");
        updateData.tradeNote = additionalNote || null;
      }
      updateData.sellingPrice = null;
    }

    updateListingMutation.mutate(updateData);
    setShowConfirmDialog(false);
  };

  const renderStageContent = () => {
    switch (currentStage.id) {
      case 'type':
        return (
          <div className="space-y-6">
            {/* Coupon Info Display */}
            {listing && (
              <div className="border border-white/20 bg-gradient-to-br from-white/10 to-white/5 p-5">
                <div className="flex items-start gap-3 mb-3">
                  <div className="w-10 h-10 border border-white/20 flex items-center justify-center shrink-0">
                    <Package className="h-5 w-5 text-white/60" strokeWidth={1} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="font-light text-white text-lg tracking-wide mb-1">
                      {listing.couponTitle}
                    </h3>
                    <p className="text-xs text-white/50 tracking-widest uppercase">
                      {listing.couponBrand}
                    </p>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3 pt-3 border-t border-white/10">
                  <div>
                    <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Value</p>
                    <p className="text-white font-light">
                      {listing.couponValueType === "percentage"
                        ? `${listing.couponValue}%`
                        : `₹${listing.couponValue}`}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] text-white/50 uppercase tracking-widest mb-1">Expires</p>
                    <p className="text-white font-light">
                      {new Date(listing.expiryDate).toLocaleDateString()}
                    </p>
                  </div>
                </div>
              </div>
            )}

            {/* Listing Type Selection */}
            <div>
              <Label className="text-white/60 text-xs uppercase tracking-wider mb-3 block">
                Select Listing Type *
              </Label>
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={() => setListingType("sell")}
                  className={cn(
                    "border p-6 transition-all text-center",
                    listingType === "sell"
                      ? "bg-white text-black border-white"
                      : "bg-white/5 border-white/20 hover:border-white/40"
                  )}
                  data-testid="button-type-sell"
                >
                  <ShoppingBag className={cn(
                    "h-8 w-8 mx-auto mb-2",
                    listingType === "sell" ? "text-black" : "text-white"
                  )} />
                  <div className="text-xl font-light mb-1">Cash In</div>
                  <div className="text-xs">Buyers can purchase with cash/UPI</div>
                </button>
                <button
                  onClick={() => setListingType("trade")}
                  className={cn(
                    "border p-6 transition-all text-center",
                    listingType === "trade"
                      ? "bg-white text-black border-white"
                      : "bg-white/5 border-white/20 hover:border-white/40"
                  )}
                  data-testid="button-type-trade"
                >
                  <Repeat className={cn(
                    "h-8 w-8 mx-auto mb-2",
                    listingType === "trade" ? "text-black" : "text-white"
                  )} />
                  <div className="text-xl font-light mb-1">Trade</div>
                  <div className="text-xs">Trade for other coupons</div>
                </button>
              </div>
            </div>

            {/* Additional Note */}
            <div>
              <Label className="text-white/60 text-xs uppercase tracking-wider mb-2 block flex items-center gap-2">
                <FileText className="h-3 w-3" />
                Additional Note (Optional)
              </Label>
              <Textarea
                value={additionalNote}
                onChange={(e) => {
                  if (e.target.value.length <= 150) {
                    setAdditionalNote(e.target.value);
                  }
                }}
                placeholder="Add any special instructions or notes about your listing..."
                className="bg-white/5 border-white/10 text-white rounded-none min-h-[100px] resize-none"
                data-testid="input-additional-note"
              />
              <p className="text-xs text-white/40 mt-1 text-right">
                {additionalNote.length}/150 characters
              </p>
            </div>
          </div>
        );

      case 'buy-details':
        return listingType === 'sell' ? (
          <div className="space-y-6">
            <div>
              <Label className="text-white/60 text-xs uppercase tracking-wider mb-2 block">
                Selling Price (₹) *
              </Label>
              <Input
                type="number"
                value={sellingPrice}
                onChange={(e) => setSellingPrice(e.target.value)}
                placeholder="Enter amount"
                className="bg-white/5 border-white/10 text-white rounded-none h-12 text-lg"
                data-testid="input-selling-price"
              />
              <p className="text-xs text-white/40 mt-2">
                Set the price buyers will pay for this coupon
              </p>
            </div>

            <div className="border border-white/20 bg-white/5 p-4">
              <div className="flex items-start gap-3 mb-3">
                <TrendingDown className="h-4 w-4 text-white/60 shrink-0 mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center justify-between mb-2">
                    <Label className="text-white text-sm font-normal">
                      Enable Auto Price Decrease
                    </Label>
                    <button
                      onClick={() => setEnableAutoDecrease(!enableAutoDecrease)}
                      className={cn(
                        "w-11 h-6 rounded-full transition-colors relative",
                        enableAutoDecrease ? "bg-white" : "bg-white/20"
                      )}
                      data-testid="toggle-auto-decrease"
                    >
                      <div className={cn(
                        "absolute top-0.5 w-5 h-5 rounded-full transition-all",
                        enableAutoDecrease
                          ? "right-0.5 bg-black"
                          : "left-0.5 bg-white"
                      )} />
                    </button>
                  </div>
                  <p className="text-xs text-white/50">
                    Automatically reduce price if no buyers after specified days
                  </p>
                </div>
              </div>

              {enableAutoDecrease && (
                <div className="grid grid-cols-2 gap-3 mt-4 pt-4 border-t border-white/10">
                  <div>
                    <Label className="text-white/60 text-xs mb-2 block">
                      Start After (Days)
                    </Label>
                    <Input
                      type="number"
                      value={offerStartDays}
                      onChange={(e) => setOfferStartDays(e.target.value)}
                      className="bg-white/5 border-white/10 text-white rounded-none h-10"
                      data-testid="input-start-days"
                    />
                  </div>
                  <div>
                    <Label className="text-white/60 text-xs mb-2 block">
                      Daily Decrease (%)
                    </Label>
                    <Input
                      type="number"
                      value={dailyDecreasePercent}
                      onChange={(e) => setDailyDecreasePercent(e.target.value)}
                      className="bg-white/5 border-white/10 text-white rounded-none h-10"
                      data-testid="input-decrease-percent"
                    />
                  </div>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            <div>
              <Label className="text-white/60 text-xs uppercase tracking-wider mb-3 block">
                What would you like to trade for? *
              </Label>
              <p className="text-xs text-white/40 mb-4">
                Specify categories and minimum values you're interested in (Max 8 cards)
              </p>
            </div>

            <div className="space-y-3">
              {tradeCards.map((card, index) => (
                <div
                  key={card.id}
                  className="border border-white/20 bg-white/5 p-4"
                  data-testid={`trade-card-${card.id}`}
                >
                  <div className="flex items-start gap-3">
                    <div className="flex-1 grid grid-cols-2 gap-3">
                      <div>
                        <Label className="text-white/60 text-xs mb-2 block">
                          Category
                        </Label>
                        <select
                          value={card.category}
                          onChange={(e) => handleUpdateTradeCard(card.id, 'category', e.target.value)}
                          className="w-full bg-white/5 border border-white/10 text-white rounded-none h-10 px-3 text-sm"
                          data-testid={`select-category-${card.id}`}
                        >
                          <option value="">Select...</option>
                          {categories.map(cat => (
                            <option key={cat.id} value={cat.id}>
                              {cat.label}
                            </option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <Label className="text-white/60 text-xs mb-2 block">
                          Min Value (₹)
                        </Label>
                        <Input
                          type="number"
                          value={card.minValue || ""}
                          onChange={(e) => handleUpdateTradeCard(card.id, 'minValue', parseInt(e.target.value) || 0)}
                          placeholder="0"
                          className="bg-white/5 border-white/10 text-white rounded-none h-10"
                          data-testid={`input-min-value-${card.id}`}
                        />
                      </div>
                    </div>
                    {tradeCards.length > 1 && (
                      <button
                        onClick={() => handleRemoveTradeCard(card.id)}
                        className="text-white/40 hover:text-white p-2 hover:bg-white/10 transition-all mt-6"
                        data-testid={`button-remove-card-${card.id}`}
                      >
                        <AlertCircle className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {tradeCards.length < 8 && (
              <Button
                onClick={handleAddTradeCard}
                className="w-full bg-white/10 text-white hover:bg-white/20 border border-white/20 rounded-none h-10"
                data-testid="button-add-trade-card"
              >
                + Add Another Card
              </Button>
            )}
          </div>
        );

      case 'review':
        return (
          <div className="space-y-6">
            <div className="border border-white/20 bg-gradient-to-br from-white/10 to-white/5 p-5">
              <p className="text-[10px] text-white/50 uppercase tracking-widest mb-4">
                Review Your Changes
              </p>

              <div className="space-y-4">
                <div>
                  <p className="text-xs text-white/50 mb-1">Listing Type</p>
                  <p className="text-white font-light">
                    {listingType === "sell" ? "Cash In (Sell)" : "Trade"}
                  </p>
                </div>

                {listingType === "sell" && sellingPrice && (
                  <div>
                    <p className="text-xs text-white/50 mb-1">Selling Price</p>
                    <p className="text-white font-light">₹{sellingPrice}</p>
                  </div>
                )}

                {listingType === "trade" && (
                  <div>
                    <p className="text-xs text-white/50 mb-2">Trade Requirements</p>
                    <div className="space-y-2">
                      {tradeCards
                        .filter(card => card.category && card.minValue > 0)
                        .map((card, index) => (
                          <div key={card.id} className="flex items-center gap-2 text-sm text-white/80">
                            <Badge className="bg-white/10 text-white border-white/20 rounded-none text-xs">
                              {index + 1}
                            </Badge>
                            <span>
                              {categories.find(c => c.id === card.category)?.label} - Min ₹{card.minValue}
                            </span>
                          </div>
                        ))}
                    </div>
                  </div>
                )}

                {additionalNote && (
                  <div>
                    <p className="text-xs text-white/50 mb-1">Additional Note</p>
                    <p className="text-white/80 text-sm">{additionalNote}</p>
                  </div>
                )}
              </div>
            </div>

            <div className="border border-yellow-500/20 bg-yellow-500/10 p-4">
              <div className="flex items-start gap-3">
                <AlertCircle className="h-5 w-5 text-yellow-400 shrink-0 mt-0.5" strokeWidth={1} />
                <div>
                  <p className="text-sm text-yellow-400 font-medium mb-1">Important</p>
                  <p className="text-xs text-white/60">
                    Updating your listing will immediately change how it appears to buyers. Make sure all details are correct before proceeding.
                  </p>
                </div>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  if (isLoading || !listing) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="text-center space-y-4">
          <Loader2 className="h-10 w-10 animate-spin mx-auto text-white/60" />
          <p className="text-white/60 text-sm">Loading listing details...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <button
            onClick={() => navigate("/coupex/my-listings")}
            className="text-white hover:text-white/80"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" strokeWidth={1} />
          </button>
          <h1 className="text-sm font-light tracking-wider">EDIT LISTING</h1>
          <div className="w-5" />
        </div>

        {/* Progress Bar */}
        <div className="h-1 bg-white/10">
          <div
            className="h-full bg-white transition-all duration-300"
            style={{ width: `${progressPercentage}%` }}
          />
        </div>

        {/* Stage Indicators */}
        <div className="flex items-center justify-between px-4 py-3 overflow-x-auto">
          {LISTING_STAGES.map((stage, index) => {
            const StageIcon = stage.icon;
            const isActive = index === currentStageIndex;
            const isCompleted = completedStages.includes(index);
            const isAccessible = completedStages.includes(index) || index <= currentStageIndex;

            return (
              <button
                key={stage.id}
                onClick={() => isAccessible && handleStageClick(index)}
                disabled={!isAccessible}
                className={cn(
                  "flex flex-col items-center gap-1 min-w-[70px] transition-all",
                  isAccessible ? "cursor-pointer" : "cursor-not-allowed opacity-40"
                )}
                data-testid={`stage-${stage.id}`}
              >
                <div className={cn(
                  "w-8 h-8 rounded-full border flex items-center justify-center transition-all",
                  isActive
                    ? "bg-white border-white"
                    : isCompleted
                      ? "bg-white/20 border-white"
                      : "bg-transparent border-white/20"
                )}>
                  {isCompleted && !isActive ? (
                    <CheckCircle className="h-4 w-4 text-white" strokeWidth={2} />
                  ) : (
                    <StageIcon className={cn(
                      "h-4 w-4",
                      isActive ? "text-black" : "text-white"
                    )} strokeWidth={1.5} />
                  )}
                </div>
                <span className={cn(
                  "text-[10px] tracking-wider font-light text-center",
                  isActive ? "text-white" : "text-white/50"
                )}>
                  {stage.shortTitle}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Main Content */}
      <div
        ref={scrollableContentRef}
        className="flex-1 pt-[180px] pb-32 px-4 overflow-y-auto"
      >
        <div className="max-w-2xl mx-auto">
          <div className="mb-6">
            <h2 className="text-2xl font-light tracking-wide mb-2 text-white">
              {currentStage.title}
            </h2>
            <p className="text-sm text-white/50">{currentStage.description}</p>
          </div>

          {renderStageContent()}
        </div>
      </div>

      {/* Fixed Bottom Button */}
      <div className="fixed bottom-0 left-0 right-0 z-40 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4">
        <div className="max-w-2xl mx-auto">
          <Button
            onClick={() => {
              if (currentStageIndex === LISTING_STAGES.length - 1) {
                setShowConfirmDialog(true);
              } else {
                handleNextStage();
              }
            }}
            disabled={updateListingMutation.isPending}
            className="w-full bg-white text-black hover:bg-white/90 rounded-none h-14 text-base font-light uppercase tracking-wider"
            data-testid="button-next-stage"
          >
            {currentStageIndex === LISTING_STAGES.length - 1 ? (
              updateListingMutation.isPending ? (
                <>
                  <Loader2 className="h-5 w-5 mr-2 animate-spin" />
                  UPDATING...
                </>
              ) : (
                "UPDATE LISTING"
              )
            ) : (
              <>
                CONTINUE
                <ArrowRight className="h-5 w-5 ml-2" strokeWidth={1} />
              </>
            )}
          </Button>
        </div>
      </div>

      {/* Confirmation Dialog */}
      <Dialog open={showConfirmDialog} onOpenChange={setShowConfirmDialog}>
        <DialogContent className="bg-black border-white/20 text-white rounded-none max-w-md">
          <DialogHeader>
            <DialogTitle className="text-xl font-light tracking-wide">
              Confirm Update
            </DialogTitle>
            <DialogDescription className="text-white/60 text-sm">
              Are you sure you want to update this listing? This will immediately change how it appears to buyers.
            </DialogDescription>
          </DialogHeader>
          <div className="border border-white/20 bg-white/5 p-4 my-4">
            <p className="text-xs text-white/50 mb-2">You're updating:</p>
            <p className="text-white font-light">{listing.couponTitle}</p>
          </div>
          <DialogFooter className="flex gap-3">
            <Button
              onClick={() => setShowConfirmDialog(false)}
              className="flex-1 bg-white/10 text-white hover:bg-white/20 rounded-none h-11"
              data-testid="button-cancel-update"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={updateListingMutation.isPending}
              className="flex-1 bg-white text-black hover:bg-white/90 rounded-none h-11"
              data-testid="button-confirm-update"
            >
              {updateListingMutation.isPending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Updating...
                </>
              ) : (
                "Confirm Update"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

