            </div>

            <Separator className="bg-white/10" />

            {/* Consultation Modes */}
            <div>
              <p className="text-white/60 text-xs uppercase tracking-widest mb-2">Consultation Mode</p>
              <div className="space-y-2">
                <div className="flex gap-2">
