          >
            {currentStageIndex === BOOKING_STAGES.length - 1 ? (
              createBookingMutation.isPending ? (
                <>PROCESSING...</>
              ) : (
                <>
                  {paymentMode === 'prepaid' ? `PAY ${formatCurrency(totalAmount)}` : 'CONFIRM BOOKING'}
                </>
              )
            ) : (
              <>
                NEXT
                <ArrowRight className="h-5 w-5 ml-2" />
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

shared/coupon-value-calculator.ts.content:
import { differenceInDays } from "date-fns";

interface CouponValueParams {
  couponValue: number;
  couponValueType: string;
  couponBrand: string;
  couponCategory: string;
  expiryDate: string | Date;
  minAmount?: number;
  maxDiscount?: number;
}

// Brand reliability scores (1-10)
const BRAND_SCORES: Record<string, number> = {
  amazon: 10,
  flipkart: 9.5,
  myntra: 9,
  swiggy: 9.5,
  zomato: 9,
  makemytrip: 8.5,
  "booking.com": 8.5,
  uber: 9,
  paytm: 8.5,
  phonepe: 8.5,
  gpay: 9,
  "google pay": 9,
  netflix: 10,
  spotify: 9.5,
  prime: 10,
  hotstar: 9,
  // Add more as needed
};

// Category popularity scores (1-10)
const CATEGORY_SCORES: Record<string, number> = {
  food: 9,
  travel: 8.5,
  shopping: 9.5,
  bills: 7.5,
  entertainment: 8,
  all: 10, // Universal coupons are most valuable
};

/**
 * Calculate coupon value score (1-10) based on multiple factors:
 * - Worth/Value (30%): Actual monetary value of the coupon
 * - Brand Reliability (25%): How reliable and popular the brand is
 * - Category Demand (20%): How in-demand the category is
 * - Expiry/Freshness (15%): Days until expiry
 * - Usage Flexibility (10%): Min amount and restrictions
 */
export function calculateCouponValueScore(params: CouponValueParams): number {
  const {
    couponValue,
    couponValueType,
    couponBrand,
    couponCategory,
    expiryDate,
    minAmount,
    maxDiscount,
  } = params;

  // 1. Worth Score (0-10) - 30% weight
  let worthScore = 0;
  if (couponValueType === "percentage") {
    // Percentage discounts: scale based on percentage
    if (couponValue >= 50) worthScore = 10;
    else if (couponValue >= 40) worthScore = 9;
    else if (couponValue >= 30) worthScore = 8;
    else if (couponValue >= 20) worthScore = 7;
    else if (couponValue >= 15) worthScore = 6;
    else if (couponValue >= 10) worthScore = 5;
    else if (couponValue >= 5) worthScore = 3;
    else worthScore = 2;

    // Adjust based on max discount cap
    if (maxDiscount) {
      if (maxDiscount >= 2000) worthScore = Math.min(10, worthScore + 1);
      else if (maxDiscount < 200) worthScore = Math.max(1, worthScore - 2);
    }
  } else {
    // Fixed amount discounts: scale based on rupee value
    if (couponValue >= 2000) worthScore = 10;
    else if (couponValue >= 1500) worthScore = 9;
    else if (couponValue >= 1000) worthScore = 8.5;
    else if (couponValue >= 750) worthScore = 7.5;
    else if (couponValue >= 500) worthScore = 6.5;
    else if (couponValue >= 300) worthScore = 5.5;
    else if (couponValue >= 200) worthScore = 4.5;
    else if (couponValue >= 100) worthScore = 3.5;
    else if (couponValue >= 50) worthScore = 2.5;
    else worthScore = 1.5;
  }

  // 2. Brand Reliability Score (0-10) - 25% weight
  const brandLower = couponBrand.toLowerCase();
  let brandScore = BRAND_SCORES[brandLower] || 6; // Default to mid-tier

  // Check for partial matches
  if (brandScore === 6) {
    for (const [brand, score] of Object.entries(BRAND_SCORES)) {
      if (brandLower.includes(brand) || brand.includes(brandLower)) {
        brandScore = score;
        break;
      }
    }
  }

  // 3. Category Demand Score (0-10) - 20% weight
  const categoryLower = couponCategory.toLowerCase();
  const categoryScore = CATEGORY_SCORES[categoryLower] || 6;

  // 4. Expiry/Freshness Score (0-10) - 15% weight
  const daysUntilExpiry = differenceInDays(new Date(expiryDate), new Date());
  let expiryScore = 0;
  if (daysUntilExpiry >= 90) expiryScore = 10;
  else if (daysUntilExpiry >= 60) expiryScore = 9;
  else if (daysUntilExpiry >= 45) expiryScore = 8;
  else if (daysUntilExpiry >= 30) expiryScore = 7;
  else if (daysUntilExpiry >= 21) expiryScore = 6;
  else if (daysUntilExpiry >= 14) expiryScore = 5;
  else if (daysUntilExpiry >= 7) expiryScore = 3;
  else if (daysUntilExpiry >= 3) expiryScore = 2;
  else if (daysUntilExpiry >= 0) expiryScore = 1;
  else expiryScore = 0; // Expired

  // 5. Usage Flexibility Score (0-10) - 10% weight
  let flexibilityScore = 10; // Start with perfect score
  if (minAmount) {
    // Penalize based on minimum order requirement
    if (minAmount >= 5000) flexibilityScore = 4;
    else if (minAmount >= 3000) flexibilityScore = 5;
    else if (minAmount >= 2000) flexibilityScore = 6;
    else if (minAmount >= 1000) flexibilityScore = 7;
    else if (minAmount >= 500) flexibilityScore = 8;
    else if (minAmount >= 200) flexibilityScore = 9;
  }

  // Calculate weighted average
  const finalScore =
    worthScore * 0.3 +
    brandScore * 0.25 +
    categoryScore * 0.2 +
    expiryScore * 0.15 +
    flexibilityScore * 0.1;

  // Round to 1 decimal place and ensure it's between 1 and 10
  return Math.max(1, Math.min(10, Math.round(finalScore * 10) / 10));
}

/**
 * Get value score badge color and label
 */
export function getValueScoreBadge(score: number): {
  color: string;
  label: string;
  bgClass: string;
  textClass: string;
  borderClass: string;
} {
  if (score >= 9) {
    return {
      color: "diamond",
      label: "Diamond",
      bgClass: "bg-purple-500/20",
      textClass: "text-purple-300",
      borderClass: "border-purple-500/30",
    };
  } else if (score >= 8) {
    return {
      color: "gold",
      label: "Gold",
      bgClass: "bg-yellow-500/20",
      textClass: "text-yellow-300",
      borderClass: "border-yellow-500/30",
    };
  } else if (score >= 6.5) {
    return {
      color: "silver",
      label: "Silver",
      bgClass: "bg-gray-400/20",
      textClass: "text-gray-300",
      borderClass: "border-gray-400/30",
    };
  } else if (score >= 5) {
    return {
      color: "bronze",
      label: "Bronze",
      bgClass: "bg-orange-600/20",
      textClass: "text-orange-400",
      borderClass: "border-orange-600/30",
    };
  } else {
    return {
      color: "basic",
      label: "Basic",
      bgClass: "bg-white/10",
      textClass: "text-white/60",
      borderClass: "border-white/20",
    };
  }
}

client/src/pages/coupex-trade.tsx.content:
import { useState, useEffect } from "react";
import { useAuth } from "@/hooks/use-auth";
import { useLocation, useRoute } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { Card } from "@/components/ui/card";
import { format, differenceInDays } from "date-fns";
import { getBrandImage } from "@/lib/brand-images";
import {
  ArrowLeft,
  Calendar,
  Tag,
  AlertCircle,
  Repeat,
  CheckCircle2,
  Info
} from "lucide-react";

interface Listing {
  id: string;
  userId: string;
  couponCode: string;
  couponTitle: string;
  couponBrand: string;
  couponCategory: string;
  couponType: string;
  couponValue: string;
  couponValueType: string;
  couponDescription?: string;
  expiryDate: string;
  minAmount?: string;
  maxDiscount?: string;
  tradePreference?: string;
  tradeNote?: string;
  status: string;
  views: number;
  createdAt: string;
}

export default function CoupExTrade() {
  const { user, isAuthenticated } = useAuth();
  const [, navigate] = useLocation();
  const [, params] = useRoute("/coupex/trade/:id");
  const { toast } = useToast();
  const [selectedCouponId, setSelectedCouponId] = useState<string>("");
  const [offerNote, setOfferNote] = useState("");

  const listingId = params?.id || "";

  useEffect(() => {
    if (!isAuthenticated) {
      navigate("/");
    }
  }, [isAuthenticated, navigate]);

  // Fetch the listing we want to trade with
  const { data: targetListing, isLoading: listingLoading } = useQuery<Listing>({
    queryKey: ["/api/coupex/listings", listingId],
    enabled: !!listingId,
  });

  // Fetch user's own listings that can be traded
  const { data: myListings = [], isLoading: myListingsLoading } = useQuery<Listing[]>({
    queryKey: ["/api/coupex/my-listings"],
    enabled: isAuthenticated,
  });

  // Prevent trading with own listing
  useEffect(() => {
    if (targetListing && user && targetListing.userId === user.id) {
      toast({
        title: "Cannot Trade",
        description: "You cannot trade with your own listing.",
        variant: "destructive",
      });
      navigate("/coupex");
    }
  }, [targetListing, user, navigate, toast]);

  const createTradeOfferMutation = useMutation({
    mutationFn: async (data: {
      listingId: string;
      offererId: string;
      listingOwnerId: string;
      offeredCouponCode: string;
      offeredCouponTitle: string;
      offeredCouponBrand: string;
      offeredCouponValue: string;
      offeredCouponExpiry: string;
      offerNote?: string;
    }) => {
      return apiRequest("POST", "/api/coupex/trade-offer", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/coupex/trade-offers"] });
      toast({
        title: "Trade Offer Sent",
        description: "Your trade offer has been sent successfully. The seller will be notified.",
      });
      navigate("/coupex");
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to send trade offer. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleSubmitTradeOffer = () => {
    if (!selectedCouponId) {
      toast({
        title: "Select a Coupon",
        description: "Please select a coupon to offer for trade.",
        variant: "destructive",
      });
      return;
    }

    if (!user?.id || !targetListing) return;

    const selectedCoupon = myListings.find(l => l.id === selectedCouponId);
    if (!selectedCoupon) return;

    createTradeOfferMutation.mutate({
      listingId: targetListing.id,
      offererId: user.id,
      listingOwnerId: targetListing.userId,
      offeredCouponCode: selectedCoupon.couponCode,
      offeredCouponTitle: selectedCoupon.couponTitle,
      offeredCouponBrand: selectedCoupon.couponBrand,
      offeredCouponValue: selectedCoupon.couponValue,
      offeredCouponExpiry: selectedCoupon.expiryDate,
      offerNote: offerNote || undefined,
    });
  };

  const getDaysUntilExpiry = (dateString: string) => {
    return differenceInDays(new Date(dateString), new Date());
  };

  const isExpiringSoon = (dateString: string) => {
    const days = getDaysUntilExpiry(dateString);
    return days <= 7 && days > 0;
  };

  // Filter coupons that match the seller's trade preferences
  const getMatchingCoupons = () => {
    if (!targetListing?.tradePreference) {
      // If no preference specified, show all active coupons
      return myListings.filter(
        l => l.status === "active" && getDaysUntilExpiry(l.expiryDate) > 0
      );
    }

    const preference = targetListing.tradePreference.toLowerCase();
    return myListings.filter(listing => {
      if (listing.status !== "active") return false;
      if (getDaysUntilExpiry(listing.expiryDate) <= 0) return false;

      // Check if brand or category matches the preference
      const brand = listing.couponBrand.toLowerCase();
      const category = listing.couponCategory.toLowerCase();
      const title = listing.couponTitle.toLowerCase();

      return (
        preference.includes(brand) ||
        preference.includes(category) ||
        brand.includes(preference) ||
        category.includes(preference) ||
        title.includes(preference)
      );
    });
  };

  const matchingCoupons = getMatchingCoupons();
  const otherCoupons = myListings.filter(
    l => !matchingCoupons.includes(l) && l.status === "active" && getDaysUntilExpiry(l.expiryDate) > 0
  );

  if (listingLoading || myListingsLoading) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin" />
          <p className="text-white/60 text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  if (!targetListing) {
    return (
      <div className="min-h-screen bg-black text-white flex items-center justify-center px-4">
        <div className="text-center">
          <AlertCircle className="h-16 w-16 mx-auto mb-4 text-white/40" strokeWidth={1} />
          <p className="text-white/60">Listing not found</p>
          <Button
            onClick={() => navigate("/coupex")}
            className="mt-4 bg-white text-black hover:bg-white/90"
          >
            Back to CoupEx
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white pb-32">
      {/* Fixed Header */}
      <div className="fixed top-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-b border-white/10">
        <div className="flex items-center justify-between py-4 px-4">
          <button
            onClick={() => navigate(`/coupex/listing/${listingId}`)}
            className="text-white hover:text-white/80"
            data-testid="button-back"
          >
            <ArrowLeft className="h-5 w-5" strokeWidth={1} />
          </button>
          <h1 className="text-sm font-bold tracking-wider absolute left-1/2 -translate-x-1/2">
            PROPOSE TRADE
          </h1>
          <div className="w-5" />
        </div>
      </div>

      {/* Main Content */}
      <div className="pt-16 px-4 space-y-6">
        {/* What They Want */}
        <div>
          <h2 className="text-xs font-bold tracking-widest uppercase text-white/50 mb-4 flex items-center gap-2">
            <Tag className="h-3.5 w-3.5" strokeWidth={1} />
            They're Looking For
          </h2>
          <Card className="bg-white/5 border-white/10 rounded-none p-4">
            <div className="space-y-3">
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1">
                  <h3 className="text-base font-light text-white mb-1">
                    {targetListing.couponTitle}
                  </h3>
                  <p className="text-xs text-white/50 uppercase tracking-widest">
                    {targetListing.couponBrand}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-lg font-light text-white">
                    {targetListing.couponValueType === "percentage"
                      ? `${targetListing.couponValue}%`
                      : `₹${targetListing.couponValue}`}
                  </p>
                  <p className="text-[10px] text-white/40 uppercase">Value</p>
                </div>
              </div>

              {targetListing.tradePreference && (
                <div className="pt-3 border-t border-white/10">
                  <p className="text-xs text-white/40 uppercase tracking-widest mb-1">
                    Preferred Trade
                  </p>
                  <p className="text-sm text-white/80">{targetListing.tradePreference}</p>
                </div>
              )}

              {targetListing.tradeNote && (
                <div className="pt-3 border-t border-white/10">
                  <p className="text-xs text-white/40 uppercase tracking-widest mb-1">Note</p>
                  <p className="text-sm text-white/60">{targetListing.tradeNote}</p>
                </div>
              )}
            </div>
          </Card>
        </div>

        {/* Your Matching Coupons */}
        {matchingCoupons.length > 0 && (
          <div>
            <h2 className="text-xs font-bold tracking-widest uppercase text-white/50 mb-4 flex items-center gap-2">
              <CheckCircle2 className="h-3.5 w-3.5" strokeWidth={1} />
              Matching Coupons ({matchingCoupons.length})
            </h2>
            <div className="space-y-3">
              {matchingCoupons.map((coupon) => {
                const daysLeft = getDaysUntilExpiry(coupon.expiryDate);
                const expiring = isExpiringSoon(coupon.expiryDate);

                return (
                  <Card
                    key={coupon.id}
                    onClick={() => setSelectedCouponId(coupon.id)}
                    className={`cursor-pointer transition-all border-2 ${
                      selectedCouponId === coupon.id
                        ? "bg-white/10 border-white"
                        : "bg-white/5 border-white/10 hover:border-white/30"
                    } rounded-none`}
                    data-testid={`card-coupon-${coupon.id}`}
                  >
                    <div className="p-4 space-y-3">
                      <div className="flex items-start justify-between gap-3">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge className="bg-green-500/20 text-green-400 border-green-500/20 rounded-none text-[10px] uppercase">
                              Match
                            </Badge>
                            {expiring && (
                              <Badge className="bg-red-500/20 text-red-400 border-red-500/20 rounded-none text-[10px] uppercase">
                                {daysLeft}d Left
                              </Badge>
                            )}
                          </div>
                          <h3 className="text-base font-light text-white mb-1">
                            {coupon.couponTitle}
                          </h3>
                          <p className="text-xs text-white/50 uppercase tracking-widest">
                            {coupon.couponBrand}
                          </p>
                        </div>
                        <div className="text-right">
                          <p className="text-lg font-light text-white">
                            {coupon.couponValueType === "percentage"
                              ? `${coupon.couponValue}%`
                              : `₹${coupon.couponValue}`}
                          </p>
                          <p className="text-[10px] text-white/40 uppercase">Value</p>
                        </div>
                      </div>

                      <div className="flex items-center justify-between pt-2 border-t border-white/10">
                        <span className="text-xs text-white/40 uppercase tracking-widest">
                          Expires
                        </span>
                        <span className={`text-xs font-semibold ${expiring ? "text-red-400" : "text-white/60"}`}>
                          {format(new Date(coupon.expiryDate), "dd MMM yyyy")}
                        </span>
                      </div>
                    </div>
                  </Card>
                );
              })}
            </div>
          </div>
        )}

        {/* Other Available Coupons */}
        {otherCoupons.length > 0 && (
          <div>
            <h2 className="text-xs font-bold tracking-widest uppercase text-white/50 mb-4 flex items-center gap-2">
              <Info className="h-3.5 w-3.5" strokeWidth={1} />
              Other Coupons ({otherCoupons.length})
            </h2>
            <div className="space-y-3">
              {otherCoupons.map((coupon) => {
                const daysLeft = getDaysUntilExpiry(coupon.expiryDate);
                const expiring = isExpiringSoon(coupon.expiryDate);

                return (
                  <Card
                    key={coupon.id}
                    onClick={() => setSelectedCouponId(coupon.id)}
                    className={`cursor-pointer transition-all border ${
                      selectedCouponId === coupon.id
                        ? "bg-white/10 border-white"
                        : "bg-white/5 border-white/10 hover:border-white/30"
                    } rounded-none`}
                    data-testid={`card-coupon-${coupon.id}`}
                  >
                    <div className="p-4 space-y-3">
                      <div className="flex items-start justify-between gap-3">
                        <div className="flex-1">
                          {expiring && (
                            <div className="mb-2">
                              <Badge className="bg-red-500/20 text-red-400 border-red-500/20 rounded-none text-[10px] uppercase">
                                {daysLeft}d Left
                              </Badge>
                            </div>
                          )}
                          <h3 className="text-base font-light text-white mb-1">
                            {coupon.couponTitle}
                          </h3>
                          <p className="text-xs text-white/50 uppercase tracking-widest">
                            {coupon.couponBrand}
                          </p>
                        </div>
                        <div className="text-right">
                          <p className="text-lg font-light text-white">
                            {coupon.couponValueType === "percentage"
                              ? `${coupon.couponValue}%`
                              : `₹${coupon.couponValue}`}
                          </p>
                          <p className="text-[10px] text-white/40 uppercase">Value</p>
                        </div>
                      </div>

                      <div className="flex items-center justify-between pt-2 border-t border-white/10">
                        <span className="text-xs text-white/40 uppercase tracking-widest">
                          Expires
                        </span>
                        <span className={`text-xs font-semibold ${expiring ? "text-red-400" : "text-white/60"}`}>
                          {format(new Date(coupon.expiryDate), "dd MMM yyyy")}
                        </span>
                      </div>
                    </div>
                  </Card>
                );
              })}
            </div>
          </div>
        )}

        {/* No Coupons Available */}
        {matchingCoupons.length === 0 && otherCoupons.length === 0 && (
          <Card className="bg-white/5 border-white/10 rounded-none p-8">
            <div className="text-center space-y-4">
              <AlertCircle className="h-12 w-12 mx-auto text-white/40" strokeWidth={1} />
              <div>
                <h3 className="text-base font-light text-white mb-2">No Coupons Available</h3>
                <p className="text-sm text-white/60">
                  You don't have any active coupons to trade. Create a listing first to start trading.
                </p>
              </div>
              <Button
                onClick={() => navigate("/coupex/new-listing")}
                className="bg-white text-black hover:bg-white/90 rounded-none"
                data-testid="button-create-listing"
              >
                Create Listing
              </Button>
            </div>
          </Card>
        )}

        {/* Add Note */}
        {(matchingCoupons.length > 0 || otherCoupons.length > 0) && (
          <div>
            <h2 className="text-xs font-bold tracking-widest uppercase text-white/50 mb-4">
              Add a Note (Optional)
            </h2>
            <Textarea
              value={offerNote}
              onChange={(e) => setOfferNote(e.target.value)}
              placeholder="Add any additional information about your offer..."
              className="bg-white/5 border-white/10 text-white placeholder:text-white/30 rounded-none min-h-[100px] focus:border-white/30"
              data-testid="input-offer-note"
            />
          </div>
        )}

        {/* Info Box */}
        <Card className="bg-blue-500/10 border-blue-500/20 rounded-none p-4">
          <div className="flex items-start gap-3">
            <Info className="h-5 w-5 text-blue-400 shrink-0 mt-0.5" strokeWidth={1} />
            <div>
              <p className="text-sm font-semibold text-blue-400 mb-1">How Trading Works</p>
              <p className="text-xs text-blue-300/80 leading-relaxed">
                Select one of your coupons to offer in exchange. The seller will review your offer 
                and can accept or reject it. Both coupon codes will be revealed only after the trade is accepted.
              </p>
            </div>
          </div>
        </Card>
      </div>

      {/* Fixed Bottom Action */}
      {(matchingCoupons.length > 0 || otherCoupons.length > 0) && (
        <div className="fixed bottom-0 left-0 right-0 z-50 bg-black/95 backdrop-blur-xl border-t border-white/10 p-4">
          <Button
            onClick={handleSubmitTradeOffer}
            disabled={!selectedCouponId || createTradeOfferMutation.isPending}
            className="w-full bg-white text-black hover:bg-white/90 rounded-none h-12 text-base font-light uppercase tracking-wider disabled:opacity-50 disabled:cursor-not-allowed"
            data-testid="button-submit-trade-offer"
          >
            {createTradeOfferMutation.isPending ? (
              "Sending Offer..."
            ) : (
              <>
                <Repeat className="h-5 w-5 mr-2" strokeWidth={1} />
                Send Trade Offer
              </>
            )}
          </Button>
        </div>
      )}
    </div>
  );
}

