    return dummyOffers[id] || null;
  };

  const { data: offerData, isLoading, error } = useQuery<OfferDataResponse>({
    queryKey: ["/api/coupon-mart/trade-offers", offerId],
    queryFn: async () => {
      // Check if this is a dummy offer first
