                  data-testid="button-confirm-brands"
                >
                  Done {currentCard.brands.length > 0 && `(${currentCard.brands.length})`}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        );
      })()}
    </div>
  );
}

